(window.TKA_DATA=window.TKA_DATA||{})["bank-biologi"]={"id":"biologi","name":"Biologi","count":226,"items":[{"id":"0.0.0","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.1 Tingkat keanekaragaman hayati: gen, jenis, ekosistem","kind":"pg","stem":"Kelompok organisme berikut yang menunjukkan keanekaragaman hayati pada TINGKAT JENIS (spesies) adalah…","options":["Padi Rojolele, Padi Ciherang, dan Padi IR64","Kucing Anggora, Kucing Persia, dan Kucing Kampung","Jeruk Nipis (Citrus aurantifolia), Jeruk Bali (Citrus maxima), dan Jeruk Keprok (Citrus reticulata)","Durian Montong, Durian Petruk, dan Durian Musang King"],"key":[2],"why":"Jeruk Nipis, Jeruk Bali, dan Jeruk Keprok adalah tiga spesies berbeda di dalam satu genus Citrus, sehingga termasuk keanekaragaman tingkat jenis. Tiga opsi lainnya adalah varietas/ras dalam satu spesies yang sama (tingkat gen).","src":"kuis"},{"id":"0.0.1","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.1 Tingkat keanekaragaman hayati: gen, jenis, ekosistem","kind":"pg","stem":"Perkawinan silang buatan antara Kuda betina (2n = 64) dan Keledai jantan (2n = 62) menghasilkan keturunan bernama Bagal (Mule) yang memiliki 63 kromosom dan bersifat mandul (steril). Hal ini membuktikan bahwa kuda dan keledai…","options":["Merupakan satu spesies yang sama tetapi berbeda varietas","Berbeda pada tingkat filum dan kelas","Merupakan dua spesies berbeda dalam satu genus Equus yang dibatasi oleh isolasi reproduksi pasca-zigotik (sterilitas hibrida)","Mengalami keanekaragaman tingkat ekosistem"],"key":[2],"why":"Dua organisme disebut berbeda spesies apabila tidak dapat menghasilkan keturunan yang fertil. Jumlah kromosom ganjil (2n = 63) pada Bagal menyebabkan kromosom gagal berpasangan homolog saat Profase I Meiosis.","src":"kuis"},{"id":"0.0.2","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.1 Tingkat keanekaragaman hayati: gen, jenis, ekosistem","kind":"pg","stem":"Faktor utama yang menyebabkan munculnya keanekaragaman hayati tingkat ekosistem antara Hutan Hujan Tropis Kalimantan, Rawa Gambut Riau, dan Padang Sabana Nusa Tenggara Timur adalah…","options":["Interaksi antara perbedaan faktor abiotik (curah hujan, pH tanah, iklim) dengan komposisi komunitas biotik yang beradaptasi di dalamnya","Perbedaan urutan basa nitrogen pada mitokondria satu spesies pohon","Mutasi titik pada gen klorofil rumput","Persilangan antarvarietas padi lokal"],"key":[0],"why":"Keanekaragaman tingkat ekosistem terbentuk dari interaksi spesifik antara variasi faktor fisik-kimia lingkungan (abiotik) dengan komunitas makhluk hidup (biotik) yang menyusunnya.","src":"kuis"},{"id":"0.1.0","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.2 Ekologi kuantitatif: indeks Shannon-Wiener, kemerataan & dominansi","kind":"pg","stem":"Nilai Indeks Keanekaragaman Shannon-Wiener (H') suatu ekosistem hutan akan mencapai nilai tertinggi apabila…","options":["Hanya ada satu spesies pohon yang jumlahnya jutaan batang","Seluruh predator puncak dihilangkan dari hutan","Jumlah spesies (kekayaan spesies S) sangat banyak dan jumlah individu tiap spesies terdistribusi secara merata (Evenness mendekati 1)","Indeks Dominansi Simpson (D) bernilai 0,99"],"key":[2],"why":"Indeks Shannon-Wiener (H') berbanding lurus dengan kekayaan spesies (S) dan kemerataan distribusi individu antarspesies (Evenness E), serta berbanding terbalik dengan dominansi tunggal (D).","src":"kuis"},{"id":"0.1.1","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.2 Ekologi kuantitatif: indeks Shannon-Wiener, kemerataan & dominansi","kind":"pg","stem":"Konversi hutan hujan tropis primer di Sumatra menjadi perkebunan kelapa sawit monokultur akan mengubah parameter ekologi kuantitatif wilayah tersebut menjadi…","options":["Kemerataan spesies (E) menjadi 1,0 sempurna untuk 500 spesies pohon","Kekayaan spesies (S) meningkat sepuluh kali lipat","Indeks Shannon-Wiener (H') naik di atas 3,5 dan Indeks Dominansi (D) turun mendekati 0","Indeks Shannon-Wiener (H') turun drastis (< 1,0) dan Indeks Dominansi Simpson (D) naik mendekati 1,0"],"key":[3],"why":"Perkebunan monokultur didominasi secara mutlak oleh 1 spesies tanaman (Elaeis guineensis), sehingga nilai dominansi D mendekati 1 dan indeks keanekaragaman H' anjlok mendekati 0.","src":"kuis"},{"id":"0.1.2","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.2 Ekologi kuantitatif: indeks Shannon-Wiener, kemerataan & dominansi","kind":"pg","stem":"Sebuah komunitas padang lamun memiliki tepat 4 spesies lamun dengan jumlah individu masing-masing spesies sama persis (masing-masing 25% dari total populasi). Berapakah nilai Indeks Dominansi Simpson (D = Σ p<sub>i</sub>²) komunitas tersebut?","options":["0,75","0,25","0,50","1,00"],"key":[1],"why":"Karena terdapat 4 spesies dengan proporsi masing-masing p<sub>i</sub> = 0,25 (1/4), maka D = 4 × (0,25)² = 4 × 0,0625 = 0,25.","src":"kuis"},{"id":"0.2.0","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.3 Biogeografi Indonesia: Garis Wallace, Weber & Lydekker","kind":"pg","stem":"Garis imajiner biogeografi yang memisahkan kawasan Fauna Asiatis (Paparan Sunda) dengan kawasan Fauna Peralihan (Wallacea) dan melewati Selat Makassar serta Selat Lombok adalah…","options":["Garis Lydekker","Garis Wallace","Garis Khatulistiwa","Garis Weber"],"key":[1],"why":"Garis Wallace (1859) membentang dari Selat Lombok menuju Selat Makassar hingga selatan Filipina, menjadi batas timur Paparan Sunda.","src":"kuis"},{"id":"0.2.1","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.3 Biogeografi Indonesia: Garis Wallace, Weber & Lydekker","kind":"pg","stem":"Kawasan biogeografi Wallacea (Zona Peralihan yang mencakup Sulawesi, Nusa Tenggara, dan Maluku) terletak di antara dua garis batas biogeografi, yaitu…","options":["Di antara Sumatra dan Kalimantan","Di sebelah barat Garis Wallace dan sebelah timur Garis Lydekker","Di sebelah timur Pulau Papua","Di antara Garis Wallace (di sisi barat) dan Garis Lydekker (di sisi timur), serta dibelah di tengahnya oleh Garis Weber"],"key":[3],"why":"Batas barat zona Wallacea adalah Garis Wallace (tepi Paparan Sunda) dan batas timurnya adalah Garis Lydekker (tepi Paparan Sahul), sementara Garis Weber berada di bagian dalam Wallacea sebagai garis keseimbangan 50:50.","src":"kuis"},{"id":"0.2.2","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.3 Biogeografi Indonesia: Garis Wallace, Weber & Lydekker","kind":"pg","stem":"Berdasarkan teori biogeografi pulau MacArthur dan Wilson, sebuah pulau vulkanik baru akan memiliki jumlah spesies (kekayaan spesies ekuilibrium) paling BANYAK apabila pulau tersebut…","options":["Berukuran sangat kecil dan terletak sangat jauh dari benua utama","Berukuran luas (menurunkan laju kepunahan) dan terletak dekat dengan daratan benua utama (menaikkan laju imigrasi)","Tertutup seluruhnya oleh lapisan es","Berukuran kecil dan sering mengalami letusan gunung berapi"],"key":[1],"why":"Pulau yang luas menyediakan lebih banyak relung dan populasi besar (laju kepunahan rendah), sedangkan jarak yang dekat dengan benua utama mempercepat kedatangan spesies kolonis (laju imigrasi tinggi).","src":"kuis"},{"id":"0.3.0","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.4 Karakteristik flora Malesiana & fauna endemik Indonesia","kind":"pg","stem":"Manakah pasangan wilayah dan kelompok satwa endemik Indonesia berikut yang 100% tepat sesuai zona biogeografinya?","options":["Zona Wallacea (Peralihan): Anoa, Babirusa, Tarsius, Burung Maleo, dan Komodo","Zona Australis: Kanguru Pohon, Burung Cendrawasih, dan Badak Bercula Satu","Zona Wallacea: Gajah Kalimantan, Jalak Bali, dan Walabi","Zona Asiatis: Harimau Sumatra, Orangutan Tapanuli, dan Burung Kasuari"],"key":[0],"why":"Anoa, Babirusa, Tarsius, dan Maleo adalah endemik Sulawesi, sedangkan Komodo adalah endemik NTT. Kedua wilayah tersebut merupakan inti dari kawasan Wallacea (Peralihan).","src":"kuis"},{"id":"0.3.1","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.4 Karakteristik flora Malesiana & fauna endemik Indonesia","kind":"pg","stem":"Perbedaan mendasar secara botani antara bunga Padma Raksasa (Rafflesia arnoldii) dan Bunga Bangkai Raksasa (Amorphophallus titanum) yang tumbuh di hutan hujan Sumatra adalah…","options":["Keduanya merupakan spesies yang sama persis hanya berbeda umur","Rafflesia arnoldii melakukan fotosintesis CAM di malam hari","Rafflesia arnoldii memiliki batang tinggi menjulang dan umbi besar, sedangkan Amorphophallus titanum merambat di pohon","Rafflesia arnoldii adalah tumbuhan holoparasit obligat tanpa akar, batang, dan daun berklorofil (hidup di dalam jaringan akar liana Tetrastigma); sedangkan Amorphophallus titanum adalah tumbuhan berumbi dari famili Araceae yang memiliki fase vegetatif berdaun hijau dan perbungaan majemuk (spadix) menjulang tinggi"],"key":[3],"why":"Rafflesia arnoldii tidak memiliki klorofil, akar, batang, maupun daun (holoparasit pada liana Tetrastigma). Sebaliknya Amorphophallus titanum memiliki umbi raksasa dan memiliki fase berdaun hijau (fotosintesis Mandiri) yang bergantian dengan fase berbunga majemuk.","src":"kuis"},{"id":"0.3.2","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.4 Karakteristik flora Malesiana & fauna endemik Indonesia","kind":"pg","stem":"Ciri khas komunitas Flora Malesiana yang mendominasi kanopi hutan hujan tropis dataran rendah di Pulau Kalimantan dan Sumatra (Zona Barat) serta memiliki buah bersayap dua adalah pohon-pohon dari famili…","options":["Myrtaceae (Eucalyptus dan Matoa)","Dipterocarpaceae (seperti Meranti / Shorea, Keruing, dan Kapur)","Cactaceae (kaktus gurun)","Poaceae (rumput-rumputan)"],"key":[1],"why":"Hutan hujan tropis dataran rendah Paparan Sunda (Kalimantan & Sumatra) didominasi oleh pohon raksasa penghasil kayu komersial dari famili Dipterocarpaceae (Meranti, Keruing, Kamper, Balau).","src":"kuis"},{"id":"0.4.0","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.5 Prinsip taksonomi, hierarki takson & tata nama binomial","kind":"pg","stem":"Dalam tata nama botani internasional (ICN), akhiran kata Latin '-ales' (misalnya Poales, Zingiberales, Rosales) dan akhiran '-aceae' (misalnya Poaceae, Zingiberaceae, Rosaceae) secara berurutan menunjukkan tingkat takson…","options":["Ordo (Bangsa) dan Familia (Suku)","Divisio dan Kelas","Kelas dan Ordo","Familia (Suku) dan Genus (Marga)"],"key":[0],"why":"Pada tumbuhan, akhiran baku untuk Ordo adalah -ales (Zingiberales) dan akhiran baku untuk Familia adalah -aceae (Zingiberaceae).","src":"kuis"},{"id":"0.4.1","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.5 Prinsip taksonomi, hierarki takson & tata nama binomial","kind":"pg","stem":"Manakah penulisan nama ilmiah untuk Harimau Sumatra (subspesies dari harimau Asia) dan Jagung berikut yang 100% mematuhi aturan Binomial/Trinomial Nomenclature?","options":["<u>Panthera tigris</u> dan <u>Zea Mays</u>","panthera tigris sondaica dan zea mays","<i>Panthera tigris sondaica</i> dan <i>Zea mays</i>","Panthera Tigris Sondaica dan Zea Mays"],"key":[2],"why":"Huruf kapital HANYA digunakan pada huruf pertama kata pertama (nama Genus: Panthera dan Zea), sedangkan kata kedua (spesies: tigris, mays) dan kata ketiga (subspesies: sondaica) ditulis dengan huruf kecil seluruhnya dan dicetak miring.","src":"kuis"},{"id":"0.4.2","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.5 Prinsip taksonomi, hierarki takson & tata nama binomial","kind":"pg","stem":"Apabila kita menelusuri tingkatan takson dari Kingdom menuju ke arah Species, maka perubahan karakteristik kelompok yang terjadi adalah…","options":["Perbedaan genetik antar-individu semakin besar","Keanekaragaman ekosistem semakin luas","Jumlah anggota semakin banyak dan persamaan ciri semakin sedikit","Jumlah anggota semakin sedikit, tetapi jumlah persamaan ciri homolog semakin banyak dan kekerabatan semakin dekat"],"key":[3],"why":"Semakin rendah tingkat takson (menuju Species), cakupan anggotanya semakin menyempit (sedikit) tetapi kesamaan anatomi, fisiologi, dan genetiknya semakin banyak.","src":"kuis"},{"id":"0.5.0","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.6 Kunci determinasi dikotomis & taksonomi numerik (fenetik)","kind":"pg","stem":"Berdasarkan kunci determinasi pada contoh soal di atas, urutan nomor kuplet yang tepat untuk mengidentifikasi Komodo (Varanus komodoensis) dan Udang Windu (Penaeus monodon) secara berurutan adalah…","options":["Komodo: 1b – 4a | Udang: 1a – 5a","Komodo: 1a – 2a – 4a | Udang: 1b – 5a","Komodo: 1a – 2b – 3b | Udang: 1b – 5b","Komodo: 1a – 2b – 4a | Udang: 1b – 5a"],"key":[3],"why":"Komodo adalah Reptilia (Vertebrata 1a → Poikiloterm 2b → Bersisik tanduk kering 4a). Udang Windu adalah Crustacea/Arthropoda (Invertebrata 1b → Tubuh & kaki berbuku-buku 5a).","src":"kuis"},{"id":"0.5.1","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.6 Kunci determinasi dikotomis & taksonomi numerik (fenetik)","kind":"pg","stem":"Dalam studi taksonomi numerik (fenetik), dua spesimen tumbuhan diamati terhadap 10 karakter morfologi. Sebanyak 6 karakter sama-sama dimiliki oleh kedua spesimen (a = 6), 2 karakter hanya dimiliki spesimen pertama (b = 2), dan 2 karakter hanya dimiliki spesimen kedua (c = 2). Berapakah nilai Koefisien Kemiripan Jaccard [S<sub>J</sub> = a / (a + b + c)] antara kedua spesimen tersebut?","options":["1,00 (100%)","0,20 (20%)","0,40 (40%)","0,60 (60%)"],"key":[3],"why":"Koefisien Jaccard S<sub>J</sub> = a / (a + b + c) = 6 / (6 + 2 + 2) = 6 / 10 = 0,60 atau 60%.","src":"kuis"},{"id":"0.5.2","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.6 Kunci determinasi dikotomis & taksonomi numerik (fenetik)","kind":"pg","stem":"Prinsip utama dalam menyusun setiap kuplet (pasangan pernyataan bernomor a dan b) pada kunci determinasi dikotomis yang baik adalah…","options":["Setiap kuplet harus terdiri atas minimal lima pernyataan pilihan","Menggunakan sifat yang subjektif seperti 'berukuran cukup indah' atau 'berbau agak harum'","Setiap kuplet harus terdiri atas dua pernyataan karakter yang saling berlawanan (kontras/eksklusif) dan terukur secara objektif sehingga spesimen hanya cocok pada salah satu cabang","Mengurutkan spesies berdasarkan abjad nama daerahnya"],"key":[2],"why":"Kata 'dikotomis' berarti terbagi dua: setiap kuplet wajib menyajikan dua ciri yang saling bertentangan secara tegas (misal 'berbiji terbuka' vs 'berbiji tertutup').","src":"kuis"},{"id":"0.6.0","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.7 Kladistika, pohon filogenetik & evolusi 5 Kingdom ke 3 Domain","kind":"pg","stem":"Dalam sebuah kladogram, suatu kelompok taksonomi yang mencakup satu leluhur bersama (MRCA) beserta SELURUH spesies keturunannya tanpa ada satu pun cabang keturunan yang dikeluarkan disebut kelompok…","options":["Fenotipik konvergen","Parafiletik","Polifiletik","Monofiletik (Clade sejati)"],"key":[3],"why":"Kelompok Monofiletik adalah satu-satunya unit takson yang valid dalam kladistika karena mencakup leluhur bersama dan seluruh keturunannya.","src":"kuis"},{"id":"0.6.1","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.7 Kladistika, pohon filogenetik & evolusi 5 Kingdom ke 3 Domain","kind":"pg","stem":"Sayap Kelelawar (tersusun atas kerangka jari tulang mamalia berlapis kulit patagium) dan Sayap Kupu-kupu (tersusun atas lembaran kitin epidermis tanpa tulang) memiliki fungsi yang sama untuk terbang. Dalam analisis evolusi dan kladistika, kedua struktur tersebut merupakan contoh dari…","options":["Struktur Homolog akibat divergensi dari satu leluhur bersayap","Organ vestigial yang tidak berfungsi","Struktur Analog (Homoplasi) hasil evolusi konvergen karena adaptasi fungsi yang sama, sehingga tidak boleh dipakai untuk menyatukan keduanya dalam satu klad","Sinapomorfi utama kelas Aves"],"key":[2],"why":"Kemiripan fungsi dari struktur yang asal-usul anatomi dan embriologinya sama sekali berbeda disebut Analogi (evolusi konvergen). Kladogram hanya boleh disusun dari karakter Homologi.","src":"kuis"},{"id":"0.6.2","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.7 Kladistika, pohon filogenetik & evolusi 5 Kingdom ke 3 Domain","kind":"pg","stem":"Carl Woese mengusulkan sistem klasifikasi 3 Domain (Bacteria, Archaea, Eukarya) yang memecah Kingdom Monera menjadi dua domain terpisah. Karakteristik biokimia unik yang dimiliki oleh Domain Archaea tetapi TIDAK dimiliki oleh Domain Bacteria adalah…","options":["Memiliki dinding sel dari peptidoglikan tebal dan membran berikatan ester","Dinding sel TIDAK mengandung peptidoglikan (melainkan pseudomurein/protein S-layer), lipid membran berikatan ETER bercabang yang tahan kondisi ekstrem, serta memiliki protein mirip histon","Memiliki membran inti ganda dan organel mitokondria","Menghasilkan spora seksual basidiospora"],"key":[1],"why":"Archaea tidak memiliki peptidoglikan pada dinding selnya, memiliki ikatan eter hidrokarbon bercabang pada membran plasmanya (membuatnya tahan suhu >100°C di kawah hidrotermal atau kadar garam tinggi), dan mesin transkripsi/translasinya mirip Eukarya.","src":"kuis"},{"id":"0.7.0","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.8 Ancaman biodiversitas (HIPPO), fragmentasi & konservasi di Indonesia","kind":"pg","stem":"Manakah di antara pasangan tempat pelestarian berikut yang KEDUANYA merupakan bentuk Konservasi IN-SITU (di dalam habitat asli)?","options":["Kebun Raya Bogor dan Taman Safari Cisarua","Kebun Raya Purwodadi dan Taman Nasional Komodo","Kebun Binatang Ragunan dan Suaka Margasatwa Way Kambas","Taman Nasional Ujung Kulon (Banten) dan Cagar Alam Rafflesia (Bengkulu)"],"key":[3],"why":"Taman Nasional, Cagar Alam, dan Suaka Margasatwa adalah kawasan Konservasi In-Situ (di habitat asli). Kebun Raya, Kebun Binatang, dan Taman Safari adalah Konservasi Ex-Situ.","src":"kuis"},{"id":"0.7.1","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.8 Ancaman biodiversitas (HIPPO), fragmentasi & konservasi di Indonesia","kind":"pg","stem":"Perbedaan mendasar antara Cagar Alam dan Taman Nasional dalam regulasi konservasi di Indonesia adalah…","options":["Taman Nasional boleh ditebang kayunya secara komersial","Cagar Alam berada di luar habitat asli, sedangkan Taman Nasional di dalam habitat asli","Cagar Alam memiliki perlindungan suksesi alami paling ketat dan TERTUTUP untuk kegiatan wisata rekreasi umum; sedangkan Taman Nasional menerapkan sistem zonasi (zona inti, rimba, pemanfaatan) sehingga zona pemanfaatannya dapat digunakan untuk ekowisata dan edukasi","Cagar Alam hanya melindungi hewan laut, sedangkan Taman Nasional hanya melindungi burung"],"key":[2],"why":"Cagar Alam hanya boleh dimasuki dengan izin khusus untuk riset/pendidikan tanpa mengubah ekosistem, sedangkan Taman Nasional memiliki Zona Pemanfaatan untuk ekowisata terbatas.","src":"kuis"},{"id":"0.7.2","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"1.8 Ancaman biodiversitas (HIPPO), fragmentasi & konservasi di Indonesia","kind":"pg","stem":"Ketika sebuah kawasan hutan hujan tropis yang luas terpotong-potong oleh jaringan jalan raya menjadi sepuluh petak hutan kecil yang saling terpisah (fragmentasi habitat), dampak ekologis langsung yang terjadi pada petak-petak kecil tersebut adalah…","options":["Menurunnya suhu udara dan meningkatnya kelembapan di tepi hutan","Meningkatnya populasi predator puncak seperti Harimau Sumatra karena ruang berburu makin sempit","Meningkatnya Efek Tepi (Edge Effect) yang mematikan pohon hutan dalam, serta terputusnya aliran gen (gene flow) antarpopulasi satwa yang memicu perkawinan sedarah (inbreeding depression)","Meningkatnya keanekaragaman genetik di setiap petak"],"key":[2],"why":"Fragmentasi memperbesar proporsi tepi hutan yang panas/kering (edge effect) dan mengisolasi sub-populasi satwa sehingga memicu inbreeding depression. Solusinya adalah membangun koridor satwa (wildlife corridor).","src":"kuis"},{"id":"1.0.0","topic":"Bakteri & Resistensi","sub":"2.1 Ultrastruktur sel prokariotik: kapsul, dinding, nukleoid & plasmid","kind":"pg","stem":"Sel bakteri (prokariotik) tidak memiliki organel mitokondria, namun bakteri aerob seperti Azotobacter dan Mycobacterium tuberculosis tetap mampu menghasilkan hingga 38 ATP per molekul glukosa melalui fosforilasi oksidatif karena…","options":["Dinding peptidoglikan mengubah cahaya menjadi ATP","Bakteri menggunakan ribosom 70S untuk memompa proton","Plasmid bakteri dapat berubah menjadi mitokondria saat ada oksigen","Enzim rantai transpor elektron (sitokrom) dan ATP sintase tertanam langsung pada membran plasma dan lipatan mesosom bakteri"],"key":[3],"why":"Pada sel prokariotik, fungsi membran dalam mitokondria (tempat rantai transpor elektron dan kemiosmosis proton) dijalankan langsung oleh membran plasma dan invaginasi mesosom.","src":"kuis"},{"id":"1.0.1","topic":"Bakteri & Resistensi","sub":"2.1 Ultrastruktur sel prokariotik: kapsul, dinding, nukleoid & plasmid","kind":"pg","stem":"Struktur ekstra-kromosomal pada sitoplasma bakteri yang berbentuk DNA sirkuler untai ganda berukuran kecil, mampu bereplikasi secara mandiri, dan sering membawa gen ketahanan terhadap antibiotik (gen R) adalah…","options":["Nukleoid","Plasmid","Pilus seks","Kapsul polisakarida"],"key":[1],"why":"Plasmid adalah molekul dsDNA sirkuler kecil di luar kromosom utama (nukleoid) yang membawa gen-gen aksesori penting seperti resistensi antibiotik (R-plasmid) dan digunakan sebagai vektor kloning gen.","src":"kuis"},{"id":"1.0.2","topic":"Bakteri & Resistensi","sub":"2.1 Ultrastruktur sel prokariotik: kapsul, dinding, nukleoid & plasmid","kind":"pg","stem":"Galur bakteri Streptococcus pneumoniae yang memiliki Kapsul polisakarida tebal bersifat ganas (virulen) dan menyebabkan pneumonia, sedangkan galur mutan yang tidak berkapsul bersifat jinak (avirulen) karena kapsul berfungsi untuk…","options":["Melindungi sel bakteri dari penelanan dan penghancuran (fagositosis) oleh sel darah putih makrofag dan neutrofil inang","Menghasilkan ATP melalui fotosintesis","Menyimpan cadangan udara saat menyelam","Memompa keluar molekul air saat pembelahan biner"],"key":[0],"why":"Kapsul glikokaliks yang licin dan bermuatan negatif menghalangi perlekatan reseptor fagositosis leukosit inang, sehingga bakteri berkapsul lolos dari lini pertahanan tubuh.","src":"kuis"},{"id":"1.1.0","topic":"Bakteri & Resistensi","sub":"2.2 Morfologi koloni, susunan flagela & mekanisme endospora","kind":"pg","stem":"Perhatikan lima tipe susunan flagela pada sel bakteri! Bakteri seperti Escherichia coli dan Salmonella typhi yang memiliki banyak flagela tersebar merata di SELURUH permukaan tubuhnya diklasifikasikan memiliki tipe flagela…","options":["Amfitrik","Monotrik","Peritrik","Lofotrik"],"key":[2],"why":"Atrik = tanpa flagela; Monotrik = 1 di satu ujung; Lofotrik = seberkas di satu ujung; Amfitrik = di kedua ujung; Peritrik = tersebar di seluruh permukaan keliling sel.","src":"kuis"},{"id":"1.1.1","topic":"Bakteri & Resistensi","sub":"2.2 Morfologi koloni, susunan flagela & mekanisme endospora","kind":"pg","stem":"Pasangan bentuk morfologi sel bakteri dan contoh spesies patogennya berikut yang BENAR adalah…","options":["Diplokokus (bulat berpasangan dua) — Treponema pallidum penyebab sifilis","Vibrio (batang melengkung seperti tanda koma) — Vibrio cholerae penyebab kolera","Spirokaeta (spiral ulir lentur) — Staphylococcus aureus","Stafilokokus (bulat bergerombol seperti anggur) — Escherichia coli"],"key":[1],"why":"Vibrio cholerae berbentuk batang melengkung seperti koma (vibrio); Treponema pallidum berbentuk spirokaeta; Staphylococcus aureus berbentuk kokus bergerombol seperti anggur; dan E. coli berbentuk basil (batang).","src":"kuis"},{"id":"1.1.2","topic":"Bakteri & Resistensi","sub":"2.2 Morfologi koloni, susunan flagela & mekanisme endospora","kind":"pg","stem":"Pernyataan yang tepat mengenai fungsi biologis pembentukan ENDOSPORA pada bakteri genus Clostridium dan Bacillus adalah…","options":["Merupakan organel untuk menangkap energi cahaya matahari","Merupakan kapsid protein untuk menginfeksi sel tumbuhan","Merupakan struktur dormansi pertahanan diri untuk bertahan hidup melewati cekaman panas, kekeringan, dan zat kimia ekstrem tanpa menambah jumlah individu (1 sel vegetatif → 1 endospora → 1 sel vegetatif)","Merupakan alat reproduksi seksual untuk menghasilkan 4 sel anak baru yang bervariasi"],"key":[2],"why":"Endospora bakteri BUKAN alat reproduksi karena tidak menambah jumlah sel! Satu sel vegetatif membentuk tepat satu endospora saat kondisi buruk, dan berkecambah kembali menjadi satu sel saat kondisi membaik.","src":"kuis"},{"id":"1.2.0","topic":"Bakteri & Resistensi","sub":"2.3 Dinding sel & mekanisme pewarnaan Gram positif vs Gram negatif","kind":"pg","stem":"Perbedaan struktural utama pada dinding sel yang menyebabkan bakteri Gram Positif tetap berwarna ungu sedangkan bakteri Gram Negatif berubah menjadi tak berwarna setelah dicuci dengan alkohol 95% adalah…","options":["Bakteri Gram positif memiliki lapisan peptidoglikan sangat tebal (20–80 nm) dan asam teikoat yang pori-porinya menyempit saat terdehidrasi alkohol sehingga mengunci kompleks CV-I; sedangkan bakteri Gram negatif memiliki membran luar kaya lipid (LPS) yang larut oleh alkohol dan lapisan peptidoglikan yang sangat tipis (2–7 nm)","Bakteri Gram positif tidak menyerap kristal violet sama sekali","Bakteri Gram positif memiliki membran luar lipopolisakarida tebal yang menolak alkohol","Bakteri Gram negatif tidak memiliki membran plasma"],"key":[0],"why":"Alkohol 95% bekerja ganda: mendehidrasi jaring peptidoglikan tebal milik Gram (+) sehingga porinya merapat mengunci kompleks ungu CV-I, namun melarutkan lipid membran luar milik Gram (−) sehingga CV-I bocor keluar.","src":"kuis"},{"id":"1.2.1","topic":"Bakteri & Resistensi","sub":"2.3 Dinding sel & mekanisme pewarnaan Gram positif vs Gram negatif","kind":"pg","stem":"Mengapa infeksi aliran darah (sepsis) oleh bakteri Gram Negatif sering kali memicu komplikasi syok septik (demam tinggi mendadak dan penurunan tekanan darah drastis) jika bakterinya pecah (lisis) secara masif?","options":["Karena bakteri Gram negatif melepaskan asam teikoat yang membekukan darah","Karena bakteri Gram negatif memiliki endospora yang menyumbat kapiler otak","Karena ribosom 70S bakteri berubah menjadi virus","Karena membran luar dinding bakteri Gram negatif mengandung Lipopolisakarida (LPS), di mana komponen Lipid A-nya bekerja sebagai ENDOTOKSIN yang memicu makrofag melepaskan badai sitokin (TNF-α dan IL-1)"],"key":[3],"why":"Lipopolisakarida (LPS) pada membran luar bakteri Gram negatif mengandung Lipid A (Endotoksin) yang baru terlepas saat dinding bakteri pecah dan memicu respons inflamasi sistemik ekstrem.","src":"kuis"},{"id":"1.2.2","topic":"Bakteri & Resistensi","sub":"2.3 Dinding sel & mekanisme pewarnaan Gram positif vs Gram negatif","kind":"pg","stem":"Bakteri penyebab penyakit Tuberkulosis (Mycobacterium tuberculosis) sulit diwarnai dengan pewarnaan Gram biasa dan harus diidentifikasi menggunakan pewarnaan Ziehl-Neelsen (Bakteri Tahan Asam / BTA) karena dinding selnya dilapisi oleh zat lilin hidrofobik tebal, yaitu…","options":["Kolesterol murni","Asam Mikolat (Mycolic acid)","Pseudomurein","Kitin dan selulosa"],"key":[1],"why":"Genus Mycobacterium memiliki lapisan Asam Mikolat (zat lilin rantai panjang) yang terikat pada arabinogalaktan-peptidoglikan, membuatnya tahan terhadap pelunturan asam-alkohol (BTA positif).","src":"kuis"},{"id":"1.3.0","topic":"Bakteri & Resistensi","sub":"2.4 Fisiologi nutrisi, respirasi & kurva pertumbuhan bakteri","kind":"pg","stem":"Pemberian antibiotik golongan β-laktam (seperti Penisilin dan Amoksisilin) paling efektif membunuh populasi bakteri apabila diberikan saat kultur bakteri sedang berada pada…","options":["Fase Lag (Adaptasi) awal","Akhir Fase Stasioner saat bakteri telah membentuk endospora","Fase Eksponensial (Log), karena pada fase ini bakteri sedang sangat aktif membelah dan mensintesis ikatan silang peptidoglikan baru yang menjadi target kerja penisilin","Fase Kematian"],"key":[2],"why":"Penisilin bekerja menghambat enzim transpeptidase yang merakit dinding peptidoglikan baru. Oleh karena itu, penisilin paling mematikan saat bakteri sedang giat membelah diri di Fase Log.","src":"kuis"},{"id":"1.3.1","topic":"Bakteri & Resistensi","sub":"2.4 Fisiologi nutrisi, respirasi & kurva pertumbuhan bakteri","kind":"pg","stem":"Perbedaan mendasar antara fotosintesis yang dilakukan oleh Cyanobacteria (seperti Anabaena) dengan fotosintesis yang dilakukan oleh Bakteri Ungu Belerang (Chromatium) adalah…","options":["Chromatium memiliki kloroplas bermembran ganda, sedangkan Cyanobacteria tidak","Chromatium menghasilkan glukosa dari pemecahan protein daging","Cyanobacteria bersifat kemoautotrof yang tidak membutuhkan cahaya","Cyanobacteria menggunakan H2O sebagai donor elektron dan menghasilkan gas O2 (oksigenik), sedangkan Chromatium menggunakan H2S secara anaerob dan menghasilkan endapan belerang (S) tanpa menghasilkan gas O2 (anoksigenik)"],"key":[3],"why":"Cyanobacteria memiliki klorofil-a dan melakukan fotolisis H2O menghasilkan O2. Sebaliknya, bakteri fotoautotrof anoksigenik (bakteri ungu/hijau sulfur) menggunakan bakteriklorofil dan memecah H2S menjadi belerang (S) tanpa melepaskan O2.","src":"kuis"},{"id":"1.3.2","topic":"Bakteri & Resistensi","sub":"2.4 Fisiologi nutrisi, respirasi & kurva pertumbuhan bakteri","kind":"pg","stem":"Bakteri Clostridium botulinum akan langsung mati apabila terpapar oksigen atmosfer karena tergolong bakteri anaerob obligat yang…","options":["Memiliki mitokondria yang pecah bila terkena udara","Membutuhkan gas oksigen untuk membakar dinding selnya sendiri","Tidak memiliki enzim Superoksida Dismutase (SOD) dan enzim Katalase untuk mendetoksifikasi radikal bebas superoksida (O2•−) dan hidrogen peroksida (H2O2) yang terbentuk saat ada oksigen","Hanya dapat hidup di permukaan daun yang terkena sinar matahari"],"key":[2],"why":"Oksigen memicu terbentuknya radikal bebas superoksida dan H2O2 yang merusak enzim dan DNA sel. Bakteri anaerob obligat tidak memiliki enzim SOD dan Katalase sehingga mati keracunan radikal oksigen.","src":"kuis"},{"id":"1.4.0","topic":"Bakteri & Resistensi","sub":"2.5 Reproduksi biner & rekombinasi genetik (transformasi, transduksi, konjugasi)","kind":"pg","stem":"Pada eksperimen klasik Frederick Griffith (1928), bakteri Streptococcus pneumoniae galur R (tidak berkapsul, jinak) yang hidup berubah menjadi galur S (berkapsul, ganas) setelah dicampur dengan bangkai galur S yang telah dimatikan dengan pemanasan. Peristiwa perubahan sifat genetik akibat penyerapan fragmen DNA bebas dari medium ini disebut…","options":["Transformasi","Pembelahan biner","Transduksi umum","Konjugasi"],"key":[0],"why":"Penyerapan molekul DNA telanjang (bebas) dari lingkungan sekitar oleh sel bakteri yang kompeten disebut Transformasi.","src":"kuis"},{"id":"1.4.1","topic":"Bakteri & Resistensi","sub":"2.5 Reproduksi biner & rekombinasi genetik (transformasi, transduksi, konjugasi)","kind":"pg","stem":"Mekanisme rekombinasi genetik pada bakteri yang melibatkan peran virus penginfeksi bakteri (Bakteriofag) sebagai vektor pembawa potongan DNA dari bakteri donor ke bakteri resipien adalah…","options":["Konjugasi","Fragmentasi","Transduksi","Transformasi"],"key":[2],"why":"Transduksi adalah perpindahan materi genetik antar-bakteri dengan perantara kapsid virus bakteriofag (baik melalui daur litik/transduksi umum maupun daur lisogenik/transduksi khusus).","src":"kuis"},{"id":"1.4.2","topic":"Bakteri & Resistensi","sub":"2.5 Reproduksi biner & rekombinasi genetik (transformasi, transduksi, konjugasi)","kind":"pg","stem":"Dalam proses konjugasi antara bakteri E. coli donor yang memiliki Plasmid F (sel F⁺) dengan bakteri resipien yang tidak memiliki Plasmid F (sel F⁻), struktur permukaan spesifik yang menjulur dari sel F⁺ untuk menarik sel F⁻ dan membentuk saluran transfer DNA adalah…","options":["Kapsul asam mikolat","Endospora","Flagela peritrik","Pilus seks (F-pilus)"],"key":[3],"why":"Plasmid F mengkode pembentukan Pilus Seks (F-pilus) yang mengenali dan menarik sel F⁻ hingga terbentuk jembatan konjugasi sitoplasma.","src":"kuis"},{"id":"1.5.0","topic":"Bakteri & Resistensi","sub":"2.6 Mekanisme kerja antibiotik & strategi molekuler resistensi bakteri","kind":"pg","stem":"Manakah di antara pasangan jenis antibiotik dan mekanisme target kerjanya pada sel bakteri berikut yang TEPAT?","options":["Penisilin & Sefalosporin — menghambat replikasi DNA girase di nukleoid","Kloramfenikol — melarutkan membran luar fosfolipid bilayer manusia","Tetrasiklin & Streptomisin — berikatan pada subunit 30S ribosom 70S bakteri sehingga menghambat sintesis protein (translasi)","Sulfonamida — memecah ikatan peptidoglikan seperti enzim lisozim"],"key":[2],"why":"Tetrasiklin dan Streptomisin bekerja menghambat subunit kecil (30S) pada ribosom 70S bakteri. Penisilin menghambat sintesis dinding peptidoglikan; Kloramfenikol menghambat subunit 50S ribosom; dan Sulfonamida menghambat sintesis asam folat (bersaing dengan PABA).","src":"kuis"},{"id":"1.5.1","topic":"Bakteri & Resistensi","sub":"2.6 Mekanisme kerja antibiotik & strategi molekuler resistensi bakteri","kind":"pg","stem":"Beberapa galur bakteri Gram negatif seperti Pseudomonas aeruginosa dan Escherichia coli menjadi kebal (resisten) terhadap antibiotik Tetrasiklin dengan cara memproduksi protein transpor aktif di membran selnya yang terus-menerus membuang molekul obat keluar dari sitoplasma sebelum obat sempat mengikat ribosom. Mekanisme resistensi ini disebut…","options":["Transduksi bakteriofag","Pembentukan kapsul endospora","Pompa Efluks (Efflux Pump)","Inaktivasi enzimatik beta-laktamase"],"key":[2],"why":"Mekanisme memompa keluar molekul antibiotik secara aktif dari dalam sitoplasma kembali ke luar sel disebut Pompa Efluks (Efflux Pump).","src":"kuis"},{"id":"1.5.2","topic":"Bakteri & Resistensi","sub":"2.6 Mekanisme kerja antibiotik & strategi molekuler resistensi bakteri","kind":"pg","stem":"Mengapa bakteri Mycoplasma pneumoniae (penyebab pneumonia atipikal) secara alami 100% resisten (kebal) terhadap pemberian antibiotik Penisilin dan Amoksisilin?","options":["Karena Mycoplasma hidup di luar tubuh manusia","Karena Mycoplasma melakukan fotosintesis","Karena Mycoplasma memiliki ribosom 80S seperti sel manusia","Karena Mycoplasma secara alami TIDAK memiliki dinding sel peptidoglikan, sehingga tidak memiliki target kerja bagi antibiotik golongan beta-laktam"],"key":[3],"why":"Antibiotik golongan β-laktam (Penisilin, Amoksisilin) bekerja spesifik menghambat pembentukan dinding peptidoglikan. Karena Mycoplasma tidak memiliki dinding sel sama sekali, obat tersebut tidak berefek.","src":"kuis"},{"id":"1.6.0","topic":"Bakteri & Resistensi","sub":"2.7 Peranan bakteri bagi manusia: bioteknologi, industri, pertanian & patogen","kind":"pg","stem":"Perhatikan tabel pasangan spesies bakteri dan peranannya bagi kehidupan manusia berikut! Pasangan yang 100% BENAR adalah…","options":["Clostridium tetani — menghasilkan antibiotik streptomisin","Acetobacter aceti — mengubah air kelapa menjadi serat Nata de coco","Rhizobium leguminosarum — mengubah nitrit menjadi nitrat secara bebas di udara","Propionibacterium shermanii — menghasilkan asam propionat dan gas CO2 pembentuk lubang pada pembuatan Keju Swiss, serta vitamin B12"],"key":[3],"why":"Propionibacterium shermanii adalah bakteri pembuat keju Swiss dan penghasil vitamin B12. Pembuat Nata de coco adalah Acetobacter xylinum (bukan A. aceti); Rhizobium menambat N2 menjadi NH3 di bintil akar; dan penghasil streptomisin adalah Streptomyces griseus.","src":"kuis"},{"id":"1.6.1","topic":"Bakteri & Resistensi","sub":"2.7 Peranan bakteri bagi manusia: bioteknologi, industri, pertanian & patogen","kind":"pg","stem":"Seorang pasien mengalami gejala muntah dan diare cair yang sangat parah dengan feses berwarna putih keruh seperti 'air cucian beras' setelah mengonsumsi air minum yang tidak dimasak di daerah banjir. Bakteri patogen penyebab penyakit ini beserta bentuk morfologinya adalah…","options":["Treponema pallidum (berbentuk spirokaeta)","Corynebacterium diphtheriae (berbentuk batang gada)","Salmonella typhi (berbentuk basil peritrik)","Vibrio cholerae (berbentuk batang melengkung seperti tanda koma / vibrio dengan flagela monotrik)"],"key":[3],"why":"Diare profus seperti air cucian beras (rice-water stool) yang memicu dehidrasi berat adalah gejala khas penyakit Kolera yang disebabkan oleh enterotoksin bakteri Vibrio cholerae.","src":"kuis"},{"id":"1.6.2","topic":"Bakteri & Resistensi","sub":"2.7 Peranan bakteri bagi manusia: bioteknologi, industri, pertanian & patogen","kind":"pg","stem":"Dalam siklus nitrogen di lahan pertanian, petani menanam tanaman kacang-kacangan (Leguminosae) secara tumpangsari atau rotasi tanaman karena pada bintil akar tanaman tersebut hidup bakteri simbiotik yang mampu mereduksi gas N2 atmosfer menjadi amonia (NH3), yaitu…","options":["Pseudomonas denitrificans","Rhizobium leguminosarum","Acetobacter xylinum","Thiobacillus ferrooxidans"],"key":[1],"why":"Bakteri Rhizobium leguminosarum bersimbiosis mutualisme di dalam bintil akar tanaman polong-polongan (Leguminosae/Fabaceae) dan memiliki enzim nitrogenase untuk memfiksasi N2 udara menjadi NH3.","src":"kuis"},{"id":"2.0.0","topic":"Ekosistem Indonesia","sub":"3.1 Komponen ekosistem, relung ekologi (niche) & dekomposer vs detritivor","kind":"pg","stem":"Perbedaan mendasar antara peran Detritivor (seperti cacing tanah, luwing, dan teripang) dengan Dekomposer (seperti bakteri dan jamur saprofit) dalam ekosistem adalah…","options":["Detritivor melakukan fotosintesis, sedangkan dekomposer melakukan kemosintesis","Detritivor menelan dan mencacah serpihan organik mati (detritus) secara mekanis di saluran cerna, sedangkan dekomposer menguraikan molekul organik secara enzimatik ekstraseluler menjadi ion-ion mineral anorganik (mineralisasi)","Dekomposer berada pada tingkat trofik pertama, sedangkan detritivor adalah predator puncak","Detritivor hanya hidup di laut, sedangkan dekomposer hanya hidup di darat"],"key":[1],"why":"Detritivor memakan partikel detritus secara mekanis, sedangkan dekomposer (bakteri & fungi) melakukan mineralisasi yang mengubah bahan organik kembali menjadi unsur hara anorganik bagi tumbuhan.","src":"kuis"},{"id":"2.0.1","topic":"Ekosistem Indonesia","sub":"3.1 Komponen ekosistem, relung ekologi (niche) & dekomposer vs detritivor","kind":"pg","stem":"Istilah ekologi yang mendeskripsikan secara lengkap totalitas peran fungsional suatu spesies di dalam komunitasnya—mencakup jenis makanannya, waktu aktifnya, rentang toleransi suhu/pH, serta posisinya dalam jaring-jaring makanan—disebut…","options":["Relung Ekologi (Ecological Niche)","Bioma terestrial","Suksesi primer","Habitat fisik"],"key":[0],"why":"Habitat adalah tempat tinggal fisik ('alamat'), sedangkan Relung Ekologi (Niche) adalah peran fungsional dan status trofik ('profesi') spesies tersebut di dalam ekosistem.","src":"kuis"},{"id":"2.0.2","topic":"Ekosistem Indonesia","sub":"3.1 Komponen ekosistem, relung ekologi (niche) & dekomposer vs detritivor","kind":"pg","stem":"Di ekosistem danau yang dalam atau samudra terbuka, zona perairan permukaan hingga kedalaman sekitar 200 meter yang masih dapat ditembus oleh cahaya matahari dengan intensitas cukup untuk melangsungkan fotosintesis fitoplankton disebut…","options":["Zona Abisal","Zona Bentik dalam","Zona Afotik","Zona Fotik (Eufotik)"],"key":[3],"why":"Zona Fotik adalah lapisan kolom air bagian atas (0–200 m) di mana laju fotosintesis melebihi laju respirasi karena penetrasi cahaya matahari masih mencukupi.","src":"kuis"},{"id":"2.1.0","topic":"Ekosistem Indonesia","sub":"3.2 Tipe ekosistem khas Indonesia: mangrove, gambut, hutan hujan & karang","kind":"pg","stem":"Urutan zonasi vegetasi hutan mangrove di Indonesia apabila ditelusuri mulai dari garis pantai terdepan yang berhadapan langsung dengan ombak laut menuju ke arah daratan/hulu muara air payau adalah…","options":["Avicennia & Sonneratia (berakar napas) → Rhizophora (berakar tunjang) → Bruguiera (berakar lutut) → Nypa fruticans (nipah)","Rhizophora → Pinus → Eucalyptus → Avicennia","Bruguiera → Avicennia → Nypa → Rhizophora","Nypa → Bruguiera → Rhizophora → Avicennia"],"key":[0],"why":"Ingat rumus urutan mangrove dari laut ke darat: A-S-R-B-N (Avicennia/Sonneratia di paling depan → Rhizophora di tengah → Bruguiera di belakang → Nypa di tepi sungai payau).","src":"kuis"},{"id":"2.1.1","topic":"Ekosistem Indonesia","sub":"3.2 Tipe ekosistem khas Indonesia: mangrove, gambut, hutan hujan & karang","kind":"pg","stem":"Pernyataan yang tepat mengenai perbedaan antara tumbuhan Lamun (Seagrass) dengan Rumput Laut (Seaweed / Alga makroskopis) di perairan Indonesia adalah…","options":["Rumput laut memiliki bunga dan biji vivipar seperti bakau","Lamun adalah tumbuhan tingkat tinggi berbunga dan berpembuluh sejati (Angiospermae Monokotil) yang memiliki akar rimpang, batang, dan daun; sedangkan rumput laut (alga) adalah organisme talus (Thallophyta/Protista) tanpa akar, batang, dan daun sejati","Lamun adalah alga merah tidak berpembuluh, sedangkan rumput laut adalah tumbuhan berbiji terbuka","Lamun tidak melakukan fotosintesis, sedangkan rumput laut berfotosintesis"],"key":[1],"why":"Lamun (Seagrass: Enhalus, Thalassia) adalah tumbuhan berbunga sejati (Angiospermae), sedangkan Rumput Laut (Seaweed: Eucheuma, Sargassum) adalah Alga (Protista mirip tumbuhan).","src":"kuis"},{"id":"2.1.2","topic":"Ekosistem Indonesia","sub":"3.2 Tipe ekosistem khas Indonesia: mangrove, gambut, hutan hujan & karang","kind":"pg","stem":"Ekosistem Hutan Rawa Gambut (Peat Swamp Forest) di Kalimantan dan Sumatra merupakan gudang penyimpan karbon daratan terbesar karena tanah gambut terbentuk dari…","options":["Endapan abu vulkanik gunung berapi yang kaya belerang","Akumulasi serasah kayu dan bahan organik selama ribuan tahun yang mengalami dekomposisi sangat lambat akibat kondisi tanah yang tergenang air, miskin oksigen (anaerob), dan sangat asam (pH 3,0–4,5)","Aktivitas cacing tanah di padang sabana kering","Pelapukan batuan kapur basa oleh gelombang laut"],"key":[1],"why":"Genangan air yang miskin oksigen (anaerob) dan keasaman tinggi (pH 3–4,5) menghambat aktivitas bakteri dan jamur dekomposer, sehingga serasah organik menumpuk tebal membentuk gambut penyimpan karbon.","src":"kuis"},{"id":"2.2.0","topic":"Ekosistem Indonesia","sub":"3.3 Interaksi antarkomponen: kompetisi, predasi Lotka-Volterra & simbiosis","kind":"pg","stem":"Berdasarkan Asas Eksklusi Kompetitif Gause, apabila dua spesies memiliki relung ekologi (ecological niche) yang 100% identik dan ditempatkan pada habitat tertutup dengan sumber makanan terbatas yang sama, maka yang akan terjadi adalah…","options":["Spesies yang memiliki efisiensi pemanfaatan sumber daya dan laju reproduksi lebih tinggi akan bertahan, sedangkan spesies pesaing yang kalah efisien akan tereliminasi hingga punah lokal","Kedua spesies berubah menjadi organisme fotoautotrof","Populasi kedua spesies akan naik tak terhingga","Kedua spesies langsung melakukan hibridisasi membentuk spesies baru"],"key":[0],"why":"Asas Gause menyatakan bahwa dua spesies tidak dapat menempati relung ekologi yang persis sama secara stabil di satu habitat; salah satu pasti akan tersingkir melalui kompetisi interspesifik.","src":"kuis"},{"id":"2.2.1","topic":"Ekosistem Indonesia","sub":"3.3 Interaksi antarkomponen: kompetisi, predasi Lotka-Volterra & simbiosis","kind":"pg","stem":"Dalam grafik dinamika populasi Predator dan Mangsa (osilasi Lotka-Volterra) di ekosistem alami yang seimbang, hubungan fase antara kurva populasi mangsa dan kurva populasi predator selalu menunjukkan pola…","options":["Kenaikan populasi Predator selalu terjadi lebih dulu sebelum mangsa bertambah","Kedua puncak kurva selalu berimpit pada detik yang sama persis","Populasi mangsa selalu lebih sedikit daripada populasi predator","Kenaikan dan puncak populasi Mangsa selalu MENDAHULUI kenaikan dan puncak populasi Predator (kurva predator mengikuti kurva mangsa dengan jeda waktu)"],"key":[3],"why":"Pertambahan kelimpahan mangsa menyediakan banyak makanan bagi predator sehingga kelahiran predator menyusul naik beberapa waktu kemudian.","src":"kuis"},{"id":"2.2.2","topic":"Ekosistem Indonesia","sub":"3.3 Interaksi antarkomponen: kompetisi, predasi Lotka-Volterra & simbiosis","kind":"pg","stem":"Rumput teki (Cyperus rotundus) dan pohon Pinus mengeluarkan senyawa kimia sekunder ke dalam tanah di sekitar perakarannya yang berfungsi menghambat perkecambahan biji dan pertumbuhan tumbuhan herba spesies lain. Bentuk interaksi antarspesies ini disebut…","options":["Mimikri Müllerian","Alelopati / Amensalisme (− / 0)","Simbiosis komensalisme (+ / 0)","Mikoriza mutualistik (+ / +)"],"key":[1],"why":"Penghambatan pertumbuhan satu spesies oleh sekresi senyawa kimia toksik (alelokimia) dari tumbuhan lain disebut Alelopati (Amensalisme: − / 0).","src":"kuis"},{"id":"2.3.0","topic":"Ekosistem Indonesia","sub":"3.4 Aliran energi, rantai makanan, produktivitas (GPP/NPP) & hukum 10%","kind":"pg","stem":"Perhatikan jaring-jaring makanan di ekosistem sawah berikut: Padi → Belalang → Katak → Ular Sawah → Burung Elang. Apabila tanaman Padi memiliki Produktivitas Primer Bersih (NPP) sebesar 40.000 kkal/m²/tahun dan efisiensi ekologis antartingkat trofik adalah 10%, maka jumlah energi yang berhasil diubah menjadi biomassa pada tingkat KONSUMEN III (Ular Sawah) adalah…","options":["40 kkal/m²/tahun","4.000 kkal/m²/tahun","400 kkal/m²/tahun","4 kkal/m²/tahun"],"key":[0],"why":"Padi (Produsen/Trofik I) = 40.000 → Belalang (Konsumen I/Trofik II) = 4.000 → Katak (Konsumen II/Trofik III) = 400 → Ular Sawah (Konsumen III/Trofik IV) = 40 kkal/m²/tahun.","src":"kuis"},{"id":"2.3.1","topic":"Ekosistem Indonesia","sub":"3.4 Aliran energi, rantai makanan, produktivitas (GPP/NPP) & hukum 10%","kind":"pg","stem":"Mengapa hanya sekitar 10% energi dari satu tingkat trofik yang dapat berpindah menjadi biomassa baru pada tingkat trofik berikutnya, sementara sekitar 90% energi hilang?","options":["Karena konsumen memantulkan 90% makanan kembali ke matahari","Karena dekomposer menghisap energi dari tubuh hewan hidup","Karena sebagian besar energi (~90%) terpakai untuk aktivitas metabolisme dan terlepas ke lingkungan sebagai panas (kalor) respirasi seluler, serta terbuang bersama feses/ekskresi yang tidak tercerna","Karena 90% energi berubah menjadi unsur nitrogen di udara"],"key":[2],"why":"Sesuai Hukum II Termodinamika, sebagian besar energi terdisipasi sebagai panas respirasi seluler dan sisa organik yang tidak terasimilasi.","src":"kuis"},{"id":"2.3.2","topic":"Ekosistem Indonesia","sub":"3.4 Aliran energi, rantai makanan, produktivitas (GPP/NPP) & hukum 10%","kind":"pg","stem":"Di ekosistem hutan mangrove dan dasar laut dalam, rantai makanan yang paling dominan adalah Rantai Makanan Detritus yang dimulai dari…","options":["Bakteri kemoautotrof nitrifikasi","Fitoplankton hidup yang melakukan fotosintesis","Rumput laut hijau yang dimakan ikan baronang","Hancuran serasah daun gugur dan sisa bahan organik mati (detritus) yang dimakan oleh detritivor (seperti kepiting bakau, udang kecil, dan cacing)"],"key":[3],"why":"Di hutan mangrove, >80% daun bakau gugur ke lumpur menjadi serasah (detritus) yang dimakan kepiting/udang detritivor sebagai dasar Rantai Makanan Detritus.","src":"kuis"},{"id":"2.4.0","topic":"Ekosistem Indonesia","sub":"3.5 Tiga jenis piramida ekologi & fenomena piramida terbalik","kind":"pg","stem":"Di antara ketiga jenis piramida ekologi berikut, manakah piramida yang TIDAK PERNAH berbentuk terbalik di ekosistem mana pun di bumi dan paling akurat merepresentasikan Hukum II Termodinamika?","options":["Piramida Biomassa Sesaat","Piramida Populasi Parasit","Piramida Energi (Produktivitas)","Piramida Jumlah Individu"],"key":[2],"why":"Piramida Energi mengukur laju aliran energi per satuan luas per satuan waktu (kkal/m²/tahun) sehingga tidak pernah bisa terbalik.","src":"kuis"},{"id":"2.4.1","topic":"Ekosistem Indonesia","sub":"3.5 Tiga jenis piramida ekologi & fenomena piramida terbalik","kind":"pg","stem":"Mengapa pada ekosistem perairan laut terbuka, Piramida Biomassa dapat berbentuk terbalik (biomassa fitoplankton lebih kecil daripada biomassa zooplankton pada saat pengukuran)?","options":["Karena hukum kekekalan energi tidak berlaku di dalam air laut","Karena air laut mengubah garam menjadi energi bagi ikan","Karena pengukuran biomassa hanya mencatat massa sesaat (standing crop), di mana fitoplankton berumur pendek tetapi memiliki kecepatan reproduksi (turnover rate) yang sangat tinggi sehingga terus-menerus menyuplai makanan bagi zooplankton","Karena zooplankton di laut dapat berfotosintesis sendiri tanpa makan fitoplankton"],"key":[2],"why":"Turnover rate (laju pergantian generasi) fitoplankton sangat tinggi sehingga laju produksinya sepanjang waktu sangat besar meski stok sesaatnya tampak kecil.","src":"kuis"},{"id":"2.4.2","topic":"Ekosistem Indonesia","sub":"3.5 Tiga jenis piramida ekologi & fenomena piramida terbalik","kind":"pg","stem":"Saat mengukur data untuk menyusun Piramida Biomassa, para ahli ekologi wajib menggunakan ukuran 'berat kering' (setelah sampel dioven hingga airnya menguap), bukan 'berat basah', karena…","options":["Air akan mengubah herbivora menjadi karnivora","Air di dalam jaringan makhluk hidup sangat berfluktuasi dan tidak mengandung nilai energi organik (kalori) hasil asimilasi karbon","Oven akan menambah jumlah karbon di dalam sampel","Berat basah sulit ditimbang dengan neraca"],"key":[1],"why":"Kandungan air antar-organisme sangat bervariasi dan air tidak merepresentasikan jumlah materi organik/energi biomassa.","src":"kuis"},{"id":"2.5.0","topic":"Ekosistem Indonesia","sub":"3.6 Daur biogeokimia lengkap: nitrogen, karbon, fosfor, sulfur & air","kind":"pg","stem":"Urutan mikroorganisme yang terlibat dalam perubahan Amonia (NH3) → Nitrit (NO2-) → Nitrat (NO3-) → Gas Nitrogen bebas (N2) di dalam siklus nitrogen secara berurutan adalah…","options":["Rhizobium → Azotobacter → Nitrosomonas","Nitrosomonas → Nitrobacter → Pseudomonas denitrificans","Nitrobacter → Nitrosomonas → Rhizobium","Pseudomonas denitrificans → Nitrobacter → Nitrosomonas"],"key":[1],"why":"NH3 → NO2- dikatalisis oleh Nitrosomonas (nitritasi); NO2- → NO3- oleh Nitrobacter (nitratasi); dan NO3- → N2 oleh Pseudomonas denitrificans (denitrifikasi).","src":"kuis"},{"id":"2.5.1","topic":"Ekosistem Indonesia","sub":"3.6 Daur biogeokimia lengkap: nitrogen, karbon, fosfor, sulfur & air","kind":"pg","stem":"Di antara lima daur biogeokimia utama (Karbon, Nitrogen, Oksigen, Air, dan Fosfor), daur manakah yang merupakan SIKLUS SEDIMENTER murni karena TIDAK memiliki fase gas alami di atmosfer bumi?","options":["Daur Fosfor (PO43- berasal dari pelapukan batuan fosfat/apatit)","Daur Nitrogen","Daur Karbon","Daur Hidrologi"],"key":[0],"why":"Fosfor tidak memiliki senyawa gas alami di atmosfer; cadangan utamanya berada di batuan kerak bumi dan sedimen laut.","src":"kuis"},{"id":"2.5.2","topic":"Ekosistem Indonesia","sub":"3.6 Daur biogeokimia lengkap: nitrogen, karbon, fosfor, sulfur & air","kind":"pg","stem":"Dalam Daur Sulfur (Belerang), tumbuhan menyerap belerang dari dalam tanah melalui akar dalam bentuk ion… untuk digunakan menyusun asam amino…","options":["Ion Sulfat (SO42-); asam amino bersulfur yaitu Metionin dan Sistein (pembentuk jembatan disulfida struktur tersier protein)","Gas SO2; asam amino glisin dan alanin","Asam sulfida (H2S); asam nukleat DNA","Belerang murni (S8); glukosa dan amilum"],"key":[0],"why":"Akar tumbuhan menyerap belerang dalam bentuk ion Sulfat anorganik (SO42-) untuk menyusun asam amino Sistein dan Metionin.","src":"kuis"},{"id":"2.6.0","topic":"Ekosistem Indonesia","sub":"3.7 Suksesi ekologis, eutrofikasi (DO-BOD), biomagnifikasi & restorasi","kind":"pg","stem":"Perhatikan dua peristiwa kerusakan ekosistem berikut: Peristiwa I adalah letusan Gunung Krakatau 1883 yang menutup seluruh pulau dengan lapisan lava batu apung steril; Peristiwa II adalah kebakaran hutan gambut di Riau yang menyisakan lapisan tanah dan biji di dalamnya. Pernyataan yang tepat mengenai proses pemulihan kedua ekosistem tersebut adalah…","options":["Peristiwa I mengalami suksesi sekunder, sedangkan Peristiwa II mengalami suksesi primer","Kedua peristiwa langsung ditumbuhi oleh pohon jati dewasa dalam waktu satu minggu","Suksesi primer tidak dapat mencapai komunitas klimaks","Peristiwa I mengalami Suksesi Primer yang wajib diawali oleh organisme pionir Lichen (lumut kerak) dan Cyanobacteria pembentuk tanah; sedangkan Peristiwa II mengalami Suksesi Sekunder yang berlangsung lebih cepat karena substrat tanah masih tersedia"],"key":[3],"why":"Suksesi Primer terjadi bila substrat tanah hilang total sehingga wajib diawali pionir Lichen pelapuk batu. Suksesi Sekunder terjadi bila komunitas rusak tetapi substrat tanah masih tersisa.","src":"kuis"},{"id":"2.6.1","topic":"Ekosistem Indonesia","sub":"3.7 Suksesi ekologis, eutrofikasi (DO-BOD), biomagnifikasi & restorasi","kind":"pg","stem":"Di sebuah sungai yang tercemar limbah organik rumah tangga secara berat, grafik kualitas air tepat di titik pembuangan limbah akan menunjukkan karakteristik…","options":["Kadar DO dan BOD sama-sama naik menjadi 100 mg/L","Ikan air jernih berkembang biak paling pesat di titik limbah","Kadar DO (oksigen terlarut) anjlok ke titik terendah, sedangkan nilai BOD dan jumlah bakteri pengurai aerob melonjak ke puncak tertinggi","Kadar DO mencapai puncak tertinggi dan nilai BOD mencapai titik terendah"],"key":[2],"why":"Di zona pencemaran organik berat, bakteri aerob mengonsumsi oksigen terlarut untuk menguraikan limbah, sehingga nilai BOD sangat TINGGI dan kadar DO sangat RENDAH.","src":"kuis"},{"id":"2.6.2","topic":"Ekosistem Indonesia","sub":"3.7 Suksesi ekologis, eutrofikasi (DO-BOD), biomagnifikasi & restorasi","kind":"pg","stem":"Manakah pasangan polutan atmosfer dan dampak lingkungan global/regionalnya berikut yang 100% BENAR?","options":["Gas CFC (Freon) — melepaskan radikal klorin yang menguraikan lapisan Ozon (O3) di stratosfer; sedangkan gas SO2 dan NOx — bereaksi dengan uap air membentuk Hujan Asam (H2SO4 & HNO3)","Gas Karbon Monoksida (CO) — menyuburkan daun tanaman hutan","Gas Oksigen (O2) — menyebabkan efek rumah kaca paling kuat","Gas CO2 dan CH4 — melubangi lapisan ozon stratosfer secara langsung"],"key":[0],"why":"CO2 & CH4 = Efek Rumah Kaca / Pemanasan Global; CFC = Penipisan Lapisan Ozon (O3); SO2 & NOx = Hujan Asam; CO = mengikat Hb membentuk HbCO.","src":"kuis"},{"id":"3.0.0","topic":"Enzim & Metabolisme Sel","sub":"4.1 Struktur holoenzim, energi aktivasi & mekanisme kerja enzim","kind":"pg","stem":"Pernyataan yang tepat mengenai komponen penyusun enzim lengkap (Holoenzim) adalah…","options":["Koenzim NAD+ dan FAD tersusun atas asam lemak jenuh","Apoenzim tersusun atas ion logam yang tahan panas, sedangkan kofaktor tersusun atas protein","Apoenzim adalah bagian protein yang bersifat termolabil dan menentukan spesifisitas substrat; sedangkan Kofaktor/Koenzim adalah bagian non-protein (ion logam atau vitamin B) yang membantu aktivitas katalitik","Holoenzim hanya dapat bekerja jika apoenzimnya dilepaskan"],"key":[2],"why":"Holoenzim = Apoenzim (protein globular, peka suhu/pH) + Gugus non-protein (Kofaktor ion logam atau Koenzim organik turunan vitamin).","src":"kuis"},{"id":"3.0.1","topic":"Enzim & Metabolisme Sel","sub":"4.1 Struktur holoenzim, energi aktivasi & mekanisme kerja enzim","kind":"pg","stem":"Berdasarkan Teori Kecocokan Terinduksi (Induced Fit Theory) yang dikemukakan oleh Daniel Koshland, interaksi antara sisi aktif enzim dengan molekul substrat berlangsung dengan cara…","options":["Enzim berubah menjadi molekul produk secara permanen","Sisi aktif enzim bersifat fleksibel; saat substrat mulai berikatan, interaksi kimia memicu perubahan konformasi 3D sisi aktif enzim hingga mencengkeram substrat secara presisi","Substrat menghancurkan ikatan peptida apoenzim","Sisi aktif enzim bersifat kaku sempurna seperti lubang gembok besi"],"key":[1],"why":"Model Induced Fit Koshland membuktikan bahwa sisi aktif bersifat fleksibel dan menyesuaikan bentuknya saat mengikat substrat.","src":"kuis"},{"id":"3.0.2","topic":"Enzim & Metabolisme Sel","sub":"4.1 Struktur holoenzim, energi aktivasi & mekanisme kerja enzim","kind":"pg","stem":"Pada grafik tingkat energi reaksi biokimia, kurva reaksi yang dikatalisis oleh enzim dibandingkan dengan kurva reaksi tanpa enzim akan menunjukkan…","options":["Energi akhir produk turun menjadi nol","Energi awal substrat naik dua kali lipat","Puncak bukit Energi Aktivasi (Ea) yang lebih RENDAH, namun selisih energi bebas antara substrat dan produk (ΔG) tetap SAMA","Puncak bukit Energi Aktivasi (Ea) yang lebih tinggi dan ΔG berubah dari positif menjadi negatif"],"key":[2],"why":"Enzim bekerja menurunkan penghalang Energi Aktivasi (Ea) tanpa mengubah tinggi awal substrat maupun tinggi akhir produk (ΔG tetap).","src":"kuis"},{"id":"3.1.0","topic":"Enzim & Metabolisme Sel","sub":"4.2 Kinetika Michaelis-Menten, pengaruh suhu, pH & uji katalase","kind":"pg","stem":"Dua enzim diuji kinetika Michaelis-Menten-nya: Enzim P memiliki nilai Km = 0,2 mM, sedangkan Enzim Q memiliki nilai Km = 15 mM. Kesimpulan biokimia yang tepat adalah…","options":["Enzim P memiliki afinitas (daya ikat) terhadap substrat yang JAUH LEBIH TINGGI dibandingkan Enzim Q, karena Enzim P hanya membutuhkan konsentrasi substrat 0,2 mM untuk mencapai ½ Vmax","Nilai Km tidak ada hubungannya dengan pengikatan substrat","Enzim Q memiliki afinitas terhadap substrat yang lebih kuat daripada Enzim P","Enzim P baru bisa bekerja pada konsentrasi substrat di atas 100 mM"],"key":[0],"why":"Semakin KECIL nilai Km, semakin TINGGI afinitas enzim terhadap substratnya.","src":"kuis"},{"id":"3.1.1","topic":"Enzim & Metabolisme Sel","sub":"4.2 Kinetika Michaelis-Menten, pengaruh suhu, pH & uji katalase","kind":"pg","stem":"Perhatikan tiga enzim pencernaan manusia: (1) Ptialin mulut, (2) Pepsin lambung, dan (3) Tripsin duodenum. Urutan rentang pH optimum ketiga enzim tersebut secara berurutan adalah…","options":["(1) pH 2,0 — (2) pH 7,0 — (3) pH 8,5","Ketiga enzim tersebut sama-sama bekerja optimum pada pH 7,0","(1) pH ~7,0 (netral) — (2) pH ~1,5–2,0 (sangat asam) — (3) pH ~8,0–8,5 (basa)","(1) pH 8,5 — (2) pH 7,0 — (3) pH 2,0"],"key":[2],"why":"Ptialin optimum di pH netral (~7,0), Pepsin di pH sangat asam (~1,5–2,0), dan Tripsin/Lipase di pH basa (~8,0–8,5).","src":"kuis"},{"id":"3.1.2","topic":"Enzim & Metabolisme Sel","sub":"4.2 Kinetika Michaelis-Menten, pengaruh suhu, pH & uji katalase","kind":"pg","stem":"Ketika larutan enzim telah mencapai kecepatan maksimumnya (Vmax) akibat seluruh sisi aktif enzim telah jenuh oleh substrat, satu-satunya cara untuk menaikkan lagi laju reaksi di atas batas Vmax tersebut adalah…","options":["Menambahkan konsentrasi Enzim [E] ke dalam tabung reaksi","Menaikkan suhu tabung hingga 100°C","Menambahkan lebih banyak substrat","Menambahkan inhibitor non-kompetitif"],"key":[0],"why":"Saat seluruh sisi aktif enzim jenuh oleh substrat, Vmax hanya bisa dinaikkan dengan menambah jumlah molekul enzim [E].","src":"kuis"},{"id":"3.2.0","topic":"Enzim & Metabolisme Sel","sub":"4.3 Regulasi enzim: inhibisi kompetitif, non-kompetitif & alosterik","kind":"pg","stem":"Apabila penambahan suatu zat penghambat menyebabkan nilai kecepatan maksimum (Vmax) TURUN menjadi setengahnya sedangkan nilai Km TETAP, dan penambahan substrat berlebih gagal memulihkan Vmax, maka zat tersebut adalah…","options":["Koenzim vitamin B kompleks","Aktivator alosterik positif","Inhibitor Non-Kompetitif (Alosterik) yang menempel di sisi alosterik dan mengubah konformasi sisi aktif enzim","Inhibitor Kompetitif yang menempel di sisi aktif"],"key":[2],"why":"Inhibitor Non-Kompetitif menurunkan Vmax tanpa mengubah Km dan tidak dapat diatasi dengan penambahan substrat.","src":"kuis"},{"id":"3.2.1","topic":"Enzim & Metabolisme Sel","sub":"4.3 Regulasi enzim: inhibisi kompetitif, non-kompetitif & alosterik","kind":"pg","stem":"Dalam jalur biosintesis asam amino: Senyawa A →(Enzim 1) B →(Enzim 2) C →(Enzim 3) Produk Akhir Z. Ketika Produk Z sudah berlimpah, molekul Z berikatan pada sisi alosterik Enzim 1 untuk menghentikan produksi sementara. Mekanisme ini disebut…","options":["Inhibisi Umpan Balik Negatif (Feedback Inhibition)","Denaturasi termal ireversibel","Aktivasi zimogen proteolitik","Hidrolisis kompetitif"],"key":[0],"why":"Ketika produk akhir menghambat secara alosterik enzim pertama di jalurnya, mekanismenya disebut Inhibisi Umpan Balik (Feedback Inhibition).","src":"kuis"},{"id":"3.2.2","topic":"Enzim & Metabolisme Sel","sub":"4.3 Regulasi enzim: inhibisi kompetitif, non-kompetitif & alosterik","kind":"pg","stem":"Obat antibakteri Sulfonamida (Sulfa) memiliki struktur molekul mirip PABA yang dibutuhkan bakteri untuk mensintesis asam folat. Cara kerja Sulfonamida merupakan contoh…","options":["Enzim lisozim pemecah dinding sel","Koenzim rantai transpor elektron","Inhibitor Kompetitif pada sisi aktif enzim sintesis asam folat bakteri","Inhibitor Non-Kompetitif pada ribosom 80S manusia"],"key":[2],"why":"Sulfonamida bersaing dengan PABA memperebutkan sisi aktif enzim dihidropteroat sintase bakteri (Inhibitor Kompetitif).","src":"kuis"},{"id":"3.3.0","topic":"Enzim & Metabolisme Sel","sub":"4.4 Katabolisme I: glikolisis (10 langkah) & dekarboksilasi oksidatif","kind":"pg","stem":"Apabila substrat awal yang masuk ke jalur Glikolisis bukanlah Glukosa (6C), melainkan langsung 1 molekul PGAL / G3P (3C), maka hasil bersih energi yang diperoleh sampai terbentuk 1 molekul Asam Piruvat adalah…","options":["2 ATP bersih dan 1 NADH (karena PGAL masuk setelah fase investasi 2 ATP terlewati!)","4 ATP dan 2 NADH","1 ATP dan 1 NADH","0 ATP dan 2 CO2"],"key":[0],"why":"Satu molekul PGAL (3C) pada fase panen langsung menghasilkan 2 ATP dan 1 NADH tanpa dikurangi investasi.","src":"kuis"},{"id":"3.3.1","topic":"Enzim & Metabolisme Sel","sub":"4.4 Katabolisme I: glikolisis (10 langkah) & dekarboksilasi oksidatif","kind":"pg","stem":"Tahapan respirasi aerob yang berlangsung di matriks mitokondria dan mengubah Asam Piruvat (3C) menjadi Asetil-KoA (2C) sambil melepaskan gas CO2 untuk pertama kalinya tanpa menghasilkan ATP adalah…","options":["Siklus Cori","Kemiosmosis ATP sintase","Fosforilasi tingkat substrat","Dekarboksilasi Oksidatif oleh kompleks piruvat dehidrogenase"],"key":[3],"why":"Dekarboksilasi Oksidatif mengubah 2 Piruvat menjadi 2 Asetil-KoA + 2 NADH + 2 CO2 (0 ATP).","src":"kuis"},{"id":"3.3.2","topic":"Enzim & Metabolisme Sel","sub":"4.4 Katabolisme I: glikolisis (10 langkah) & dekarboksilasi oksidatif","kind":"pg","stem":"Enzim alosterik utama pengontrol laju Glikolisis yang dihambat apabila kadar ATP dan Asam Sitrat di dalam sel sudah sangat tinggi adalah…","options":["Enzim Laktat dehidrogenase","Enzim Fosfofruktokinase (PFK)","Enzim Sitokrom oksidase","Enzim RuBisCO"],"key":[1],"why":"Fosfofruktokinase (PFK) dihambat secara alosterik oleh ATP dan Sitrat tinggi, serta diaktifkan oleh AMP/ADP tinggi.","src":"kuis"},{"id":"3.4.0","topic":"Enzim & Metabolisme Sel","sub":"4.5 Katabolisme II: siklus Krebs, transpor elektron & kemiosmosis ATP","kind":"pg","stem":"Dalam satu putaran Siklus Krebs untuk 1 molekul Asetil-KoA (2C), jumlah produk yang dihasilkan adalah…","options":["3 NADH, 1 FADH2, 1 ATP (GTP), dan 2 CO2","2 NADH, 1 FADH2, 2 ATP, dan 1 CO2","6 NADH, 2 FADH2, 2 ATP, dan 4 CO2","10 NADH, 2 FADH2, dan 34 ATP"],"key":[0],"why":"Untuk 1 molekul Asetil-KoA (1 putaran Siklus Krebs) dihasilkan tepat: 3 NADH, 1 FADH2, 1 ATP, dan 2 CO2.","src":"kuis"},{"id":"3.4.1","topic":"Enzim & Metabolisme Sel","sub":"4.5 Katabolisme II: siklus Krebs, transpor elektron & kemiosmosis ATP","kind":"pg","stem":"Berdasarkan mekanisme Kemiosmosis di mitokondria, aliran elektron sepanjang Kompleks I, III, dan IV memompa ion hidrogen (proton / H+) dari… menuju…, sebelum mengalir balik memutar ATP Sintase.","options":["Dari sitosol menuju ruang antarmembran","Dari Matriks Mitokondria menuju Ruang Antarmembran, lalu H+ mengalir balik dari Ruang Antarmembran ke Matriks melalui kanal ATP Sintase","Dari Ruang Antarmembran menuju Matriks, lalu keluar ke sitoplasma","Dari inti sel menuju lisosom"],"key":[1],"why":"Proton dipompa dari Matriks ke Ruang Antarmembran, lalu mengalir balik ke Matriks memutar rotor ATP Sintase.","src":"kuis"},{"id":"3.4.2","topic":"Enzim & Metabolisme Sel","sub":"4.5 Katabolisme II: siklus Krebs, transpor elektron & kemiosmosis ATP","kind":"pg","stem":"Mengapa oksidasi sempurna 1 glukosa pada sel otot rangka menghasilkan 36 ATP, sedangkan pada sel jantung/hati dan bakteri aerob menghasilkan 38 ATP?","options":["Karena sel hati melakukan fotosintesis tambahan","Karena 2 NADH glikolisis sitosol pada otot rangka dimasukkan ke mitokondria melalui shuttle Gliserol-Fosfat yang mengubahnya menjadi 2 FADH2 (menghasilkan 4 ATP, bukan 6 ATP)","Karena sel otot rangka tidak memiliki Siklus Krebs","Karena bakteri aerob memiliki dua mitokondria"],"key":[1],"why":"Shuttle Gliserol-Fosfat pada otot rangka/otak menyerahkan elektron NADH sitosol ke FAD menjadi FADH2 sehingga menghasilkan 2 ATP lebih sedikit (36 vs 38 ATP).","src":"kuis"},{"id":"3.5.0","topic":"Enzim & Metabolisme Sel","sub":"4.6 Fermentasi (asam laktat vs alkohol) & katabolisme lemak-protein","kind":"pg","stem":"Tujuan biokimia utama mengapa sel yang kekurangan oksigen mengubah Asam Piruvat menjadi Etanol atau Asam Laktat adalah…","options":["Untuk menghasilkan gas oksigen baru","Untuk memompa proton ke matriks mitokondria","Untuk mengoksidasi kembali NADH menjadi NAD+ bebas, sehingga stok NAD+ tetap tersedia agar Glikolisis (penghasil 2 ATP) dapat terus berjalan","Untuk menghabiskan cadangan air di sitoplasma"],"key":[2],"why":"Reduksi piruvat/asetaldehida bertujuan meregenerasi NAD+ agar Glikolisis tidak terhenti.","src":"kuis"},{"id":"3.5.1","topic":"Enzim & Metabolisme Sel","sub":"4.6 Fermentasi (asam laktat vs alkohol) & katabolisme lemak-protein","kind":"pg","stem":"Dalam katabolisme lemak (trigliserida), Gliserol (3C) dan Asam Lemak masuk ke poros respirasi seluler melalui jalur…","options":["Keduanya langsung diubah menjadi asam laktat","Gliserol masuk ke rantai transpor elektron, asam lemak jadi amonia","Gliserol diubah menjadi PGAL (G3P) masuk ke Glikolisis; sedangkan Asam Lemak dipotong setiap 2 karbon melalui Beta-Oksidasi menjadi Asetil-KoA yang masuk ke Siklus Krebs","Gliserol masuk ke Siklus Calvin"],"key":[2],"why":"Gliserol masuk ke Glikolisis sebagai PGAL, sedangkan Asam Lemak mengalami β-Oksidasi menjadi Asetil-KoA.","src":"kuis"},{"id":"3.5.2","topic":"Enzim & Metabolisme Sel","sub":"4.6 Fermentasi (asam laktat vs alkohol) & katabolisme lemak-protein","kind":"pg","stem":"Tahap pertama yang wajib dialami asam amino di Hati sebelum kerangka karbonnya dapat masuk ke Siklus Krebs adalah…","options":["Fotolisis","Deaminasi Oksidatif (pelepasan gugus amina -NH2 menjadi amonia NH3 yang diubah menjadi Urea lewat Siklus Ornitin)","Transkripsi mRNA","Beta-oksidasi"],"key":[1],"why":"Gugus amina (-NH2) dilepas melalui Deaminasi di hati menjadi NH3 → Urea (Siklus Ornitin).","src":"kuis"},{"id":"3.6.0","topic":"Enzim & Metabolisme Sel","sub":"4.7 Anabolisme I: struktur kloroplas & reaksi terang fotosintesis","kind":"pg","stem":"Perbedaan mendasar antara Fotofosforilasi Non-Siklik dan Fotofosforilasi Siklik pada Reaksi Terang fotosintesis adalah…","options":["Siklik mengikat CO2 menjadi glukosa secara langsung","Non-siklik tidak membutuhkan cahaya","Non-siklik melibatkan FS II (P680) dan FS I (P700), melakukan fotolisis H2O, serta menghasilkan ATP, NADPH, dan O2; sedangkan Siklik HANYA melibatkan FS I (P700) dan HANYA menghasilkan ATP (tanpa NADPH dan tanpa O2)","Non-siklik terjadi di stroma, siklik di grana"],"key":[2],"why":"Non-Siklik menghasilkan ATP + NADPH + O2; Siklik hanya melibatkan P700 dan hanya menghasilkan ATP.","src":"kuis"},{"id":"3.6.1","topic":"Enzim & Metabolisme Sel","sub":"4.7 Anabolisme I: struktur kloroplas & reaksi terang fotosintesis","kind":"pg","stem":"Elektron pada klorofil Fotosistem II (P680) yang lepas akibat eksitasi foton cahaya matahari akan digantikan oleh elektron yang berasal dari…","options":["Pemecahan molekul air (Fotolisis H2O → 2H+ + 2e- + ½O2) di lumen tilakoid","Oksidasi glukosa","Pemecahan molekul CO2","Transfer dari molekul ATP"],"key":[0],"why":"Kekosongan elektron pada P680+ diisi kembali oleh elektron hasil Fotolisis Air (H2O).","src":"kuis"},{"id":"3.6.2","topic":"Enzim & Metabolisme Sel","sub":"4.7 Anabolisme I: struktur kloroplas & reaksi terang fotosintesis","kind":"pg","stem":"Pada percobaan Ingenhousz menggunakan Hydrilla verticillata, tindakan yang meningkatkan jumlah gelembung gas O2 paling signifikan adalah…","options":["Merebus Hydrilla dengan alkohol","Meletakkan di tempat gelap dan menambah es","Menyinari dengan lampu hijau redup","Menyinari dengan cahaya merah/biru terang dan menambahkan natrium bikarbonat (NaHCO3 / soda kue) sebagai sumber CO2 terlarut"],"key":[3],"why":"NaHCO3 menyuplai CO2 terlarut yang mempercepat Siklus Calvin dan regenerasi NADP+/ADP bagi Reaksi Terang.","src":"kuis"},{"id":"3.7.0","topic":"Enzim & Metabolisme Sel","sub":"4.8 Anabolisme II: siklus Calvin, tumbuhan C3, C4, CAM & kemosintesis","kind":"pg","stem":"Bagaimana cara tanaman C4 (Jagung, Tebu) dan tanaman CAM (Nanas, Kaktus) menghindari Fotorespirasi dibandingkan tanaman C3 (Padi, Kedelai)?","options":["Tanaman C4 dan CAM tidak memiliki enzim RuBisCO","Tanaman C4 memisahkan fiksasi awal CO2 (oleh PEP Karboksilase di mesofil) dan Siklus Calvin (di sel seludang pembuluh / Anatomi Kranz) secara RUANG (spasial); sedangkan tanaman CAM memisahkannya secara WAKTU (temporal: buka stomata malam hari ikat CO2 jadi malat, tutup stomata siang hari jalankan Siklus Calvin)","Tanaman C4 menyerap CO2 lewat akar","Tanaman C3 membuka stomata hanya di malam hari"],"key":[1],"why":"C4 = pemisahan RUANG (Mesofil → Seludang Pembuluh); CAM = pemisahan WAKTU (Malam buka stomata → Siang tutup stomata).","src":"kuis"},{"id":"3.7.1","topic":"Enzim & Metabolisme Sel","sub":"4.8 Anabolisme II: siklus Calvin, tumbuhan C3, C4, CAM & kemosintesis","kind":"pg","stem":"Dalam prosedur eksperimen Uji Sachs, langkah merebus daun di dalam larutan ALKOHOL PANAS setelah direbus di air mendidih bertujuan untuk…","options":["Mematikan bakteri permukaan daun","Mengubah glukosa menjadi selulosa","Melarutkan pigmen klorofil sehingga daun menjadi pucat, agar perubahan warna menjadi biru kehitaman saat ditetesi Lugol/Iodin terlihat jelas","Membuka stomata daun"],"key":[2],"why":"Alkohol panas melarutkan klorofil agar uji amilum dengan Lugol/Iodin terlihat jelas.","src":"kuis"},{"id":"3.7.2","topic":"Enzim & Metabolisme Sel","sub":"4.8 Anabolisme II: siklus Calvin, tumbuhan C3, C4, CAM & kemosintesis","kind":"pg","stem":"Dari setiap 6 molekul PGAL (3C) yang dihasilkan dari fiksasi 3 molekul CO2 di Siklus Calvin, berapa molekul PGAL yang keluar sebagai produk bersih dan berapa yang dipakai kembali untuk regenerasi RuBP?","options":["1 molekul PGAL keluar sebagai produk bersih, sedangkan 5 molekul PGAL dipakai kembali untuk meregenerasi 3 molekul RuBP","3 PGAL keluar dan 3 PGAL untuk regenerasi","5 PGAL keluar dan 1 PGAL untuk regenerasi","6 PGAL keluar semua"],"key":[0],"why":"Untuk 3 CO2: terbentuk 6 PGAL → 1 PGAL keluar, dan 5 PGAL diregenerasi menjadi 3 RuBP.","src":"kuis"},{"id":"4.0.0","topic":"Sistem Sirkulasi","sub":"5.1 Komposisi plasma darah, eritrosit & 5 jenis leukosit","kind":"pg","stem":"Urutan kelimpahan lima jenis sel darah putih (leukosit) pada darah manusia sehat dari persentase PALING BANYAK hingga PALING SEDIKIT adalah…","options":["Limfosit > Neutrofil > Eosinofil > Monosit > Basofil","Neutrofil (60–70%) > Limfosit (20–30%) > Monosit (3–8%) > Eosinofil (2–4%) > Basofil (<1%)","Basofil > Eosinofil > Monosit > Limfosit > Neutrofil","Monosit > Neutrofil > Basofil > Limfosit > Eosinofil"],"key":[1],"why":"Ingat jembatan keledai: Never Let Monkeys Eat Bananas → Neutrofil > Limfosit > Monosit > Eosinofil > Basofil.","src":"kuis"},{"id":"4.0.1","topic":"Sistem Sirkulasi","sub":"5.1 Komposisi plasma darah, eritrosit & 5 jenis leukosit","kind":"pg","stem":"Apabila dari dalam plasma darah dikeluarkan seluruh protein pembekuan darah (khususnya Fibrinogen), maka cairan kuning jernih yang tersisa (yang mengandung air, elektrolit, albumin, dan antibodi/imunoglobulin) dinamakan…","options":["Cairan limfa","Hematokrit","Kimus","Serum darah"],"key":[3],"why":"Rumus baku fisiologi darah: Serum = Plasma Darah − Fibrinogen (dan faktor koagulasi yang terpakai). Itulah sebabnya cairan berisi antibodi siap pakai disebut 'Serum' (misal Serum Anti-Bisa Ular).","src":"kuis"},{"id":"4.0.2","topic":"Sistem Sirkulasi","sub":"5.1 Komposisi plasma darah, eritrosit & 5 jenis leukosit","kind":"pg","stem":"Sel darah putih agranulosit yang memiliki ukuran sel paling besar, berinti tunggal berbentuk seperti ginjal atau tapal kuda, dan ketika berdiapedesis keluar dari kapiler menuju jaringan ikat akan berdiferensiasi membesar menjadi sel fagosit raksasa bernama MAKROFAG adalah…","options":["Limfosit B","Neutrofil","Monosit","Basofil"],"key":[2],"why":"Monosit adalah prekursor di dalam darah yang ketika masuk ke jaringan berubah menjadi Makrofag jaringan (seperti sel Kupffer di hati, mikroglia di otak, dan makrofag alveolus di paru).","src":"kuis"},{"id":"4.1.0","topic":"Sistem Sirkulasi","sub":"5.2 Hemostasis, kaskade pembekuan darah & gangguan koagulasi","kind":"pg","stem":"Perhatikan skema proses pembekuan darah berikut: Trombosit pecah → mengeluarkan Zat P → Zat P bersama ion Ca2+ mengubah Zat Q (yang disintesis di hati dengan bantuan Vitamin K) menjadi Zat R → Zat R mengubah Fibrinogen menjadi Benang Fibrin. Zat P, Zat Q, dan Zat R secara berurutan adalah…","options":["Trombin, Fibrinogen, dan Protrombin","Trombokinase (Tromboplastin), Protrombin, dan Trombin","Protrombin, Trombokinase, dan Trombin","Fibrin, Trombin, dan Trombokinase"],"key":[1],"why":"Zat P yang keluar dari trombosit pecah adalah enzim Trombokinase (Tromboplastin); Zat Q adalah Protrombin; dan Zat R adalah enzim Trombin aktif.","src":"kuis"},{"id":"4.1.1","topic":"Sistem Sirkulasi","sub":"5.2 Hemostasis, kaskade pembekuan darah & gangguan koagulasi","kind":"pg","stem":"Mengapa penderita gangguan fungsi Hati kronis (sirosis hepatis) atau bayi baru lahir yang mengalami defisiensi Vitamin K sangat rentan mengalami perdarahan hebat?","options":["Karena Vitamin K adalah bahan baku pembentukan keping darah di sumsum tulang","Karena tanpa Vitamin K sel darah merah akan pecah","Karena Vitamin K berfungsi mengikat ion kalsium di tulang","Karena sel-sel Hati membutuhkan Vitamin K sebagai kofaktor mutlak untuk mensintesis Protrombin (Faktor II) serta faktor pembekuan VII, IX, dan X"],"key":[3],"why":"Protrombin dan beberapa faktor koagulasi plasma disintesis di dalam organ Hati (Hepar) dengan bantuan mutlak Vitamin K.","src":"kuis"},{"id":"4.1.2","topic":"Sistem Sirkulasi","sub":"5.2 Hemostasis, kaskade pembekuan darah & gangguan koagulasi","kind":"pg","stem":"Senyawa antikoagulan alami yang disekresikan oleh sel Basofil dan Sel Mast di dalam tubuh manusia untuk mencegah terjadinya pembekuan darah spontan di dalam pembuluh darah yang utuh adalah…","options":["Fibrinogen","Histamin","Hirudin","Heparin"],"key":[3],"why":"Basofil dan Sel Mast melepaskan dua zat utama: Histamin (mediator vasodilatasi inflamasi/alergi) dan Heparin (antikoagulan alami pengaktif antitrombin). Sedangkan Hirudin berasal dari kelenjar ludah lintah.","src":"kuis"},{"id":"4.2.0","topic":"Sistem Sirkulasi","sub":"5.3 Penggolongan darah ABO-Rhesus, transfusi & eritroblastosis fetalis","kind":"pg","stem":"Mengapa seseorang yang bergolongan darah O disebut sebagai 'Donor Universal', sedangkan seseorang yang bergolongan darah AB disebut sebagai 'Resipien Universal' pada skema transfusi klasik?","options":["Karena eritrosit golongan O memiliki aglutinogen A dan B lengkap","Karena eritrosit golongan O TIDAK memiliki aglutinogen (antigen) A maupun B sehingga tidak digumpalkan oleh antibodi resipien; sedangkan plasma darah golongan AB TIDAK memiliki aglutinin (antibodi) Anti-A maupun Anti-B sehingga tidak menggumpalkan eritrosit donor","Karena plasma golongan O tidak memiliki antibodi sama sekali","Karena eritrosit golongan AB tidak memiliki inti sel"],"key":[1],"why":"Dalam transfusi, bahaya utama adalah penggumpalan eritrosit donor oleh antibodi plasma resipien. Eritrosit golongan O bersih dari antigen A/B (aman didonorkan), sedangkan plasma golongan AB bersih dari antibodi Anti-A/Anti-B (aman menerima).","src":"kuis"},{"id":"4.2.1","topic":"Sistem Sirkulasi","sub":"5.3 Penggolongan darah ABO-Rhesus, transfusi & eritroblastosis fetalis","kind":"pg","stem":"Kasus Eritroblastosis Fetalis (penyakit hemolitik bayi baru lahir akibat inkompatibilitas Rhesus) secara spesifik HANYA akan terjadi pada kondisi kehamilan…","options":["Ibu bergolongan Rhesus negatif (Rh-) mengandung janin Rhesus positif (Rh+) pada kehamilan kedua dan seterusnya (setelah tersensitisasi oleh persalinan anak pertama yang Rh+)","Ayah bergolongan Rhesus negatif dan Ibu Rhesus positif","Ibu bergolongan Rhesus positif (Rh+) mengandung janin Rhesus negatif (Rh-)","Ibu dan janin sama-sama bergolongan Rhesus negatif (Rh-)"],"key":[0],"why":"Ibu Rh− yang terpapar eritrosit janin Rh+ saat melahirkan anak pertama akan memproduksi antibodi Anti-Rh (kelas IgG). Pada kehamilan kedua dengan janin Rh+, IgG Anti-Rh ibu menembus plasenta dan melisiskan eritrosit janin.","src":"kuis"},{"id":"4.2.2","topic":"Sistem Sirkulasi","sub":"5.3 Penggolongan darah ABO-Rhesus, transfusi & eritroblastosis fetalis","kind":"pg","stem":"Apabila darah dari seorang donor bergolongan darah A ditransfusikan secara keliru dalam jumlah besar kepada resipien (penerima) yang bergolongan darah B, maka reaksi imunologis fatal yang langsung terjadi di dalam pembuluh darah resipien adalah…","options":["Aglutinogen B pada eritrosit donor digumpalkan oleh aglutinin Anti-B resipien","Aglutinogen A pada membran eritrosit donor diikat dan digumpalkan (aglutinasi) diikuti hemolisis oleh Aglutinin Anti-A (α) yang terdapat di dalam plasma darah resipien B","Leukosit donor memfagositosis jantung resipien","Trombosit resipien berubah menjadi golongan A"],"key":[1],"why":"Eritrosit donor golongan A membawa antigen (aglutinogen) A. Begitu masuk ke sirkulasi resipien golongan B (yang plasmanya kaya antibodi/aglutinin Anti-A), eritrosit donor langsung digumpalkan dan dilisiskan.","src":"kuis"},{"id":"4.3.0","topic":"Sistem Sirkulasi","sub":"5.4 Anatomi ruang-katup jantung, konduksi listrik & gelombang EKG","kind":"pg","stem":"Struktur yang bertindak sebagai pemacu detak alami (natural pacemaker) pada jantung manusia karena memiliki laju depolarisasi spontan tercepat (70–80 kali/menit) dan terletak di dinding atas Atrium Kanan adalah…","options":["Serabut Purkinje","Berkas His","Nodus Atrioventrikular (AV Node)","Nodus Sinoatrial (SA Node)"],"key":[3],"why":"Nodus Sinoatrial (SA Node) di dinding atrium kanan adalah pacemaker utama jantung yang menginisiasi setiap siklus detak jantung.","src":"kuis"},{"id":"4.3.1","topic":"Sistem Sirkulasi","sub":"5.4 Anatomi ruang-katup jantung, konduksi listrik & gelombang EKG","kind":"pg","stem":"Mengapa dinding otot (miokardium) pada Ventrikel Kiri jantung manusia sehat berukuran sekitar tiga kali lebih tebal dibandingkan dinding Ventrikel Kanan?","options":["Karena ventrikel kiri menampung volume darah tiga kali lebih banyak daripada ventrikel kanan","Karena darah kaya oksigen memiliki massa jenis tiga kali lebih berat daripada darah kaya CO2","Karena ventrikel kiri harus memompa darah kaya O2 melalui aorta ke SELURUH jaringan tubuh (sirkulasi sistemik) melawan resistensi pembuluh dan tekanan yang jauh lebih tinggi (~120 mmHg) dibandingkan ventrikel kanan yang hanya memompa darah jarak dekat ke paru-paru (~25 mmHg)","Karena katup bikuspidalis lebih berat daripada katup trikuspidalis"],"key":[2],"why":"Volume darah yang dipompa ventrikel kanan dan kiri per denyut adalah sama (~70 mL), namun Ventrikel Kiri membutuhkan gaya kontraksi jauh lebih besar untuk mendorong darah ke seluruh tubuh.","src":"kuis"},{"id":"4.3.2","topic":"Sistem Sirkulasi","sub":"5.4 Anatomi ruang-katup jantung, konduksi listrik & gelombang EKG","kind":"pg","stem":"Katup jantung yang terletak membatasi antara Atrium Kiri (Serambi Kiri) dan Ventrikel Kiri (Bilik Kiri) serta berfungsi mencegah aliran balik darah kaya O2 ke atrium kiri saat ventrikel kiri berkontraksi adalah…","options":["Katup Trikuspidalis (berdaun tiga)","Katup Semilunaris Aorta","Katup Semilunaris Pulmonal","Katup Bikuspidalis / Katup Mitral (berdaun dua)"],"key":[3],"why":"Ingat rumus Ka-Ti, Ki-Bi: Kanan = Trikuspidalis; Kiri = Bikuspidalis (Mitral).","src":"kuis"},{"id":"4.4.0","topic":"Sistem Sirkulasi","sub":"5.5 Siklus kardiak, curah jantung (CO), tekanan darah & sirkulasi ganda","kind":"pg","stem":"Urutan jalannya darah pada Peredaran Darah Kecil (Sirkulasi Pulmonal) manusia secara tepat adalah…","options":["Atrium Kanan → Vena Pulmonalis → Paru-paru → Arteri Pulmonalis → Ventrikel Kiri","Ventrikel Kanan (Bilik Kanan) → Arteri Pulmonalis (darah kaya CO2) → Kapiler Alveolus Paru-paru → Vena Pulmonalis (darah kaya O2) → Atrium Kiri (Serambi Kiri)","Ventrikel Kanan → Aorta → Paru-paru → Vena Kava → Atrium Kiri","Ventrikel Kiri → Aorta → Seluruh Tubuh → Vena Kava → Atrium Kanan"],"key":[1],"why":"Sirkulasi Pulmonal dimulai dari Ventrikel Kanan memompa darah deoksigenasi lewat Arteri Pulmonalis ke paru-paru, lalu darah teroksigenasi kembali lewat Vena Pulmonalis masuk ke Atrium Kiri.","src":"kuis"},{"id":"4.4.1","topic":"Sistem Sirkulasi","sub":"5.5 Siklus kardiak, curah jantung (CO), tekanan darah & sirkulasi ganda","kind":"pg","stem":"Satu jam setelah seseorang menyantap makanan yang kaya karbohidrat dan protein, pembuluh darah di dalam tubuh yang memiliki konsentrasi GLUKOSA dan ASAM AMINO terlarut paling tinggi adalah…","options":["Vena Porta Hepatika (pembuluh balik yang mengangkut darah langsung dari kapiler vili usus halus menuju ke organ Hati)","Arteri Koronaria","Arteri Pulmonalis","Vena Renalis"],"key":[0],"why":"Darah dari kapiler jonjot (vili) usus halus yang baru menyerap glukosa dan asam amino tidak langsung dibawa ke jantung, melainkan dialirkan melalui Vena Porta Hepatika menuju Hati (Hepar) untuk diatur kadarnya.","src":"kuis"},{"id":"4.4.2","topic":"Sistem Sirkulasi","sub":"5.5 Siklus kardiak, curah jantung (CO), tekanan darah & sirkulasi ganda","kind":"pg","stem":"Di antara pembuluh-pembuluh darah berikut, manakah pembuluh darah yang memiliki konsentrasi limbah UREA paling RENDAH (paling bersih dari urea)?","options":["Arteri Renalis (pembuluh yang baru masuk ke ginjal)","Vena Kava Inferior","Vena Hepatika (pembuluh yang baru keluar dari organ hati)","Vena Renalis (pembuluh balik yang baru keluar dari organ Ginjal setelah darah selesai menjalani filtrasi dan augmentasi di nefron)"],"key":[3],"why":"Urea dibentuk di Hati (sehingga Vena Hepatika paling kaya urea) dan dibuang di Ginjal (sehingga darah yang keluar meninggalkan ginjal melalui Vena Renalis paling bersih/rendah kadar ureanya).","src":"kuis"},{"id":"4.5.0","topic":"Sistem Sirkulasi","sub":"5.6 Histologi arteri-vena-kapiler, sistem limfatik & gangguan sirkulasi","kind":"pg","stem":"Manakah pernyataan berikut yang tepat membedakan struktur histologis dan sifat fisiologis antara Pembuluh Nadi (Arteri) dengan Pembuluh Balik (Vena) ukuran sedang?","options":["Dinding vena memiliki lapisan otot polos (tunika media) yang jauh lebih tebal dan elastis daripada arteri","Lumen arteri tampak gepeng dan lebih lebar dibandingkan vena pendampingnya","Arteri memiliki dinding tunika media yang tebal-elastis, bertekanan tinggi, dan tidak memiliki katup di sepanjang salurannya (kecuali di pangkal aorta); sedangkan Vena berdinding lebih tipis, bertekanan rendah, dan memiliki banyak katup satu arah di sepanjang salurannya","Jika pembuluh vena terpotong, darah akan memancar kuat seirama denyut jantung"],"key":[2],"why":"Arteri menahan tekanan sistolik tinggi sehingga tunika medianya sangat tebal dan elastis. Vena bertekanan sangat rendah sehingga membutuhkan banyak katup bulan sabit di sepanjang pembuluh agar darah tidak mengalir balik.","src":"kuis"},{"id":"4.5.1","topic":"Sistem Sirkulasi","sub":"5.6 Histologi arteri-vena-kapiler, sistem limfatik & gangguan sirkulasi","kind":"pg","stem":"Perbedaan patofisiologi antara gangguan pembuluh darah Aterosklerosis dan Arteriosklerosis adalah…","options":["Arteriosklerosis adalah pelebaran katup vena di sekitar anus","Aterosklerosis disebabkan oleh infeksi cacing filaria","Aterosklerosis terjadi di pembuluh vena kaki, sedangkan arteriosklerosis di kapiler paru","Aterosklerosis adalah penyempitan dinding dalam arteri akibat penumpukan plak lemak/kolesterol (LDL); sedangkan Arteriosklerosis adalah pengerasan dan hilangnya elastisitas dinding arteri akibat pengendapan zat kapur (kalsium / Ca2+)"],"key":[3],"why":"Ingat kata kuncinya: ATERO-sklerosis = plak Ateroma (lemak/kolesterol); ARTERIO-sklerosis = pengerasan dinding arteri akibat kalsifikasi (endapan kapur Ca2+). Sedangkan pelebaran vena di betis = Varises; di anus = Hemoroid (Wasir).","src":"kuis"},{"id":"4.5.2","topic":"Sistem Sirkulasi","sub":"5.6 Histologi arteri-vena-kapiler, sistem limfatik & gangguan sirkulasi","kind":"pg","stem":"Penyakit Kaki Gajah (Filariasis / Elephantiasis) yang menyebabkan pembengkakan luar biasa (edema kronis) pada tungkai bawah pasien disebabkan oleh infeksi cacing Wuchereria bancrofti (ditularkan nyamuk Culex) yang menyumbat…","options":["Pembuluh Limfa (Getah Bening) dan kelenjar limfa inguinal, sehingga cairan interstisial jaringan gagal dikembalikan ke sistem peredaran darah","Vena pulmonalis di paru-paru","Saluran ureter di ginjal","Arteri koronaria jantung"],"key":[0],"why":"Salah satu fungsi utama Sistem Limfatik adalah mengembalikan kelebihan cairan interstisial (~3 L/hari) dari ruang antarsel jaringan kembali ke vena darah. Jika cacing Filaria menyumbat pembuluh limfa, cairan menumpuk ekstrem di tungkai (kaki gajah).","src":"kuis"},{"id":"5.0.0","topic":"Sistem Respirasi","sub":"6.1 Anatomi saluran pernapasan, histologi trakea-bronkiolus & surfaktan","kind":"pg","stem":"Di sepanjang saluran pernapasan manusia, organ yang berfungsi sebagai persimpangan saluran napas dan saluran cerna, serta dilengkapi katup tulang rawan elastis EPIGLOTIS untuk menutup batang tenggorok saat menelan makanan adalah…","options":["Sakus alveolaris","Bronkiolus terminalis","Konka nasalis di rongga hidung","Faring dan pangkal Laring"],"key":[3],"why":"Faring adalah persimpangan jalur udara dan makanan; tepat di bawahnya terdapat Laring yang dilengkapi katup Epiglotis (menutup glotis laring saat menelan bolus makanan).","src":"kuis"},{"id":"5.0.1","topic":"Sistem Respirasi","sub":"6.1 Anatomi saluran pernapasan, histologi trakea-bronkiolus & surfaktan","kind":"pg","stem":"Udara yang dihirup melalui rongga hidung mengalami tiga proses penyesuaian fisik dan biologis sebelum mencapai paru-paru, yaitu…","options":["Pengubahan gas nitrogen menjadi amonia di rongga hidung","Pertukaran gas O2 dan CO2 secara langsung ke dalam otak","Pendinginan oleh tulang rawan, pengeringan oleh silia, dan penyerapan oksigen oleh konka","Penyaringan partikel debu oleh rambut hidung & lendir, penghangatan suhu udara oleh kapiler darah di Konka nasalis, serta pelembapan udara oleh sekresi mukus sel goblet"],"key":[3],"why":"Rongga hidung menyaring udara (rambut & mukus), menghangatkan udara sesuai suhu tubuh (~37°C oleh pleksus kapiler konka), dan melembapkan udara (uap air mukus).","src":"kuis"},{"id":"5.0.2","topic":"Sistem Respirasi","sub":"6.1 Anatomi saluran pernapasan, histologi trakea-bronkiolus & surfaktan","kind":"pg","stem":"Zat fosfolipid-protein yang disekresikan oleh sel Pneumosit Tipe II pada dinding alveolus paru-paru untuk menurunkan tegangan permukaan cairan alveolus sehingga alveolus mudah mengembang dan tidak kolaps saat ekspirasi adalah…","options":["Histamin","Enzim karbonat anhidrase","Hormon eritropoietin","Surfaktan paru"],"key":[3],"why":"Surfaktan (dipalmitoilfosfatidilkolin) menurunkan tegangan permukaan cairan pelapis alveolus agar alveolus tidak mengempis rapat (atelektasis) saat mengembuskan napas.","src":"kuis"},{"id":"5.1.0","topic":"Sistem Respirasi","sub":"6.2 Mekanika ventilasi paru: pernapasan dada vs perut & hukum Boyle","kind":"pg","stem":"Manakah urutan mekanisme sebab-akibat yang 100% TEPAT pada saat seseorang melakukan EKSPIRASI pada pernapasan perut?","options":["Udara keluar dari paru-paru → menyebabkan tekanan paru naik → otot diafragma berkontraksi mendatar","Otot diafragma BERELAKSASI → posisi diafragma kembali MELENGKUNG ke atas mendesak rongga dada → volume rongga dada mengecil → tekanan udara di dalam paru-paru naik melebihi tekanan atmosfer (> 760 mmHg) → udara mengalir keluar","Otot diafragma berkontraksi → diafragma melengkung ke atas → tekanan paru turun → udara keluar","Otot antartulang rusuk luar berkontraksi → tulang rusuk turun → udara keluar"],"key":[1],"why":"Ingat prinsip mutlak: Relaksasi otot diafragma membuat diafragma kembali melengkung ke atas → memperkecil volume rongga dada → menaikkan tekanan intrapulmoner (>760 mmHg) → mendorong udara keluar.","src":"kuis"},{"id":"5.1.1","topic":"Sistem Respirasi","sub":"6.2 Mekanika ventilasi paru: pernapasan dada vs perut & hukum Boyle","kind":"pg","stem":"Pada saat seorang penyanyi atau peniup terompet melakukan EKSPIRASI PAKSA (mengembuskan napas sekuat-kuatnya), otot pernapasan yang berkontraksi secara aktif untuk menarik tulang rusuk turun ke bawah dan menekan rongga dada adalah…","options":["Otot antartulang rusuk luar (interkostalis eksterna)","Otot antartulang rusuk DALAM (interkostalis interna) bersama otot dinding perut (abdominalis)","Otot sternokleidomastoideus di leher","Otot polos trakea"],"key":[1],"why":"Otot antartulang rusuk LUAR (eksterna) berkontraksi untuk INSPIRASI (mengangkat rusuk). Sedangkan otot antartulang rusuk DALAM (interna) dan otot perut berkontraksi khusus saat EKSPIRASI PAKSA (menarik rusuk turun).","src":"kuis"},{"id":"5.1.2","topic":"Sistem Respirasi","sub":"6.2 Mekanika ventilasi paru: pernapasan dada vs perut & hukum Boyle","kind":"pg","stem":"Hubungan fisik antara perubahan volume rongga toraks (dada) dan perubahan tekanan udara di dalam paru-paru selama siklus pernapasan bekerja berdasarkan hukum fisika gas pada suhu konstan, yaitu…","options":["Hukum Pascal","Hukum Boyle (P × V = konstan; tekanan berbanding terbalik dengan volume)","Hukum Avogadro","Hukum Archimedes"],"key":[1],"why":"Hukum Boyle menyatakan bahwa pada suhu tetap, tekanan gas berbanding terbalik dengan volumenya (P ∝ 1/V): saat volume paru membesar, tekanan udaranya turun sehingga udara luar tersedot masuk.","src":"kuis"},{"id":"5.2.0","topic":"Sistem Respirasi","sub":"6.3 Spirometri paru: volume, kapasitas pernapasan & ventilasi semenit","kind":"pg","stem":"Rumus yang tepat untuk menghitung KAPASITAS VITAL PARU-PARU (Vital Capacity / KV) seorang pasien dari data hasil pengukuran spirometer adalah…","options":["KV = Kapasitas Total Paru (KTP) + Volume Residu (VR)","KV = Volume Tidal (VT) + Volume Residu (VR)","KV = Volume Komplementer (VKI) − Volume Suplementer (VKP)","KV = Volume Tidal (VT) + Volume Cadangan Inspirasi / Komplementer (VKI) + Volume Cadangan Ekspirasi / Suplementer (VKP)"],"key":[3],"why":"Kapasitas Vital (KV) adalah jumlah seluruh volume udara yang dapat dipertukarkan secara maksimal: KV = VT + VKI + VKP (atau KTP − VR).","src":"kuis"},{"id":"5.2.1","topic":"Sistem Respirasi","sub":"6.3 Spirometri paru: volume, kapasitas pernapasan & ventilasi semenit","kind":"pg","stem":"Seorang pasien bernapas dengan frekuensi 15 kali/menit dan memiliki Volume Tidal (VT) sebesar 500 mL. Apabila volume Ruang Rugi Anatomis (Anatomical Dead Space di saluran hidung hingga bronkiolus) pasien tersebut adalah 150 mL, berapakah volume udara segar yang benar-benar mencapai alveolus per menit (Ventilasi Alveolar Efektif)?","options":["7.500 mL/menit","2.250 mL/menit","5.250 mL/menit [dihitung dari 15 × (500 − 150) mL]","350 mL/menit"],"key":[2],"why":"Setiap kali menarik napas 500 mL, sebanyak 150 mL tertinggal di ruang rugi saluran napas dan hanya 500 − 150 = 350 mL yang mencapai alveolus. Dalam 1 menit (15 napas): 15 × 350 mL = 5.250 mL/menit.","src":"kuis"},{"id":"5.2.2","topic":"Sistem Respirasi","sub":"6.3 Spirometri paru: volume, kapasitas pernapasan & ventilasi semenit","kind":"pg","stem":"Volume udara sekitar 1.000–1.200 mL yang tetap bertahan di dalam paru-paru dan tidak mungkin dikeluarkan meskipun seseorang telah mengembuskan napas sekuat-kuatnya disebut…","options":["Volume Suplementer (VKP)","Kapasitas Inspirasi","Volume Residu (Udara Sisa)","Volume Tidal"],"key":[2],"why":"Volume Residu (VR) menjaga alveolus tetap terbuka dan mencegah fluktuasi ekstrem gas darah di antara dua tarikan napas.","src":"kuis"},{"id":"5.3.0","topic":"Sistem Respirasi","sub":"6.4 Difusi gas alveolus-kapiler: hukum Fick & gradien tekanan parsial","kind":"pg","stem":"Proses pertukaran gas secara difusi di mana Oksigen (O2) berpindah dari kapiler darah sistemik (PO2 = 95 mmHg) menuju ke dalam sel-sel jaringan tubuh (PO2 < 40 mmHg), sedangkan Karbon Dioksida (CO2) berpindah dari sel jaringan menuju ke kapiler darah disebut…","options":["Ventilasi Pulmoner","Fosforilasi Oksidatif","Respirasi Internal (Respirasi Jaringan)","Respirasi Eksternal"],"key":[2],"why":"Pertukaran gas di paru-paru (Alveolus ↔ Kapiler Paru) = Respirasi Eksternal; pertukaran gas di jaringan tubuh (Kapiler Sistemik ↔ Sel Jaringan) = Respirasi Internal.","src":"kuis"},{"id":"5.3.1","topic":"Sistem Respirasi","sub":"6.4 Difusi gas alveolus-kapiler: hukum Fick & gradien tekanan parsial","kind":"pg","stem":"Berdasarkan Hukum Difusi Gas Fick [V = (A × D × ΔP) / T], kondisi patologis pada penyakit Pneumonia (paru-paru basah akibat infeksi di mana alveolus terendam cairan radang) menghambat penyerapan oksigen terutama karena…","options":["Memperbesar ketebalan jarak penghalang difusi (T) antara udara alveolus dan kapiler darah akibat penumpukan cairan eksudat","Menurunkan tekanan parsial CO2 di jaringan otot","Meningkatkan luas permukaan alveolus (A) secara berlebihan","Mengubah gas oksigen menjadi nitrogen"],"key":[0],"why":"Pada Pneumonia atau Edema Paru, cairan yang memenuhi alveolus dan ruang interstisial mempertebal jarak tempuh difusi (T membesar), sehingga menurut rumus Fick laju difusi O2 (V) berbanding terbalik dan turun drastis.","src":"kuis"},{"id":"5.3.2","topic":"Sistem Respirasi","sub":"6.4 Difusi gas alveolus-kapiler: hukum Fick & gradien tekanan parsial","kind":"pg","stem":"Energi yang menggerakkan perpindahan molekul gas O2 menembus epitel pipih alveolus menuju ke dalam eritrosit di kapiler paru-paru berasal dari…","options":["Energi kinetik difusi pasif murni akibat gradien (selisih) tekanan parsial PO2 yang lebih tinggi di alveolus (104 mmHg) dibandingkan di darah kapiler paru (40 mmHg)","Tarikan medan magnet zat besi hemoglobin","Hidrolisis molekul ATP oleh pompa oksigen aktif di membran alveolus","Kontraksi aktif silia di dalam alveolus"],"key":[0],"why":"Tidak ada pompa transpor aktif (ATP) untuk gas O2 maupun CO2 di seluruh tubuh manusia! Pertukaran gas 100% terjadi melalui difusi pasif sederhana menuruni gradien tekanan parsial.","src":"kuis"},{"id":"5.4.0","topic":"Sistem Respirasi","sub":"6.5 Transpor O2 & CO2 darah, kurva disosiasi HbO2 & efek Bohr-Haldane","kind":"pg","stem":"Sebagian besar (~70%) gas karbon dioksida (CO2) hasil respirasi seluler jaringan tubuh diangkut menuju ke paru-paru dalam bentuk…","options":["Gelembung gas bebas di dalam keping darah (trombosit)","Senyawa karboksihemoglobin (HbCO) yang stabil","Ion Bikarbonat (HCO3-) di dalam plasma darah, yang pembentukannya dari CO2 + H2O dikatalisis oleh enzim Karbonat Anhidrase di dalam sel darah merah (eritrosit)","Gas CO2 yang berikatan dengan atom besi Fe2+ pada gugus heme hemoglobin"],"key":[2],"why":"Jebakan klasik TKA: CO2 paling banyak (70%) diangkut sebagai ion Bikarbonat (HCO3-) di plasma darah setelah diubah oleh enzim Karbonat Anhidrase di dalam eritrosit. (Karbaminohemoglobin HbCO2 hanya 23%, sedangkan HbCO adalah ikatan racun Karbon Monoksida!).","src":"kuis"},{"id":"5.4.1","topic":"Sistem Respirasi","sub":"6.5 Transpor O2 & CO2 darah, kurva disosiasi HbO2 & efek Bohr-Haldane","kind":"pg","stem":"Berdasarkan Efek Bohr, apabila kadar CO2 di jaringan meningkat dan pH darah kapiler menurun (menjadi lebih asam), maka kurva disosiasi oksihemoglobin (HbO2) akan bergeser ke arah… yang berdampak…","options":["Bergeser ke KIRI → hemoglobin mengikat O2 lebih erat dan tidak mau melepaskannya ke jaringan","Bergeser vertikal ke atas → jumlah eritrosit bertambah dua kali lipat","Tidak mengalami pergeseran sama sekali","Bergeser ke KANAN → afinitas hemoglobin terhadap O2 menurun, sehingga mempermudah dan memperbanyak pelepasan (unloading) molekul O2 dari darah ke sel-sel jaringan yang sedang aktif"],"key":[3],"why":"Efek Bohr (dipicu oleh ↑CO2, ↓pH/asam, ↑Suhu, ↑2,3-BPG) menggeser kurva ke KANAN, yang menurunkan daya ikat Hb terhadap O2 sehingga HbO2 lebih mudah melepaskan O2 ke jaringan yang membutuhkan.","src":"kuis"},{"id":"5.4.2","topic":"Sistem Respirasi","sub":"6.5 Transpor O2 & CO2 darah, kurva disosiasi HbO2 & efek Bohr-Haldane","kind":"pg","stem":"Mengapa kurva disosiasi oksihemoglobin milik Hemoglobin Janin (HbF) terletak di sebelah KIRI dibandingkan kurva Hemoglobin Dewasa milik Ibu (HbA)?","options":["Agar darah janin dapat menyerahkan oksigen ke darah ibu","Karena HbF tidak memiliki atom besi","Karena janin sudah bernapas menggunakan alveolus paru-parunya di dalam air ketuban","Karena HbF memiliki afinitas (daya ikat) terhadap oksigen yang lebih TINGGI daripada HbA, sehingga pada tekanan parsial O2 plasenta yang rendah, HbF janin mampu menarik dan mengikat O2 yang dilepaskan oleh darah ibu"],"key":[3],"why":"Posisi kurva di sebelah KIRI berarti nilai P50 lebih rendah dan afinitas terhadap O2 lebih TINGGI. Hal ini mutlak diperlukan agar O2 berpindah dari HbA ibu menuju HbF janin di plasenta.","src":"kuis"},{"id":"5.5.0","topic":"Sistem Respirasi","sub":"6.6 Regulasi pusat napas (medula oblongata), adaptasi ketinggian & patologi","kind":"pg","stem":"Ketika seseorang menahan napas selama 1 menit, dorongan tak tertahankan dari pusat pernapasan di Medula Oblongata yang memaksa orang tersebut kembali menarik napas dipicu terutama oleh…","options":["Menurunnya kadar gas nitrogen di dalam alveolus","Meningkatnya konsentrasi gas Karbon Dioksida (CO2) dan ion Hidrogen (H+ / penurunan pH menjadi asam) di dalam darah arteri dan cairan serebrospinal yang merangsang kemoreseptor sentral","Menurunnya suhu darah di jantung","Mengeringnya lendir di rongga hidung"],"key":[1],"why":"Kemoreseptor sentral di medula oblongata jauh lebih sensitif terhadap kenaikan PCO2 dan penurunan pH (kenaikan H+) dibandingkan terhadap penurunan PO2.","src":"kuis"},{"id":"5.5.1","topic":"Sistem Respirasi","sub":"6.6 Regulasi pusat napas (medula oblongata), adaptasi ketinggian & patologi","kind":"pg","stem":"Apabila seseorang mengalami gangguan gagal napas atau hipoventilasi berat sehingga gas CO2 gagal dibuang dan menumpuk di dalam darah, maka keseimbangan asam-basa darah pasien tersebut akan mengalami…","options":["Asidosis respiratorik (pH darah turun < 7,35 karena tumpukan CO2 bereaksi dengan air membentuk asam karbonat H2CO3 yang melepaskan ion H+)","Penurunan jumlah eritrosit secara mendadak","Alkalosis respiratorik (pH darah naik > 7,45)","Peningkatan pH darah menjadi 8,0"],"key":[0],"why":"Penumpukan CO2 di darah menggeser kesetimbangan CO2 + H2O ⇌ H2CO3 ⇌ H+ + HCO3- ke arah kanan, meningkatkan konsentrasi ion H+ sehingga pH darah turun di bawah 7,35 (Asidosis Respiratorik).","src":"kuis"},{"id":"5.5.2","topic":"Sistem Respirasi","sub":"6.6 Regulasi pusat napas (medula oblongata), adaptasi ketinggian & patologi","kind":"pg","stem":"Penduduk asli yang tinggal di dataran tinggi pegunungan Andes atau Papua (> 3.500 meter dpl) memiliki jumlah sel darah merah (eritrosit) dan kadar hemoglobin per mililiter darah yang lebih tinggi dibandingkan penduduk pantai karena…","options":["Tekanan parsial oksigen (PO2) atmosfer yang rendah di pegunungan merangsang organ Ginjal mensekresikan hormon Eritropoietin (EPO) yang memacu pembentukan eritrosit di sumsum tulang","Kelenjar tiroid mengubah leukosit menjadi eritrosit","Suhu dingin pegunungan membekukan plasma darah","Penduduk pegunungan menghirup lebih banyak gas karbon monoksida"],"key":[0],"why":"Di dataran tinggi, kerapatan molekul udara dan tekanan parsial O2 rendah. Sebagai kompensasi jangka panjang, ginjal mengeluarkan hormon EPO untuk memperbanyak jumlah eritrosit pengangkut O2.","src":"kuis"},{"id":"6.0.0","topic":"Sistem Ekskresi & Integrasi","sub":"7.1 Anatomi ginjal, struktur mikroskopis nefron & vaskularisasi renal","kind":"pg","stem":"Manakah di antara struktur nefron berikut yang SELURUHNYA terletak di bagian KORTEKS (kulit ginjal)?","options":["Lengkung Henle, Pelvis renalis, dan Ureter","Glomerulus, Kapsula Bowman, Tubulus Kontortus Proksimal (TKP), dan Tubulus Kontortus Distal (TKD)","Lengkung Henle desendens dan Duktus kolektivus bagian bawah","Piramida renalis dan Kaliks mayor"],"key":[1],"why":"Badan Malpighi (Glomerulus + Kapsula Bowman), TKP, dan TKD berada di lapisan Korteks ginjal, sedangkan Lengkung Henle menjulur masuk ke lapisan Medula.","src":"kuis"},{"id":"6.0.1","topic":"Sistem Ekskresi & Integrasi","sub":"7.1 Anatomi ginjal, struktur mikroskopis nefron & vaskularisasi renal","kind":"pg","stem":"Urutan saluran yang dilalui oleh Urin Sesungguhnya mulai dari saat meninggalkan Duktus Kolektivus nefron hingga dikeluarkan dari tubuh secara berurutan adalah…","options":["Pelvis renalis (rongga ginjal) → Ureter → Vesika urinaria (kandung kemih) → Uretra","Uretra → Vesika urinaria → Ureter → Pelvis renalis","Kapsula Bowman → Ureter → TKP → Uretra","Pelvis renalis → Uretra → Vesika urinaria → Ureter"],"key":[0],"why":"Jangan tertukar antara Ureter dan Uretra! Dari ginjal (Pelvis renalis) menuju kandung kemih adalah sepasang URETER; dari kandung kemih keluar tubuh adalah satu saluran URETRA.","src":"kuis"},{"id":"6.0.2","topic":"Sistem Ekskresi & Integrasi","sub":"7.1 Anatomi ginjal, struktur mikroskopis nefron & vaskularisasi renal","kind":"pg","stem":"Proses pengeluaran zat-zat sisa metabolisme seluler (seperti urea, kreatinin, dan CO2) yang sudah tidak dibutuhkan tubuh lagi disebut Ekskresi. Manakah di antara peristiwa berikut yang BUKAN merupakan ekskresi, melainkan SEKRESI?","options":["Pengeluaran keringat oleh kelenjar sudorifera kulit saat cuaca panas","Pelepasan hormon Insulin oleh sel beta pankreas ke darah dan pengeluaran enzim amilase oleh kelenjar ludah","Pembuangan gas CO2 dan uap air oleh alveolus paru-paru","Pengeluaran cairan urin oleh ginjal"],"key":[1],"why":"Sekresi adalah pengeluaran senyawa kimia yang MASIH BERGUNA bagi proses fisiologis tubuh (seperti hormon dan enzim pencernaan), sedangkan Ekskresi membuang limbah metabolisme seluler.","src":"kuis"},{"id":"6.1.0","topic":"Sistem Ekskresi & Integrasi","sub":"7.2 Pembentukan urin I: mekanisme filtrasi glomerulus & reabsorpsi TKP","kind":"pg","stem":"Komponen di bawah ini yang dalam kondisi sehat ditemukan di dalam Urin Primer (filtrat di dalam Kapsula Bowman), tetapi sudah TIDAK ditemukan lagi (0%) di dalam Urin Sekunder setelah melewati Tubulus Kontortus Proksimal (TKP) adalah…","options":["Air dan ion natrium","Urea dan kreatinin","Sel darah merah dan albumin","Glukosa dan Asam Amino (karena 100% diserap kembali secara transpor aktif di TKP)"],"key":[3],"why":"Glukosa dan asam amino berukuran kecil sehingga lolos filtrasi masuk ke Urin Primer, namun 100% diserap kembali (reabsorpsi aktif) oleh epitel ber-mikrovili di Tubulus Kontortus Proksimal (TKP).","src":"kuis"},{"id":"6.1.1","topic":"Sistem Ekskresi & Integrasi","sub":"7.2 Pembentukan urin I: mekanisme filtrasi glomerulus & reabsorpsi TKP","kind":"pg","stem":"Sel-sel epitel pelapis Tubulus Kontortus Proksimal (TKP) memiliki struktur khusus berupa jutaan mikrovili (brush border) dan kepadatan organel mitokondria yang sangat tinggi karena…","options":["TKP harus berkontraksi memeras urin seperti otot jantung","TKP berfungsi memproduksi hormon insulin","TKP berfungsi memompa sel darah merah kembali ke arteri","TKP merupakan lokasi utama REABSORPSI AKTIF (yang membutuhkan banyak ATP dari mitokondria dan luas permukaan serap yang lebar dari mikrovili) untuk menyerap kembali 100% glukosa, asam amino, serta ~65% ion Na+ dan air"],"key":[3],"why":"Reabsorpsi 100% glukosa, asam amino, dan pemompaan Na+ di TKP membutuhkan transpor aktif yang mengonsumsi banyak ATP (mitokondria banyak) dan permukaan serap yang sangat luas (mikrovili brush border).","src":"kuis"},{"id":"6.1.2","topic":"Sistem Ekskresi & Integrasi","sub":"7.2 Pembentukan urin I: mekanisme filtrasi glomerulus & reabsorpsi TKP","kind":"pg","stem":"Mengapa di dalam Urin Primer orang yang sehat TIDAK ditemukan adanya sel darah merah (eritrosit) maupun protein plasma berukuran besar seperti Albumin?","options":["Karena albumin dan eritrosit sudah habis diserap kembali di lengkung Henle","Karena eritrosit hancur terkena asam klorida di ginjal","Karena pori endotel kapiler Glomerulus, membran basal bermuatan negatif, dan celah kaki Podosit Kapsula Bowman bertindak sebagai saringan selektif berdasarkan ukuran dan muatan yang menahan sel darah serta protein","Karena hati sudah mengubah seluruh albumin menjadi urea sebelum sampai ke ginjal"],"key":[2],"why":"Sawar filtrasi glomerulus (endotel berfenestra + membran basal bermuatan negatif + celah podosit) menahan komponen seluler darah dan molekul protein bermuatan negatif seperti Albumin.","src":"kuis"},{"id":"6.2.0","topic":"Sistem Ekskresi & Integrasi","sub":"7.3 Pembentukan urin II: lengkung Henle, augmentasi TKD & regulasi ADH-aldosteron","kind":"pg","stem":"Perbedaan sifat permeabilitas dan fungsi antara Lengkung Henle Segmen Desendens (Turun) dan Segmen Asendens (Naik) dalam mekanisme Countercurrent Multiplier di medula ginjal adalah…","options":["Segmen turun kedap air, sedangkan segmen naik sangat permeabel terhadap air","Keduanya berfungsi menghasilkan hormon adrenalin","Segmen turun memompa glukosa keluar, sedangkan segmen naik menyerap protein","Segmen Desendens (Turun) sangat permeabel terhadap AIR (sehingga air keluar secara osmosis ke medula yang asin); sedangkan Segmen Asendens (Naik) bersifat KEDAP (impermeabel) terhadap air namun secara aktif memompa keluar garam NaCl ke medula"],"key":[3],"why":"Prinsip Countercurrent Multiplier: Lengan Turun (Desendens) = keluar AIR secara osmosis (urin makin pekat); Lengan Naik (Asendens) = kedap air, pompa aktif keluar GARAM NaCl (menjaga medula tetap asin).","src":"kuis"},{"id":"6.2.1","topic":"Sistem Ekskresi & Integrasi","sub":"7.3 Pembentukan urin II: lengkung Henle, augmentasi TKD & regulasi ADH-aldosteron","kind":"pg","stem":"Pada tahap ke-3 pembentukan urin yaitu AUGMENTASI (Sekresi Tubulus) yang berlangsung di Tubulus Kontortus Distal (TKD), peristiwa fisiologis yang terjadi adalah…","options":["Penambahan/sekresi aktif zat-zat sisa dari kapiler peritubuler ke dalam urin sekunder, seperti ion Hidrogen (H+), ion Kalium (K+), NH4+, kreatinin, dan sisa metabolisme obat/penisilin hingga terbentuk Urin Sesungguhnya","Pengubahan amonia menjadi urea oleh enzim arginase","Penyaringan plasma darah bertekanan tinggi untuk memisahkan sel darah merah","Penyerapan kembali 100% glukosa dan asam amino ke kapiler darah"],"key":[0],"why":"Augmentasi adalah proses pembuangan aktif ion H+ (pengatur pH darah), K+, NH4+, kreatinin, dan sisa obat dari kapiler peritubuler masuk ke lumen TKD untuk dibuang bersama Urin Sesungguhnya.","src":"kuis"},{"id":"6.2.2","topic":"Sistem Ekskresi & Integrasi","sub":"7.3 Pembentukan urin II: lengkung Henle, augmentasi TKD & regulasi ADH-aldosteron","kind":"pg","stem":"Mengapa setelah seseorang mengonsumsi minuman beralkohol atau kopi berkafein tinggi, frekuensi buang air kecilnya meningkat dengan urin yang banyak dan encer?","options":["Karena kopi mengubah urea menjadi glukosa di kandung kemih","Karena alkohol melubangi kapsula Bowman","Karena alkohol dan kafein bersifat diuretik yang MENGHAMBAT pelepasan hormon ADH (Vasopresin) dari hipofisis posterior, sehingga reabsorpsi air di Duktus Kolektivus berkurang dan air banyak dibuang lewat urin","Karena kafein dan alkohol merangsang hipofisis mengeluarkan ADH sebanyak-banyaknya"],"key":[2],"why":"Alkohol dan kafein menghambat sekresi hormon ADH. Ketika kadar ADH darah turun, kanal Akuaporin-2 di duktus kolektivus ditarik masuk sehingga air tidak diserap kembali ke darah (urin menjadi banyak & encer, yang membuat peminum alkohol justru mengalami dehidrasi!).","src":"kuis"},{"id":"6.3.0","topic":"Sistem Ekskresi & Integrasi","sub":"7.4 Peran hati (hepar) dalam ekskresi: siklus ornitin & perombakan bilirubin","kind":"pg","stem":"Urutan senyawa asam amino antara dan enzim pemecah akhir pada Siklus Ornitin (Siklus Pembentukan Urea) di dalam sel hati (hepatosit) yang tepat adalah…","options":["Sitrulin → Ornitin → Bilirubin → dipecah oleh enzim renin menjadi urea","Arginin → Sitrulin → Ornitin → dibantu enzim katalase menghasilkan amonia","Ornitin → Kreatinin → Asam urat","Ornitin (mengikat NH3 + CO2) → Sitrulin (mengikat NH3) → Arginin → dipecah oleh enzim Arginase menjadi UREA + Ornitin kembali"],"key":[3],"why":"Hafalkan jembatan keledai 'Orang Sakit Ada Ubatnya': Ornitin → Sitrulin → Arginin → (dikatalisis enzim Arginase) → Urea + Ornitin.","src":"kuis"},{"id":"6.3.1","topic":"Sistem Ekskresi & Integrasi","sub":"7.4 Peran hati (hepar) dalam ekskresi: siklus ornitin & perombakan bilirubin","kind":"pg","stem":"Apabila dari hasil perombakan Hemoglobin eritrosit tua di dalam organ Hati ditelusuri nasibnya, komponen yang TIDAK diekskresikan keluar tubuh melainkan disimpan di hati (sebagai feritin) dan dikirim kembali ke sumsum tulang merah untuk bahan baku eritrosit baru adalah…","options":["Biliverdin dan Bilirubin","Sterkobilin dan Urobilin","Cincin porfirin heme","Unsur Zat Besi (Fe) dan rantai polipeptida Globin"],"key":[3],"why":"Tubuh sangat menghemat zat besi dan asam amino: komponen Globin dan Zat Besi (Fe) didaur ulang 100%, sedangkan yang dibuang menjadi pigmen empedu (bilirubin) hanyalah cincin porfirin heme tanpa besi.","src":"kuis"},{"id":"6.3.2","topic":"Sistem Ekskresi & Integrasi","sub":"7.4 Peran hati (hepar) dalam ekskresi: siklus ornitin & perombakan bilirubin","kind":"pg","stem":"Zat warna (pigmen) turunan bilirubin yang memberikan warna KUNING khas pada cairan urin sehat dan warna COKELAT pada feses secara berurutan adalah…","options":["Sterkobilin pada urin dan Urobilin pada feses","Urobilin pada urin dan Sterkobilin pada feses","Biliverdin pada urin dan Albumin pada feses","Urea pada urin dan Amonia pada feses"],"key":[1],"why":"Ingat huruf awalnya: Urobilin = warna kuning Urin; Sterkobilin = warna cokelat feses (stercus = feses).","src":"kuis"},{"id":"6.4.0","topic":"Sistem Ekskresi & Integrasi","sub":"7.5 Histologi kulit, kelenjar keringat & mekanisme termoregulasi hipotalamus","kind":"pg","stem":"Apabila kita mengamati penampang histologis kulit manusia dari permukaan paling luar menuju ke arah dalam, urutan 5 sub-lapisan pada EPIDERMIS yang benar adalah…","options":["Stratum basale → spinosum → granulosum → lusidum → korneum","Stratum granulosum → korneum → basale → lusidum","Stratum korneum (tanduk) → Stratum lusidum → Stratum granulosum → Stratum spinosum → Stratum basale (germinativum)","Dermis → Hipodermis → Korneum → Basale"],"key":[2],"why":"Ingat jembatan keledai dari luar ke dalam: Come Let's Get Sun Burned → Korneum (sel mati berkeratin yang mengelupas) → Lusidum → Granulosum → Spinosum → Basale/Germinativum (sel induk pembelah mitosis & sel melanosit).","src":"kuis"},{"id":"6.4.1","topic":"Sistem Ekskresi & Integrasi","sub":"7.5 Histologi kulit, kelenjar keringat & mekanisme termoregulasi hipotalamus","kind":"pg","stem":"Di lapisan kulit manakah terletak Kelenjar Keringat (Glandula sudorifera), Kelenjar Minyak (Glandula sebasea), folikel rambut, kapiler darah, serta ujung-ujung saraf indera peraba?","options":["Di lapisan DERMIS (Korium / Kulit Jangat)","Di lapisan Stratum korneum epidermis","Di permukaan luar keratin","Di lapisan Stratum lusidum epidermis"],"key":[0],"why":"Epidermis sama sekali tidak memiliki pembuluh darah maupun kelenjar. Seluruh kelenjar keringat, kelenjar minyak, folikel rambut, pembuluh darah, dan korpuskula saraf terletak di lapisan DERMIS!","src":"kuis"},{"id":"6.4.2","topic":"Sistem Ekskresi & Integrasi","sub":"7.5 Histologi kulit, kelenjar keringat & mekanisme termoregulasi hipotalamus","kind":"pg","stem":"Bagaimana cara keluarnya keringat ke permukaan kulit mampu menurunkan suhu tubuh manusia saat cuaca panas atau setelah berolahraga?","options":["Karena air keringat menyerap kalor (panas laten penguapan ~580 kalori per gram air) dari permukaan kulit dan pembuluh darah dermis pada saat keringat tersebut MENGUAP (berevaporasi) menjadi uap air","Karena kelenjar keringat mengubah panas menjadi ATP","Karena garam NaCl di dalam keringat menghasilkan suhu dingin secara kimiawi","Karena pori-pori kulit menyedot udara dingin masuk ke dalam darah"],"key":[0],"why":"Pendinginan tubuh oleh keringat bekerja berdasarkan fisika Kalor Laten Penguapan (Evaporative Cooling): untuk berubah wujud dari cair menjadi uap, molekul air keringat menyerap energi panas dari kulit.","src":"kuis"},{"id":"6.5.0","topic":"Sistem Ekskresi & Integrasi","sub":"7.6 Integrasi antarsistem (sirkulasi-respirasi-ekskresi), RAAS & uji urin klinis","kind":"pg","stem":"Perhatikan keterkaitan luar biasa antara Hati, Ginjal, Paru-paru, dan Kelenjar Adrenal dalam sistem RAAS (Renin-Angiotensin-Aldosterone System) saat seseorang mengalami penurunan tekanan darah akibat perdarahan atau dehidrasi! Urutan kerja keempat organ tersebut yang tepat adalah…","options":["Ginjal melepaskan enzim Renin → mengubah Angiotensinogen (dari Hati) menjadi Angiotensin I → diubah oleh enzim ACE (di kapiler Paru-paru) menjadi Angiotensin II → memicu vasokonstriksi arteriol serta merangsang Korteks Adrenal melepaskan hormon Aldosteron untuk menyerap kembali Na+ dan air di nefron Ginjal","Paru-paru melepas Renin → Hati melepas Aldosteron → Ginjal menyerap glukosa","Hati melepaskan Insulin → Ginjal membuang Na+ ke urin → tekanan darah naik","Kelenjar tiroid melepaskan ADH untuk menyempitkan bronkus paru-paru"],"key":[0],"why":"Sistem RAAS adalah contoh puncak integrasi 4 organ: Ginjal (sekresi enzim Renin) + Hati (sintesis substrat Angiotensinogen) + Paru-paru (enzim pengonversi ACE) + Korteks Adrenal (sekresi hormon Aldosteron) → menaikkan kembali volume dan tekanan darah!","src":"kuis"},{"id":"6.5.1","topic":"Sistem Ekskresi & Integrasi","sub":"7.6 Integrasi antarsistem (sirkulasi-respirasi-ekskresi), RAAS & uji urin klinis","kind":"pg","stem":"Dalam menjaga homeostasis pH darah agar tetap berada di rentang 7,35–7,45 saat tubuh mengalami kondisi asam (asidosis metabolik), Sistem Respirasi dan Sistem Ekskresi (Ginjal) bekerja sama dengan cara…","options":["Paru-paru melakukan hiperventilasi untuk membuang lebih banyak gas CO2 (mengurangi asam karbonat darah), sedangkan Tubulus Ginjal membuang (mensekresikan) ion H+ ke dalam urin serta menyerap kembali (mereabsorpsi) ion penyangga Bikarbonat (HCO3-) ke dalam darah","Paru-paru menahan CO2 dan ginjal membuang ion bikarbonat (HCO3-)","Paru-paru menyerap amonia dan ginjal memproduksi asam laktat","Ginjal menghentikan filtrasi glomerulus"],"key":[0],"why":"Kompensasi ganda mengatasi asidosis (darah terlalu asam): (1) Paru-paru mempercepat napas (hiperventilasi) membuang CO2; (2) Nefron ginjal mensekresikan H+ (dan NH4+) ke urin pada tahap augmentasi sekaligus mereabsorpsi ion basa HCO3- ke darah.","src":"kuis"},{"id":"6.5.2","topic":"Sistem Ekskresi & Integrasi","sub":"7.6 Integrasi antarsistem (sirkulasi-respirasi-ekskresi), RAAS & uji urin klinis","kind":"pg","stem":"Prinsip kerja mesin Cuci Darah (Hemodialisis) yang menggantikan fungsi ginjal pada pasien gagal ginjal kronis (uremia) didasarkan pada mekanisme…","options":["Pemanasan darah hingga suhu 100°C agar urea menguap","Penambahan enzim arginase ke dalam kantung darah pasien","Fagositosis urea oleh sel darah putih di dalam mesin","Difusi pasif dan ultrafiltrasi zat sisa (urea, kreatinin, kelebihan K+) dari darah pasien melintasi membran semipermeabel (dialiser) menuju cairan dialisat yang tidak mengandung urea"],"key":[3],"why":"Dalam mesin hemodialisis, darah mengalir di satu sisi membran semipermeabel sementara cairan dialisat steril mengalir di sisi sebelahnya. Karena cairan dialisat memiliki konsentrasi urea = 0, urea dari darah berdifusi keluar menuju dialisat, sedangkan sel darah dan protein tertahan oleh pori membran.","src":"kuis"},{"id":"7.0.0","topic":"Sistem Imun","sub":"8.1 Pertahanan non-spesifik lini pertama: sawar fisik, kimiawi & flora normal","kind":"pg","stem":"Manakah di antara komponen pertahanan tubuh berikut yang SELURUHNYA termasuk ke dalam Pertahanan Non-Spesifik Lini Pertama (Sawar Eksternal)?","options":["Kulit berkeratin utuh, membran mukosa bersilia, asam klorida (HCl) lambung, serta enzim lisozim pada air mata dan saliva","Limfosit B, Limfosit T, dan Antibodi IgG","Sel Mast, Histamin, dan Kompleks MHC Kelas II","Makrofag, Sel Natural Killer (NK), dan Interferon"],"key":[0],"why":"Pertahanan Non-Spesifik Lini Pertama mencakup penghalang fisik, kimiawi, dan flora normal di permukaan tubuh: kulit, mukus, silia, HCl lambung, sebum asam kulit, dan enzim lisozim.","src":"kuis"},{"id":"7.0.1","topic":"Sistem Imun","sub":"8.1 Pertahanan non-spesifik lini pertama: sawar fisik, kimiawi & flora normal","kind":"pg","stem":"Mekanisme molekuler enzim Lisozim (yang terdapat pada air mata, air liur, dan keringat) dalam melumpuhkan bakteri penginvasi adalah dengan cara…","options":["Mengikat subunit 30S ribosom bakteri","Menghidrolisis ikatan antara gula NAG dan NAM pada polimer peptidoglikan dinding sel bakteri sehingga dinding sel rapuh dan bakteri mengalami lisis osmotik","Membentuk memori imunologis terhadap virus","Memfagositosis bakteri secara utuh seperti makrofag"],"key":[1],"why":"Enzim lisozim adalah muramidase alami yang memotong tulang punggung polisakarida peptidoglikan pada dinding sel bakteri (terutama sangat efektif pada bakteri Gram positif).","src":"kuis"},{"id":"7.0.2","topic":"Sistem Imun","sub":"8.1 Pertahanan non-spesifik lini pertama: sawar fisik, kimiawi & flora normal","kind":"pg","stem":"Konsumsi antibiotik spektrum luas dalam jangka panjang sering kali menimbulkan efek samping berupa sariawan jamur (kandidiasis oleh Candida albicans) di mulut atau diare akibat bakteri Clostridium difficile karena antibiotik tersebut…","options":["Merangsang pembelahan mitosis jamur secara langsung","Mengubah sel epitel usus menjadi sel jamur","Menurunkan suhu tubuh di bawah 30°C","Membunuh populasi bakteri menguntungkan (Flora Normal / Mikrobioma) yang bertindak sebagai sawar biologis lini pertama, sehingga patogen oportunistik kehilangan kompetitor dan tumbuh pesat"],"key":[3],"why":"Bakteri flora normal melindungi mukosa melalui eksklusi kompetitif (memperebutkan nutrisi & ruang serta menjaga pH asam). Jika flora normal mati terbunuh antibiotik, jamur Candida (eukariotik yang kebal antibiotik) tumbuh tak terkendali.","src":"kuis"},{"id":"7.1.0","topic":"Sistem Imun","sub":"8.2 Pertahanan non-spesifik lini kedua: fagositosis, sel NK, interferon & komplemen","kind":"pg","stem":"Urutan tahapan proses FAGOSITOSIS bakteri oleh sel Makrofag atau Neutrofil yang tepat dari awal hingga akhir adalah…","options":["Kemotaksis (mendekati sinyal kimia bakteri) → Adhesi (perlekatan) → Ingesti (penelanan dengan pseudopodia membentuk kantung Fagosom) → Fusi fagosom dengan Lisosom membentuk Fagolisosom → Pencernaan oleh enzim hidrolitik & H2O2 → Eksositosis sisa","Opsonisasi oleh ribosom → bakteri masuk ke mitokondria makrofag","Fagolisosom → Fagosom → Kemotaksis → Adhesi → Eksositosis","Eksositosis → Ingesti → Lisosom memecahkan inti makrofag"],"key":[0],"why":"Tahapan baku fagositosis: Kemotaksis → Adhesi → Ingesti (terbentuk vesikel Fagosom) → Peleburan Fagosom + Lisosom (terbentuk Fagolisosom) → Penghancuran enzimatik & oksidatif → Eksositosis badan residu.","src":"kuis"},{"id":"7.1.1","topic":"Sistem Imun","sub":"8.2 Pertahanan non-spesifik lini kedua: fagositosis, sel NK, interferon & komplemen","kind":"pg","stem":"Pernyataan yang tepat mengenai perbedaan antara kerja Interferon dan kerja Antibodi dalam sistem pertahanan tubuh adalah…","options":["Interferon khusus membunuh cacing parasit, sedangkan antibodi membunuh bakteri","Interferon membentuk memori imunologis seumur hidup","Interferon adalah protein sitokin non-spesifik yang dilepaskan oleh sel yang terinfeksi virus untuk menginduksi kondisi antivirus pada sel-sel tetangga yang masih sehat; sedangkan Antibodi adalah protein imunoglobulin spesifik yang diproduksi oleh Sel B Plasma untuk mengikat epitop antigen tertentu","Interferon diproduksi oleh limfosit B, sedangkan antibodi diproduksi oleh sel epitel"],"key":[2],"why":"Interferon termasuk pertahanan non-spesifik lini kedua (bekerja memperingatkan sel tetangga sehat agar memblokir replikasi virus apa pun), sedangkan Antibodi termasuk pertahanan spesifik humoral dari Sel Plasma.","src":"kuis"},{"id":"7.1.2","topic":"Sistem Imun","sub":"8.2 Pertahanan non-spesifik lini kedua: fagositosis, sel NK, interferon & komplemen","kind":"pg","stem":"Ketika sistem Protein Komplemen (C1–C9) di dalam plasma darah teraktivasi pada permukaan membran sel bakteri, protein komplemen C5b hingga C9 akan merakit struktur silinder berlubang bernama MAC (Membrane Attack Complex) yang berfungsi untuk…","options":["Membungkus bakteri agar tahan terhadap panas","Menyuntikkan RNA ke dalam bakteri","Mengubah bakteri menjadi sel darah merah","Melubangi membran plasma bakteri sehingga air dan ion menyerbu masuk secara osmotik hingga sel bakteri membengkak dan pecah (sitolisis)"],"key":[3],"why":"Kompleks Serangan Membran (MAC, C5b–C9) membentuk pori transmembran permanen pada dinding/membran bakteri sehingga terjadi lisis osmotik.","src":"kuis"},{"id":"7.2.0","topic":"Sistem Imun","sub":"8.3 Respon inflamasi akut (histamin, diapedesis, kemotaksis) & mekanisme demam","kind":"pg","stem":"Dalam respons inflamasi akut (peradangan lokal), zat kimia mediator utama yang dilepaskan oleh Sel Mast dan Basofil untuk memicu pelebaran pembuluh darah lokal (vasodilatasi) serta meningkatkan permeabilitas kapiler adalah…","options":["Hemoglobin","Enzim amilase","Insulin","Histamin"],"key":[3],"why":"Histamin yang dilepaskan dari granula Sel Mast dan Basofil adalah vasodilator dan peningkat permeabilitas kapiler utama pada inflamasi maupun reaksi alergi.","src":"kuis"},{"id":"7.2.1","topic":"Sistem Imun","sub":"8.3 Respon inflamasi akut (histamin, diapedesis, kemotaksis) & mekanisme demam","kind":"pg","stem":"Proses keluarnya sel darah putih (Neutrofil dan Monosit) dengan cara memipihkan selnya dan menyelip menembus pori-pori di antara sel endotel dinding kapiler darah menuju ke jaringan yang mengalami infeksi disebut…","options":["Apoptosis","Aglutinasi","Diapedesis (Ekstravasasi)","Presipitasi"],"key":[2],"why":"Kemampuan leukosit menembus keluar dinding pembuluh kapiler menuju jaringan ikat disebut Diapedesis, sedangkan gerak terarahnya mengikuti gradien zat kimia menuju lokasi kuman disebut Kemotaksis.","src":"kuis"},{"id":"7.2.2","topic":"Sistem Imun","sub":"8.3 Respon inflamasi akut (histamin, diapedesis, kemotaksis) & mekanisme demam","kind":"pg","stem":"Ketika seseorang mulai mengalami demam akibat infeksi bakteri (set-point termostat di hipotalamus baru saja dinaikkan oleh Prostaglandin E2 dari 37°C menjadi 39°C), mengapa orang tersebut justru merasa kedinginan dan menggigil padahal suhu tubuhnya sedang naik?","options":["Karena bakteri menyerap seluruh panas tubuh","Karena pusat suhu berpindah dari hipotalamus ke sumsum tulang belakang","Karena kelenjar keringat mengeluarkan es","Karena titik patokan (set-point) di hipotalamus sudah berada di angka 39°C, sehingga suhu darah aktual yang masih 37°C dibaca oleh hipotalamus sebagai 'terlalu dingin (2 derajat di bawah target)', akibatnya hipotalamus memerintahkan vasokonstriksi kulit dan otot menggigil untuk memanaskan tubuh hingga mencapai 39°C"],"key":[3],"why":"Saat set-point hipotalamus direset naik ke 39°C oleh pirogen/PGE2, suhu tubuh normal 37°C dirasakan sebagai kondisi hipotermia relatif oleh otak, sehingga tubuh menggigil aktif untuk menaikkan suhu mencapai set-point baru tersebut.","src":"kuis"},{"id":"7.3.0","topic":"Sistem Imun","sub":"8.4 Imunitas adaptif humoral: limfosit B, seleksi klonal & 5 kelas antibodi","kind":"pg","stem":"Manakah pasangan kelas Imunoglobulin (Antibodi) dan fungsi spesifiknya berikut yang 100% TEPAT?","options":["IgM — satu-satunya antibodi yang dapat menembus plasenta dari ibu ke janin","IgG — antibodi monomer paling melimpah di darah (80%), mendominasi Respon Imun Sekunder, dan satu-satunya yang mampu menembus plasenta untuk melindungi janin","IgE — antibodi utama di dalam Air Susu Ibu (ASI) dan air mata","IgA — antibodi pentamer pemicu utama syok anafilaktik alergi"],"key":[1],"why":"Hafalkan matriks GAMED: IgG = menembus plasenta & respon sekunder; IgA = ASI/kolostrum, air mata, saliva, mukosa; IgM = pentamer pertama respon primer akut; IgE = alergi (sel mast/histamin) & infeksi cacing; IgD = reseptor permukaan sel B naif.","src":"kuis"},{"id":"7.3.1","topic":"Sistem Imun","sub":"8.4 Imunitas adaptif humoral: limfosit B, seleksi klonal & 5 kelas antibodi","kind":"pg","stem":"Pada struktur molekul antibodi berbentuk huruf Y yang tersusun atas 2 rantai berat (heavy chains) dan 2 rantai ringan (light chains), bagian ujung kedua lengan atas Y yang memiliki urutan asam amino sangat bervariasi untuk mengikat epitop antigen secara spesifik seperti gembok dan kunci disebut…","options":["Daerah Konstan (Fc) batang bawah","Kompleks serangan membran","Jembatan fosfodiester","Daerah Variabel (Fab / Paratop pengikat antigen)"],"key":[3],"why":"Ujung lengan atas Y adalah Daerah Variabel (fragmen Fab) yang membentuk celah Paratop untuk mengikat Epitop antigen secara spesifik. Batang bawah Y adalah Daerah Konstan (fragmen Fc) yang menentukan kelas Ig (G, A, M, E, D).","src":"kuis"},{"id":"7.3.2","topic":"Sistem Imun","sub":"8.4 Imunitas adaptif humoral: limfosit B, seleksi klonal & 5 kelas antibodi","kind":"pg","stem":"Dalam teknologi bioteknologi kesehatan untuk memproduksi Antibodi Monoklonal (misalnya untuk alat deteksi kehamilan hCG atau terapi target sel kanker), para ilmuwan melakukan fusi (penggabungan) dua jenis sel membentuk sel Hibridoma, yaitu antara…","options":["Sel keping darah (trombosit) dengan virus bakteriofag","Sel T Sitotoksik dengan sel otot jantung","Sel Limfosit B (penghasil satu jenis antibodi spesifik) dengan Sel Mieloma / Kanker sumsum tulang (yang memiliki kemampuan membelah diri secara abadi di dalam kultur)","Sel darah merah (eritrosit) dengan sel bakteri E. coli"],"key":[2],"why":"Sel Limfosit B mampu membuat antibodi spesifik tetapi berumur pendek di kultur; sedangkan Sel Mieloma mampu membelah tak terbatas. Fusi keduanya (dengan polietilen glikol/PEG) menghasilkan sel Hibridoma yang membelah abadi sambil memproduksi Antibodi Monoklonal murni.","src":"kuis"},{"id":"7.4.0","topic":"Sistem Imun","sub":"8.5 Empat mekanisme kerja antibodi (PLAN) dalam melumpuhkan antigen","kind":"pg","stem":"Perbedaan yang tepat antara mekanisme kerja antibodi secara AGLUTINASI dan PRESIPITASI adalah…","options":["Aglutinasi dilakukan oleh Sel T Sitotoksik, sedangkan presipitasi oleh Sel NK","Presipitasi hanya terjadi di luar tubuh manusia","Aglutinasi adalah penggumpalan antigen berbentuk PARTIKEL SEL UTUH (seperti sel bakteri atau eritrosit asing); sedangkan Presipitasi adalah pengendapan molekul ANTIGEN TERLARUT (protein/toksin bebas di cairan plasma) menjadi kompleks yang tidak larut","Aglutinasi melubangi membran sel, sedangkan presipitasi memperbaiki dinding sel"],"key":[2],"why":"Ingat bedanya: Sel utuh (bakteri/eritrosit) yang digumpalkan = Aglutinasi; Molekul protein antigen terlarut yang diendapkan = Presipitasi.","src":"kuis"},{"id":"7.4.1","topic":"Sistem Imun","sub":"8.5 Empat mekanisme kerja antibodi (PLAN) dalam melumpuhkan antigen","kind":"pg","stem":"Ketika antibodi IgG yang dihasilkan pascavaksinasi menempel menyelubungi seluruh protein Spike pada permukaan kapsid/amplop virus sehingga virus tersebut gagal berikatan dengan reseptor ACE2 pada sel epitel paru-paru manusia, mekanisme kerja antibodi ini disebut…","options":["Netralisasi virus","Fiksasi komplemen MAC","Diapedesis","Presipitasi"],"key":[0],"why":"Penyelubungan permukaan virus atau situs aktif toksin oleh antibodi sehingga gagal menempel pada reseptor sel inang disebut Netralisasi.","src":"kuis"},{"id":"7.4.2","topic":"Sistem Imun","sub":"8.5 Empat mekanisme kerja antibodi (PLAN) dalam melumpuhkan antigen","kind":"pg","stem":"Proses di mana antibodi IgG (atau protein komplemen C3b) melapisi permukaan dinding bakteri berkapsul licin sehingga bakteri tersebut menjadi sangat mudah dikenali, ditempeli, dan ditelan oleh sel Makrofag disebut…","options":["Opsonisasi","Kemotaksis negatif","Pinocytosis","Transformasi"],"key":[3],"why":"Opsonisasi berasal dari kata Yunani yang berarti 'menyiapkan makanan untuk disantap': antibodi IgG dan C3b bertindak sebagai opsonin yang menjembatani bakteri dengan reseptor permukaan makrofag.","src":"kuis"},{"id":"7.5.0","topic":"Sistem Imun","sub":"8.6 Imunitas adaptif seluler: MHC kelas I vs II, sel T helper & sitotoksik","kind":"pg","stem":"Baik Limfosit B maupun Limfosit T sama-sama dibentuk dari sel punca hematopoietik di Sumsum Tulang Merah. Namun keduanya dinamai 'Sel B' dan 'Sel T' berdasarkan organ tempat keduanya mengalami pematangan (maturasi) dan seleksi imunokompetensi, yaitu…","options":["Sel B matang di Kelenjar Tiroid, sedangkan Sel T matang di Tonsil","Sel B matang di Kelenjar Timus, sedangkan Sel T matang di Sumsum Tulang","Sel B matang tetap di Sumsum Tulang (Bone Marrow), sedangkan Sel T bermigrasi dan mengalami pematangan di Kelenjar Timus (Thymus)","Sel B matang di Limpa (Spleen), sedangkan Sel T matang di Hati"],"key":[2],"why":"B = Bone Marrow (Sumsum Tulang); T = Thymus (Kelenjar Timus di rongga dada atas).","src":"kuis"},{"id":"7.5.1","topic":"Sistem Imun","sub":"8.6 Imunitas adaptif seluler: MHC kelas I vs II, sel T helper & sitotoksik","kind":"pg","stem":"Sesuai kaidah restriksi MHC (Major Histocompatibility Complex), pasangan yang 100% BENAR antara jenis molekul MHC, sel yang mengekspresikannya, dan jenis Limfosit T yang mengenalinya adalah…","options":["MHC Kelas II — terdapat pada eritrosit dewasa — dikenali oleh Sel NK","MHC Kelas I — hanya pada sel makrofag — dikenali oleh Sel T Helper (CD4+)","MHC Kelas I — terdapat pada seluruh sel tubuh berinti — menyajikan antigen intraseluler (virus/tumor) kepada Sel T Sitotoksik (CD8+); sedangkan MHC Kelas II — terdapat khusus pada sel APC (Makrofag, Sel Dendritik, Sel B) — menyajikan antigen eksogen kepada Sel T Helper (CD4+)","MHC Kelas I — dikenali oleh antibodi IgE"],"key":[2],"why":"Gunakan rumus perkalian 8: MHC I × CD8+ = 8 (semua sel berinti → Sel T Sitotoksik); MHC II × CD4+ = 8 (sel APC profesional → Sel T Helper).","src":"kuis"},{"id":"7.5.2","topic":"Sistem Imun","sub":"8.6 Imunitas adaptif seluler: MHC kelas I vs II, sel T helper & sitotoksik","kind":"pg","stem":"Setelah infeksi virus berhasil diberantas tuntas oleh tubuh, aktivitas Sel T Sitotoksik dan Sel B harus segera diredam dan dihentikan agar tidak kebablasan merusak jaringan tubuh yang sehat. Subpopulasi limfosit T yang bertugas menekan/menghentikan respon imun tersebut dan menjaga self-tolerance adalah…","options":["Sel T Regulator / Supresor (Treg)","Sel B Plasma","Sel Mast","Sel T Memori"],"key":[0],"why":"Sel T Regulator / Supresor (Treg) mengeluarkan sitokin imunosupresif (seperti IL-10 dan TGF-β) untuk mengerem respon imun setelah patogen musnah dan mencegah penyakit autoimun.","src":"kuis"},{"id":"7.6.0","topic":"Sistem Imun","sub":"8.7 Memori imunologis, klasifikasi 4 kekebalan & imunopatologi (alergi, autoimun, HIV)","kind":"pg","stem":"Perhatikan empat contoh perolehan kekebalan tubuh berikut:\n(1) Bayi menerima antibodi IgG dari ibu melalui plasenta dan IgA melalui ASI.\n(2) Seseorang sembuh dari penyakit Cacar Air dan menjadi kebal seumur hidup.\n(3) Balita disuntik vaksin BCG dan DPT di Posyandu.\n(4) Petani yang digigit ular kobra disuntik Serum Anti-Bisa Ular (SABU) di IGD.\nPasangan yang tepat untuk Kekebalan Pasif Alami, Kekebalan Aktif Alami, Kekebalan Aktif Buatan, dan Kekebalan Pasif Buatan secara berurutan adalah…","options":["(1) Aktif Alami — (2) Pasif Alami — (3) Pasif Buatan — (4) Aktif Buatan","(1) Pasif Buatan — (2) Aktif Buatan — (3) Aktif Alami — (4) Pasif Alami","(1) Aktif Buatan — (2) Pasif Alami — (3) Aktif Alami — (4) Pasif Buatan","(1) Pasif Alami — (2) Aktif Alami — (3) Aktif Buatan — (4) Pasif Buatan"],"key":[3],"why":"Kunci cepat: Tubuh buat antibodi sendiri + ada Sel Memori = AKTIF (Sakit alami = Aktif Alami [2]; Vaksin = Aktif Buatan [3]). Terima antibodi jadi dari luar + tanpa Sel Memori = PASIF (Plasenta/ASI ibu = Pasif Alami [1]; Suntik serum SABU/ATS = Pasif Buatan [4]).","src":"kuis"},{"id":"7.6.1","topic":"Sistem Imun","sub":"8.7 Memori imunologis, klasifikasi 4 kekebalan & imunopatologi (alergi, autoimun, HIV)","kind":"pg","stem":"Manakah di antara pasangan penyakit AUTOIMUN dan jaringan/reseptor tubuh sendiri yang diserang oleh sistem imun berikut yang TEPAT?","options":["Lupus (SLE) — virus HIV menyerang Sel T Helper","Multiple Sclerosis — autoantibodi menyerang sel beta pankreas","Diabetes Melitus Tipe 1 — Sel T menyerang selubung mielin neuron otak","Myasthenia Gravis — autoantibodi menyerang dan memblokir reseptor Asetilkolin di membran otot rangka sehingga otot melemah/lumpuh"],"key":[3],"why":"Myasthenia Gravis menyerang reseptor Asetilkolin otot rangka; Multiple Sclerosis menyerang selubung mielin saraf pusat; Diabetes Melitus Tipe 1 menyerang sel β pankreas penghasil insulin; Penyakit Grave menyerang reseptor TSH kelenjar tiroid.","src":"kuis"},{"id":"7.6.2","topic":"Sistem Imun","sub":"8.7 Memori imunologis, klasifikasi 4 kekebalan & imunopatologi (alergi, autoimun, HIV)","kind":"pg","stem":"Virus HIV (Human Immunodeficiency Virus) penyebab AIDS tergolong ke dalam kelompok Retrovirus yang melumpuhkan sistem kekebalan tubuh manusia secara spesifik karena…","options":["HIV memproduksi histamin yang menyebabkan alergi","HIV memfagositosis seluruh sel darah merah di sumsum tulang","HIV hanya menginfeksi sel epitel kulit luar","HIV memiliki enzim Reverse Transcriptase (pengubah RNA virus menjadi DNA) dan glikoprotein amplopnya (gp120) berikatan spesifik menginfeksi serta menghancurkan Sel T Helper yang memiliki reseptor permukaan CD4+"],"key":[3],"why":"HIV menggunakan protein gp120 untuk menempel pada reseptor CD4+ milik Sel T Helper (dan makrofag), lalu menggunakan enzim Reverse Transcriptase untuk menyalin RNA-nya menjadi DNA dan menyisipkannya ke genom inang.","src":"kuis"},{"id":"8.0.0","topic":"Sistem Koordinasi","sub":"9.1 Histologi Neuron, Sel Glia & Selubung Mielin","kind":"pg","stem":"Bagian neuron yang memiliki kerapatan saluran ion Na⁺ berpintu-tegangan tertinggi dan berfungsi sebagai zona pemicu (trigger zone) pertama kali tercetusnya potensial aksi adalah…","options":["Ujung dendrit reseptor","Bonggol sinapsis (terminal akson)","Akson hilok (pangkal akson)","Badan Nissl pada perikarion"],"key":[2],"why":"Akson hilok menjumlahkan potensial berjenjang (EPSP/IPSP) dari dendrit dan soma; jika mencapai ambang −55 mV, akson hilok mencetuskan potensial aksi karena kerapatan saluran Na⁺-nya paling tinggi.","src":"kuis"},{"id":"8.0.1","topic":"Sistem Koordinasi","sub":"9.1 Histologi Neuron, Sel Glia & Selubung Mielin","kind":"pg","stem":"Perbedaan struktural dan fungsional antara sel pembentuk mielin di Sistem Saraf Pusat (SSP) dan Sistem Saraf Tepi (SST) yang tepat adalah…","options":["Sel Schwann membentuk mielin pada banyak akson sekaligus di SSP","Astrosit membentuk selubung mielin di otak sedangkan mikroglia di medula spinalis","Oligodendrosit membentuk mielin di SST dan memiliki neurilema","Oligodendrosit di SSP dapat membungkus puluhan akson sekaligus tetapi tidak memiliki neurilema, sedangkan satu sel Schwann di SST membungkus satu segmen akson dan memiliki neurilema"],"key":[3],"why":"Satu oligodendrosit membungkus hingga 50 segmen akson di SSP tanpa neurilema; satu sel Schwann membungkus 1 segmen akson di SST dan membentuk neurilema yang mendukung regenerasi.","src":"kuis"},{"id":"8.0.2","topic":"Sistem Koordinasi","sub":"9.1 Histologi Neuron, Sel Glia & Selubung Mielin","kind":"pg","stem":"Konduksi saltatorik pada akson bermielin berlangsung jauh lebih cepat dan hemat energi (ATP) dibandingkan akson tak bermielin karena…","options":["Potensial aksi dan pertukaran ion Na⁺/K⁺ hanya terjadi secara terfokus di celah Nodus Ranvier, sementara arus merambat cepat tanpa bocor di segmen bermielin","Mielin mengandung banyak pompa Na⁺/K⁺ yang mempercepat aliran ion","Neurotransmiter melompat langsung dari dendrit ke bonggol sinapsis","Selubung mielin merupakan konduktor logam yang mengalirkan elektron bebas"],"key":[0],"why":"Mielin adalah isolator lipid yang mencegah kebocoran arus di sepanjang internodus, sehingga pembukaan saluran Na⁺/K⁺ dan kerja pompa Na⁺/K⁺ hanya diperlukan di Nodus Ranvier.","src":"kuis"},{"id":"8.1.0","topic":"Sistem Koordinasi","sub":"9.2 Elektrofisiologi: Potensial Istirahat & Potensial Aksi","kind":"pg","stem":"Saat membran neuron berada pada fase repolarisasi (potensial bergerak turun dari +35 mV kembali menuju −70 mV), peristiwa molekuler yang sedang berlangsung adalah…","options":["Saluran Ca²⁺ terbuka menyebabkan fusi vesikel di akson hilok","Gerbang inaktivasi saluran Na⁺ menutup dan saluran K⁺ berpintu-tegangan terbuka sehingga K⁺ mengalir keluar sel","Saluran Na⁺ berpintu-tegangan terbuka lebar sehingga Na⁺ masuk ke dalam sel","Pompa Na⁺/K⁺ berhenti bekerja dan ion Cl⁻ dipompa keluar sel"],"key":[1],"why":"Pada puncak depolarisasi (+35 mV), saluran Na⁺ mengalami inaktivasi dan saluran K⁺ berpintu-tegangan terbuka penuh sehingga efluks K⁺ menurunkan potensial membran kembali negatif.","src":"kuis"},{"id":"8.1.1","topic":"Sistem Koordinasi","sub":"9.2 Elektrofisiologi: Potensial Istirahat & Potensial Aksi","kind":"pg","stem":"Racun tetrodotoksin (TTX) dari ikan buntal bekerja menyumbat secara spesifik saluran ion Na⁺ berpintu-tegangan pada membran akson. Dampak langsung pemberian TTX terhadap sel saraf adalah…","options":["Fase depolarisasi gagal terjadi sehingga potensial aksi tidak dapat dicetuskan meskipun diberi rangsang di atas ambang","Hiperpolarisasi permanen akibat masuknya ion Ca²⁺","Fase repolarisasi berlangsung sangat cepat sehingga neuron kejang","Potensial istirahat langsung berubah menjadi +35 mV"],"key":[0],"why":"Tanpa pembukaan saluran Na⁺ berpintu-tegangan, influks Na⁺ saat melampaui ambang −55 mV terblokir total sehingga fase depolarisasi dan potensial aksi gagal terbentuk.","src":"kuis"},{"id":"8.1.2","topic":"Sistem Koordinasi","sub":"9.2 Elektrofisiologi: Potensial Istirahat & Potensial Aksi","kind":"pg","stem":"Potensial aksi yang merambat di sepanjang akson tidak pernah berbalik arah menuju badan sel karena segmen membran yang baru saja dilewati berada dalam…","options":["Periode refraktori absolut akibat gerbang inaktivasi saluran Na⁺ yang belum kembali ke konformasi siap-buka","Kondisi kehabisan ATP total sehingga pompa Na⁺/K⁺ mati","Fase polarisasi istirahat dengan saluran K⁺ tertutup rapat","Hambatan oleh neurotransmiter GABA di sepanjang Nodus Ranvier"],"key":[0],"why":"Sesaat setelah depolarisasi, saluran Na⁺ terkunci dalam status inaktif (periode refraktori absolut) hingga membran mengalami repolarisasi kembali, sehingga arus lokal hanya dapat mengaktifkan segmen di depannya.","src":"kuis"},{"id":"8.2.0","topic":"Sistem Koordinasi","sub":"9.3 Transmisi Sinapsis, Neurotransmiter & Neurotoksin","kind":"pg","stem":"Ketika potensial aksi tiba di ujung bonggol sinapsis (membran prasinapsis), ion yang wajib masuk dari cairan ekstraseluler untuk memicu fusi vesikel dan eksositosis neurotransmiter adalah…","options":["K⁺","Na⁺","Cl⁻","Ca²⁺"],"key":[3],"why":"Depolarisasi terminal akson membuka saluran Ca²⁺ berpintu-tegangan; influks Ca²⁺ mengaktifkan sinaptotagmin dan kompleks SNARE untuk meleburkan vesikel sinapsis.","src":"kuis"},{"id":"8.2.1","topic":"Sistem Koordinasi","sub":"9.3 Transmisi Sinapsis, Neurotransmiter & Neurotoksin","kind":"pg","stem":"Neurotransmiter GABA (Gamma-Aminobutyric Acid) di otak bekerja membuka saluran ion Cl⁻ pada membran pascasinapsis. Efek elektrofisiologis yang ditimbulkan adalah…","options":["Hiperpolarisasi menjauhi ambang (IPSP) karena masuknya ion Cl⁻ bermuatan negatif menghambat pencetusan potensial aksi","Pemecahan enzim asetilkolinesterase di celah sinapsis","Repolarisasi prasinapsis yang mempercepat pelepasan asetilkolin","Depolarisasi menuju −55 mV (EPSP) sehingga neuron pascasinapsis mudah menembakkan impuls"],"key":[0],"why":"Influks ion Cl⁻ membuat bagian dalam membran pascasinapsis semakin negatif (mis. −78 mV), menghasilkan IPSP yang mengerem aktivitas saraf.","src":"kuis"},{"id":"8.2.2","topic":"Sistem Koordinasi","sub":"9.3 Transmisi Sinapsis, Neurotransmiter & Neurotoksin","kind":"pg","stem":"Perbandingan mekanisme kerja toksin Botulinum (penyebab botulisme) dan toksin Tetanus yang tepat adalah…","options":["Botulinum menghambat pelepasan ACh di sambungan neuromuskular (menyebabkan lumpuh layuh), sedangkan Tetanus menghambat pelepasan neurotransmiter inhibitorik GABA/glisin di interneuron (menyebabkan kejang kaku)","Botulinum menyerang selubung mielin SSP, sedangkan Tetanus menyerang sel Schwann SST","Botulinum memicu eksositosis dopamin berlebih, sedangkan Tetanus memblokir saluran Na⁺","Keduanya menghambat enzim asetilkolinesterase sehingga menimbulkan kejang kaku"],"key":[0],"why":"Botulinum merusak protein SNARE di ujung motorik sehingga ACh tidak keluar (paralisis flaksid); Tetanus merusak pelepasan GABA/glisin pada interneuron Renshaw sehingga neuron motorik menembak tanpa rem (paralisis spastik).","src":"kuis"},{"id":"8.3.0","topic":"Sistem Koordinasi","sub":"9.4 Arsitektur Sistem Saraf Pusat (SSP) & Gerak Refleks","kind":"pg","stem":"Urutan penjalaran impuls pada gerak refleks menarik tangan saat tertusuk duri yang tepat adalah…","options":["Reseptor → Neuron sensorik → Talamus → Korteks serebri lobus parietalis → Neuron motorik → Efektor","Reseptor → Neuron motorik → Akar ventral medula spinalis → Interneuron → Neuron sensorik → Efektor","Reseptor → Neuron sensorik (akar dorsal) → Interneuron di substansia grisea medula spinalis → Neuron motorik (akar ventral) → Efektor","Reseptor → Serebelum → Medula oblongata → Neuron motorik → Efektor"],"key":[2],"why":"Refleks spinal diproses langsung di substansia grisea medula spinalis (masuk lewat akar dorsal, keluar lewat akar ventral) tanpa menunggu pemrosesan di korteks serebri.","src":"kuis"},{"id":"8.3.1","topic":"Sistem Koordinasi","sub":"9.4 Arsitektur Sistem Saraf Pusat (SSP) & Gerak Refleks","kind":"pg","stem":"Bagian sistem saraf pusat yang berfungsi sebagai pusat pengendali otonom vital bagi ritme dasar pernapasan, frekuensi denyut jantung, serta refleks batuk, bersin, dan muntah adalah…","options":["Lobus oksipitalis serebrum","Medula oblongata (sumsum lanjutan)","Serebelum (otak kecil)","Korpus kalosum"],"key":[1],"why":"Medula oblongata di batang otak mengandung pusat kardiovaskular dan pusat ritmisitas meduler pernapasan; kerusakan bagian ini menyebabkan henti napas fatal.","src":"kuis"},{"id":"8.3.2","topic":"Sistem Koordinasi","sub":"9.4 Arsitektur Sistem Saraf Pusat (SSP) & Gerak Refleks","kind":"pg","stem":"Pasien stroke mengalami kondisi memahami seluruh perkataan orang lain dengan baik, tetapi sangat kesulitan merangkai kata untuk berbicara (afasia motorik). Area korteks serebrum yang mengalami kerusakan adalah…","options":["Area Broca di lobus frontalis","Korteks visual primer di lobus oksipitalis","Korteks somatosensorik di lobus parietalis","Area Wernicke di lobus temporalis"],"key":[0],"why":"Area Broca (lobus frontalis) mengatur koordinasi motorik otot-otot bicara, sedangkan Area Wernicke (lobus temporalis) mengatur pemahaman bahasa.","src":"kuis"},{"id":"8.4.0","topic":"Sistem Koordinasi","sub":"9.5 Sistem Saraf Tepi: Otonom Simpatis vs Parasimpatis","kind":"pg","stem":"Pasangan respons fisiologis di bawah ini yang seluruhnya merupakan akibat aktivasi Sistem Saraf Parasimpatis (Rest-and-Digest) adalah…","options":["Pupil melebar (midriasis), denyut jantung meningkat, bronkus melebar","Pupil menyempit (miosis), denyut jantung melambat, gerak peristaltik dan sekresi enzim pencernaan meningkat","Sekresi adrenalin meningkat, glikogenolisis di hati dipacu, sfingter urin menutup","Kelenjar keringat aktif, pembuluh darah kulit menyempit, tekanan darah naik"],"key":[1],"why":"Saraf parasimpatis (via asetilkolin dan Nervus Vagus) menyempitkan pupil (miosis), menurunkan frekuensi jantung, dan memacu aktivitas pencernaan.","src":"kuis"},{"id":"8.4.1","topic":"Sistem Koordinasi","sub":"9.5 Sistem Saraf Tepi: Otonom Simpatis vs Parasimpatis","kind":"pg","stem":"Perbedaan anatomi dan neurokimia antara jalur eferen saraf simpatis dan parasimpatis yang benar adalah…","options":["Keduanya hanya terdiri atas satu neuron motorik tunggal dari sumsum tulang belakang langsung ke otot rangka","Simpatis memiliki neuron praganglion panjang dan melepaskan asetilkolin di organ target","Simpatis memiliki neuron praganglion pendek dan pascaganglion panjang yang melepaskan norepinefrin di mayoritas organ target, sedangkan parasimpatis melepaskan asetilkolin baik di ganglion maupun di organ target","Parasimpatis berpangkal di medula spinalis torakolumbal dan melepaskan norepinefrin di organ target"],"key":[2],"why":"Semua neuron praganglion otonom (simpatis & parasimpatis) melepaskan ACh; namun neuron pascaganglion simpatis melepaskan norepinefrin, sedangkan pascaganglion parasimpatis melepaskan ACh.","src":"kuis"},{"id":"8.4.2","topic":"Sistem Koordinasi","sub":"9.5 Sistem Saraf Tepi: Otonom Simpatis vs Parasimpatis","kind":"pg","stem":"Obat inhaler Salbutamol (agonis reseptor adrenergik β₂) diberikan kepada pasien serangan asma akut karena obat tersebut meniru kerja saraf…","options":["Parasimpatis untuk mempercepat denyut jantung","Parasimpatis untuk memicu bronkokonstriksi dan pengeluaran lendir","Simpatis untuk merelaksasi otot polos bronkiolus sehingga terjadi bronkodilatasi","Somatik untuk menghentikan kontraksi diafragma"],"key":[2],"why":"Stimulasi simpatis (reseptor β₂) merelaksasi otot polos bronkiolus (bronkodilatasi), melawan penyempitan saluran napas saat serangan asma.","src":"kuis"},{"id":"8.5.0","topic":"Sistem Koordinasi","sub":"9.6 Fisiologi Indera Penglihatan: Akomodasi, Fototransduksi & Kelainan Refraksi","kind":"pg","stem":"Urutan kondisi mekanis yang terjadi pada mata normal saat melakukan akomodasi maksimum untuk membaca teks berukuran kecil pada jarak dekat adalah…","options":["Otot siliaris relaksasi → ligamen suspensorium menegang → lensa mata mencembung","Otot siliaris berkontraksi → ligamen suspensorium mengendur → lensa mata mencembung","Otot iris berkontraksi → kornea mencembung → bintik buta melebar","Otot siliaris berkontraksi → ligamen suspensorium menegang → lensa mata memipih"],"key":[1],"why":"Kontraksi otot siliaris yang melingkar memperkecil diameter cincin siliaris sehingga ketegangan ligamen suspensorium berkurang (mengendur) dan lensa yang elastis menggembung/mencembung.","src":"kuis"},{"id":"8.5.1","topic":"Sistem Koordinasi","sub":"9.6 Fisiologi Indera Penglihatan: Akomodasi, Fototransduksi & Kelainan Refraksi","kind":"pg","stem":"Peristiwa molekuler fototransduksi yang terjadi pada sel batang (basilus) retina ketika berpindah dari ruang gelap gulita ke tempat terang adalah…","options":["Cahaya mengubah 11-cis-retinal menjadi all-trans-retinal (pemutihan rodopsin) → aktivasi transdusin dan enzim PDE → kadar cGMP turun → saluran Na⁺ menutup → sel batang mengalami hiperpolarisasi","Sel batang langsung berhenti menyerap vitamin A dan beralih menggunakan iodopsin","Rodopsin terbentuk dari opsin dan retinal → saluran Na⁺ terbuka → sel batang mengalami depolarisasi","Saluran K⁺ terbuka sehingga glutamat dilepaskan secara masif ke celah sinapsis"],"key":[0],"why":"Dalam gelap, cGMP tinggi menjaga saluran Na⁺ terbuka (depolarisasi). Cahaya mengaktifkan PDE yang menguraikan cGMP sehingga saluran Na⁺ tertutup dan fotoreseptor justru mengalami hiperpolarisasi.","src":"kuis"},{"id":"8.5.2","topic":"Sistem Koordinasi","sub":"9.6 Fisiologi Indera Penglihatan: Akomodasi, Fototransduksi & Kelainan Refraksi","kind":"pg","stem":"Seorang lansia tidak dapat membaca koran pada jarak baca normal 25 cm karena titik dekat matanya (punctum proximum) bergeser menjadi 50 cm, sementara penglihatan jauhnya normal. Jenis dan ukuran lensa kacamata baca yang tepat adalah…","options":["Lensa cembung +4 Dioptri","Lensa cekung −2 Dioptri","Lensa silindris +0,5 Dioptri","Lensa cembung +2 Dioptri"],"key":[3],"why":"Kekuatan lensa untuk rabun dekat (hipermetropi/presbiopi baca): P = 100/sn − 100/PP = 100/25 − 100/50 = 4 − 2 = +2 Dioptri (lensa cembung/positif).","src":"kuis"},{"id":"8.6.0","topic":"Sistem Koordinasi","sub":"9.7 Fisiologi Indera Pendengaran, Ekuilibrium, Pengecap, Pembau & Kulit","kind":"pg","stem":"Urutan rambatan getaran mekanis gelombang bunyi sejak menggetarkan membran timpani hingga mengaktifkan reseptor pendengaran adalah…","options":["Membran timpani → Stapes → Inkus → Maleus → Tingkap bundar → Kanalis semisirkularis","Membran timpani → Maleus → Inkus → Stapes → Skala timpani → Organ Corti","Membran timpani → Saluran Eustachius → Koklea → Makula utrikulus → Saraf optikus","Membran timpani → Maleus → Inkus → Stapes → Tingkap oval → Perilimfe skala vestibuli → Endolimfe skala media (Organ Corti)"],"key":[3],"why":"Tulang pendengaran berurutan Martil (Maleus) → Landasan (Inkus) → Sanggurdi (Stapes) mengetuk tingkap oval, menggetarkan perilimfe skala vestibuli lalu endolimfe skala media tempat Organ Corti berada.","src":"kuis"},{"id":"8.6.1","topic":"Sistem Koordinasi","sub":"9.7 Fisiologi Indera Pendengaran, Ekuilibrium, Pengecap, Pembau & Kulit","kind":"pg","stem":"Ketika seorang penari balet berputar cepat lalu berhenti mendadak, ia masih merasa seolah-olah tubuhnya sedang berputar (vertigo fisiologis). Reseptor keseimbangan yang sedang terstimulasi oleh aliran cairan endolimfe akibat percepatan rotasi tersebut adalah…","options":["Membran timpani dan tulang sanggurdi","Korpuskula Pacini di telapak kaki","Krista ampularis (kupula) di dalam ampula kanalis semisirkularis","Organ Corti di dalam skala media koklea"],"key":[2],"why":"Kanalis semisirkularis (3 saluran setengah lingkaran yang saling tegak lurus) memiliki krista ampularis dengan tudung gelatin kupula yang mendeteksi percepatan sudut/rotasi kepala.","src":"kuis"},{"id":"8.6.2","topic":"Sistem Koordinasi","sub":"9.7 Fisiologi Indera Pendengaran, Ekuilibrium, Pengecap, Pembau & Kulit","kind":"pg","stem":"Pernyataan yang tepat mengenai reseptor sensorik pada lidah, hidung, dan kulit manusia adalah…","options":["Korpuskula Pacini di lapisan dermis dalam peka terhadap tekanan kuat dan getaran, sedangkan korpuskula Meissner di dermis papiler peka terhadap sentuhan halus","Papila filiformis merupakan papila yang memiliki kuncup kecap (taste buds) paling banyak untuk rasa manis","Ujung lidah manusia hanya memiliki reseptor rasa manis dan sama sekali tidak dapat mengecap rasa asin atau asam","Impuls penciuman dari sel olfaktori wajib melewati talamus terlebih dahulu sebelum mencapai bulbus olfaktorius"],"key":[0],"why":"Korpuskula Pacini mendeteksi tekanan dalam/getaran dan Meissner mendeteksi sentuhan ringan. Jalur olfaktori adalah satu-satunya indera yang TIDAK lewat talamus; papila filiformis tidak punya taste buds; dan semua area lidah ber-taste buds dapat mengecap semua rasa dasar.","src":"kuis"},{"id":"8.7.0","topic":"Sistem Koordinasi","sub":"9.8 Sistem Endokrin: Poros Hipotalamus-Hipofisis & Regulasi Kalsium","kind":"pg","stem":"Pasangan hormon di bawah ini yang keduanya TIDAK diproduksi oleh kelenjar hipofisis, melainkan disintesis oleh neuron hipotalamus lalu disimpan dan dilepaskan oleh hipofisis posterior (neurohipofisis) adalah…","options":["ADH (Vasopresin) dan Oksitosin","FSH dan LH","TSH dan ACTH","Prolaktin dan Somatotropin (GH)"],"key":[0],"why":"Neurohipofisis hanya merupakan tempat penyimpanan ujung akson neuron hipotalamus yang melepaskan ADH dan Oksitosin; keenam hormon lainnya diproduksi langsung oleh sel endokrin adenohipofisis.","src":"kuis"},{"id":"8.7.1","topic":"Sistem Koordinasi","sub":"9.8 Sistem Endokrin: Poros Hipotalamus-Hipofisis & Regulasi Kalsium","kind":"pg","stem":"Ketika kadar ion kalsium (Ca²⁺) di dalam plasma darah turun di bawah normal (hipokalsemia), respons homeostasis endokrin yang terjadi adalah…","options":["Kelenjar tiroid menyekresikan kalsitonin untuk memindahkan Ca²⁺ dari darah ke matriks tulang","Hipofisis anterior menyekresikan somatotropin untuk menutup lempeng epifisis","Korteks adrenal menyekresikan aldosteron untuk membuang Ca²⁺ lewat urin","Kelenjar paratiroid menyekresikan Parathormon (PTH) yang merangsang osteoklas membongkar Ca²⁺ tulang, meningkatkan reabsorpsi Ca²⁺ di tubulus ginjal, dan mengaktifkan vitamin D untuk absorpsi Ca²⁺ di usus"],"key":[3],"why":"PTH dari kelenjar paratiroid bekerja menaikkan kadar Ca²⁺ darah melalui 3 organ (tulang, ginjal, dan usus via kalsitriol/Vit D aktif), antagonis terhadap kalsitonin dari tiroid.","src":"kuis"},{"id":"8.7.2","topic":"Sistem Koordinasi","sub":"9.8 Sistem Endokrin: Poros Hipotalamus-Hipofisis & Regulasi Kalsium","kind":"pg","stem":"Perbedaan mendasar mekanisme kerja seluler antara hormon steroid (mis. kortisol, testosteron) dan hormon peptida (mis. insulin, glukagon) adalah…","options":["Hormon peptida menembus masuk ke dalam nukleus untuk mengubah urutan basa DNA secara permanen","Keduanya tidak membutuhkan reseptor spesifik pada sel target","Hormon steroid larut air sehingga wajib menggunakan cAMP sebagai kurir kedua di membran sel","Hormon steroid bersifat lipofilik sehingga menembus membran sel secara langsung dan berikatan dengan reseptor intraseluler untuk mengatur transkripsi gen di DNA, sedangkan hormon peptida berikatan dengan reseptor membran dan mengaktifkan second messenger"],"key":[3],"why":"Hormon steroid dan tiroid menembus dwilapis lipid dan kompleks reseptornya menjadi faktor transkripsi DNA; hormon peptida dan katekolamin bersifat hidrofilik sehingga bekerja lewat reseptor membran dan kurir kedua (cAMP/IP₃).","src":"kuis"},{"id":"8.8.0","topic":"Sistem Koordinasi","sub":"9.9 Kelenjar Pankreas, Adrenal & Umpan Balik Homeostasis Glukosa","kind":"pg","stem":"Setelah seseorang mengonsumsi makanan tinggi karbohidrat, lonjakan glukosa darah akan dideteksi oleh Pulau Langerhans pankreas yang merespons dengan…","options":["Sel beta menyekresikan insulin yang memicu penyisipan transporter GLUT-4 ke membran sel otot/adiposa dan memacu glikogenesis di hati","Sel alfa menyekresikan glukagon untuk memacu pemecahan glikogen hati","Korteks adrenal menyekresikan kortisol untuk memacu glukoneogenesis","Medula adrenal menyekresikan adrenalin untuk membuang glukosa lewat urin"],"key":[0],"why":"Sel β pankreas melepaskan insulin saat hiperglikemia untuk memasukkan glukosa ke sel otot/lemak (via GLUT-4) dan mengubah glukosa menjadi glikogen (glikogenesis) di hati dan otot.","src":"kuis"},{"id":"8.8.1","topic":"Sistem Koordinasi","sub":"9.9 Kelenjar Pankreas, Adrenal & Umpan Balik Homeostasis Glukosa","kind":"pg","stem":"Dalam menghadapi stres kronis berkepanjangan (mis. kelaparan atau tekanan psikologis berbulan-bulan), jalur neuroendokrin yang diaktifkan untuk mempertahankan ketersediaan glukosa darah melalui glukoneogenesis protein dan lemak adalah…","options":["Hipofisis posterior → Medula Adrenal → Aldosteron","Hipotalamus (CRH) → Adenohipofisis (ACTH) → Korteks Adrenal → Kortisol","Kelenjar Tiroid → Kalsitonin → Osteoblas","Saraf parasimpatis → Pulau Langerhans → Insulin"],"key":[1],"why":"Poros HPA (Hipotalamus-Pituitari-Adrenal) melalui CRH → ACTH merangsang zona fasikulata korteks adrenal melepaskan glukokortikoid (kortisol) untuk glukoneogenesis jangka panjang.","src":"kuis"},{"id":"8.8.2","topic":"Sistem Koordinasi","sub":"9.9 Kelenjar Pankreas, Adrenal & Umpan Balik Homeostasis Glukosa","kind":"pg","stem":"Perbedaan mendasar antara Diabetes Melitus (DM) Tipe 1 dan DM Tipe 2 adalah…","options":["DM Tipe 1 hanya menyerang lansia obesitas dan dapat sembuh tanpa insulin, sedangkan DM Tipe 2 menyerang bayi baru lahir","Pada DM Tipe 1 kadar glukosa darah terlalu rendah (hipoglikemia), sedangkan pada DM Tipe 2 terlalu tinggi","DM Tipe 1 disebabkan oleh kekurangan hormon ADH, sedangkan DM Tipe 2 disebabkan oleh kekurangan aldosteron","DM Tipe 1 terjadi akibat destruksi autoimun sel β pankreas sehingga produksi insulin gagal sejak usia muda, sedangkan DM Tipe 2 terjadi akibat penurunan kepekaan (resistensi) reseptor insulin pada sel target"],"key":[3],"why":"DM Tipe 1 (IDDM) adalah kelainan autoimun yang menghancurkan sel β penghasil insulin; DM Tipe 2 (NIDDM) diawali oleh resistensi reseptor insulin pada jaringan tepi.","src":"kuis"},{"id":"9.0.0","topic":"Sistem Reproduksi","sub":"10.1 Anatomi & Histologi Sistem Reproduksi Pria","kind":"pg","stem":"Pasangan yang tepat antara jenis sel di dalam testis, hormon hipofisis yang merangsangnya, dan produk yang dihasilkannya adalah…","options":["Sel Leydig dirangsang oleh LH (ICSH) untuk menyekresikan testosteron, sedangkan Sel Sertoli dirangsang oleh FSH untuk menyekresikan ABP dan inhibin serta membentuk sawar darah-testis","Sel Sertoli dirangsang oleh LH untuk menyekresikan hormon testosteron ke pembuluh darah","Sel spermatogonium dirangsang oleh oksitosin untuk menghasilkan cairan fruktosa","Sel Leydig dirangsang oleh FSH untuk menghasilkan hormon inhibin dan memberi makan sperma"],"key":[0],"why":"LH merangsang Sel Leydig di ruang interstisial menghasilkan testosteron; FSH merangsang Sel Sertoli di dalam tubulus seminiferus menghasilkan ABP, inhibin, dan menutrisi spermatid.","src":"kuis"},{"id":"9.0.1","topic":"Sistem Reproduksi","sub":"10.1 Anatomi & Histologi Sistem Reproduksi Pria","kind":"pg","stem":"Urutan saluran reproduksi pria yang dilalui oleh spermatozoa sejak dibentuk hingga keluar dari tubuh saat ejakulasi adalah…","options":["Tubulus seminiferus → Vas deferens → Epididimis → Uretra → Duktus ejakulatorius","Tubulus seminiferus → Epididimis → Vas deferens → Duktus ejakulatorius → Uretra","Tubulus seminiferus → Rete testis → Uretra → Vas deferens → Epididimis","Epididimis → Tubulus seminiferus → Vesikula seminalis → Prostat → Uretra"],"key":[1],"why":"Sesuai akronim SEVEN UP: Tubulus Seminiferus → Epididimis (tempat pematangan motilitas) → Vas deferens → Duktus Ejakulatorius → Uretra.","src":"kuis"},{"id":"9.0.2","topic":"Sistem Reproduksi","sub":"10.1 Anatomi & Histologi Sistem Reproduksi Pria","kind":"pg","stem":"Kelenjar aksesori reproduksi pria yang menyumbangkan sekitar 60–70% volume cairan semen dan kaya akan gula fruktosa sebagai sumber energi utama pembentukan ATP bagi gerak ekor spermatozoa adalah…","options":["Kelenjar bulbouretral (Cowper)","Vesikula seminalis","Epididimis","Kelenjar prostat"],"key":[1],"why":"Vesikula seminalis menghasilkan cairan kental kekuningan bersifat basa yang kaya fruktosa (bahan bakar mitokondria sperma) dan prostaglandin.","src":"kuis"},{"id":"9.1.0","topic":"Sistem Reproduksi","sub":"10.2 Anatomi & Histologi Sistem Reproduksi Wanita","kind":"pg","stem":"Tempat terjadinya proses fertilisasi (peleburan inti sperma dan oosit sekunder) serta tempat terjadinya implantasi (nidasi) blastokista secara berurutan pada manusia yang normal adalah…","options":["Ampula Tuba Fallopi (oviduk) dan Endometrium Uterus (rahim)","Infundibulum dan Miometrium Uterus","Endometrium Uterus dan Serviks","Ovarium dan Tuba Fallopi"],"key":[0],"why":"Fertilisasi terjadi di sepertiga atas/ampula tuba Fallopi (oviduk), kemudian zigot membelah sambil berjalan ke rahim dan berimplantasi sebagai blastokista di dinding endometrium uterus.","src":"kuis"},{"id":"9.1.1","topic":"Sistem Reproduksi","sub":"10.2 Anatomi & Histologi Sistem Reproduksi Wanita","kind":"pg","stem":"Lapisan dinding rahim (uterus) yang kaya akan pembuluh darah spiralis serta kelenjar, dan bagian fungsionalnya mengalami penebalan serta peluruhan secara periodik saat menstruasi adalah…","options":["Mesovarium","Perimetrium","Endometrium","Miometrium"],"key":[2],"why":"Endometrium adalah lapisan mukosa terdalam rahim (stratum fungsionalisnya luruh saat haid, dibangun kembali oleh stratum basalis); sedangkan miometrium adalah lapisan otot polos untuk kontraksi persalinan.","src":"kuis"},{"id":"9.1.2","topic":"Sistem Reproduksi","sub":"10.2 Anatomi & Histologi Sistem Reproduksi Wanita","kind":"pg","stem":"Struktur berbentuk jumbai jari-jari pada ujung corong tuba Fallopi (infundibulum) yang bergerak aktif menyapu dan menangkap oosit sekunder yang dilepaskan dari ovarium saat ovulasi disebut…","options":["Folikel de Graaf","Korpus luteum","Vili korialis","Fimbriae"],"key":[3],"why":"Fimbriae menjulur di dekat permukaan ovarium dan bersilia untuk menghasilkan arus cairan peritoneal yang menarik oosit sekunder masuk ke dalam ostium tuba Fallopi.","src":"kuis"},{"id":"9.2.0","topic":"Sistem Reproduksi","sub":"10.3 Gametogenesis: Spermatogenesis vs Oogenesis","kind":"pg","stem":"Sel kelamin wanita yang dilepaskan dari folikel de Graaf menuju tuba Fallopi pada peristiwa ovulasi berada pada tahapan…","options":["Oogonium diploid (2n) yang siap membelah mitosis","Oosit primer diploid (2n) yang terhenti pada Profase I","Oosit sekunder haploid (n) yang terhenti pada Metafase II","Ovum matang haploid (n) yang telah menyelesaikan Meiosis II"],"key":[2],"why":"Saat ovulasi, sel telur berada pada tahap Oosit Sekunder (n) yang mengalami henti meiosis kedua pada fase Metafase II; Meiosis II baru tuntas menjadi ovum jika ditembus oleh sperma.","src":"kuis"},{"id":"9.2.1","topic":"Sistem Reproduksi","sub":"10.3 Gametogenesis: Spermatogenesis vs Oogenesis","kind":"pg","stem":"Tujuan biologis utama dari pembagian sitoplasma yang sangat tidak merata (sitokinesis asimetris) pada Meiosis I dan Meiosis II oogenesis sehingga menghasilkan badan kutub (polosit) berukuran sangat kecil adalah…","options":["Memastikan satu sel telur tunggal menerima hampir seluruh cadangan nutrisi (kuning telur/sitoplasma), mitokondria, dan mRNA maternal untuk menopang pembelahan awal embrio","Mempercepat gerakan berenang sel telur di sepanjang tuba Fallopi","Membuang kelebihan kromosom seks X agar tidak terjadi gagal berpisah","Menghasilkan empat sel telur kembar identik dalam satu kali ovulasi"],"key":[0],"why":"Berbeda dengan sperma yang membuang sitoplasmanya agar ringan dan lincah, embrio awal bergantung penuh pada cadangan sitoplasma, organel mitokondria, dan nutrisi dari satu sel telur besar sebelum berimplantasi di uterus.","src":"kuis"},{"id":"9.2.2","topic":"Sistem Reproduksi","sub":"10.3 Gametogenesis: Spermatogenesis vs Oogenesis","kind":"pg","stem":"Pada struktur spermatozoa matang, bagian yang berasal dari modifikasi aparatus Golgi dan mengandung enzim hialuronidase serta akrosin untuk menembus selubung oosit sekunder adalah…","options":["Tudung akrosom di ujung kepala sperma","Selubung ekor mikrotubulus 9+2","Sentriol proksimal di pangkal flagelum","Bagian leher (midpiece) yang kaya mitokondria spiral"],"key":[0],"why":"Selama spermiogenesis, vesikel-vesikel badan Golgi menyatu di bagian depan inti haploid membentuk tudung akrosom yang berisi enzim pelisis korona radiata dan zona pelusida.","src":"kuis"},{"id":"9.3.0","topic":"Sistem Reproduksi","sub":"10.4 Siklus Menstruasi: Interaksi 4 Hormon, Siklus Ovarium & Siklus Uterus","kind":"pg","stem":"Peristiwa hormonal yang secara langsung memicu pecahnya folikel de Graaf pada peristiwa ovulasi di pertengahan siklus menstruasi adalah…","options":["Lonjakan tajam hormon LH (LH surge) dari hipofisis anterior akibat umpan balik positif dari puncak kadar estrogen","Peningkatan hormon oksitosin dan prolaktin dari hipofisis posterior","Penurunan drastis hormon progesteron dan estrogen","Penekanan hormon FSH oleh hormon hCG dari endometrium"],"key":[0],"why":"Ketika folikel de Graaf matang menghasilkan estrogen dalam konsentrasi sangat tinggi selama >48 jam, umpan balik terhadap hipotalamus-hipofisis berubah menjadi positif sehingga memicu lonjakan besar LH (LH surge) yang menyebabkan ovulasi.","src":"kuis"},{"id":"9.3.1","topic":"Sistem Reproduksi","sub":"10.4 Siklus Menstruasi: Interaksi 4 Hormon, Siklus Ovarium & Siklus Uterus","kind":"pg","stem":"Selama fase pasca-ovulasi (fase luteal, hari ke-15 hingga ke-26), tidak ada folikel ovarium baru yang mengalami pematangan maupun ovulasi ganda karena…","options":["Kadar hormon FSH dan LH berada pada titik tertinggi sepanjang fase luteal","Tingginya kadar progesteron dan estrogen yang disekresikan oleh korpus luteum memberikan umpan balik negatif yang kuat menekan sekresi GnRH, FSH, dan LH","Oosit primer di ovarium kehabisan reseptor terhadap hormon progesteron","Dinding endometrium menghasilkan enzim yang menghancurkan folikel primer"],"key":[1],"why":"Korpus luteum menyekresikan progesteron (dan estrogen) tingkat tinggi yang mengerem hipotalamus dan adenohipofisis (FSH & LH rendah), sehingga rekrutmen folikel baru tertahan hingga korpus luteum luruh.","src":"kuis"},{"id":"9.3.2","topic":"Sistem Reproduksi","sub":"10.4 Siklus Menstruasi: Interaksi 4 Hormon, Siklus Ovarium & Siklus Uterus","kind":"pg","stem":"Penyebab langsung terjadinya peluruhan dinding stratum fungsionalis endometrium (menstruasi) apabila sel telur tidak dibuahi adalah…","options":["Degenerasi korpus luteum menjadi korpus albikans yang menyebabkan kadar progesteron dan estrogen turun drastis","Peningkatan kadar hormon hCG di dalam darah ibu","Lonjakan hormon FSH yang merusak pembuluh darah rahim","Kontraksi otot lurik vagina yang menarik dinding endometrium"],"key":[0],"why":"Hilangnya dukungan progesteron akibat menyusutnya korpus luteum memicu penyempitan (vasospasme) arteri spiralis endometrium sehingga jaringan fungsionalis mengalami iskemia dan luruh.","src":"kuis"},{"id":"9.4.0","topic":"Sistem Reproduksi","sub":"10.5 Fertilisasi, Perkembangan Embrio Awal, Implantasi & Plasenta","kind":"pg","stem":"Ketika sebuah spermatozoa berhasil menyatu dengan membran plasma oosit sekunder, oosit segera melakukan reaksi kortikal (eksositosis granula kortikal yang mengeraskan zona pelusida). Tujuan utama mekanisme ini adalah…","options":["Memicu pelepasan hormon prolaktin dari hipofisis ibu","Menarik lebih banyak sperma lain agar masuk membantu pembelahan zigot","Mencegah polispermi (masuknya lebih dari satu sperma) agar zigot yang terbentuk tetap terjaga diploid (2n) dan tidak menjadi triploid (3n) yang letal","Mengubah zona pelusida menjadi tali pusat dan cairan amnion"],"key":[2],"why":"Jika dua sperma (masing-masing n) membuahi satu oosit (n), zigot menjadi triploid (3n = 69 kromosom) yang gagal berkembang; reaksi kortikal mengubah zona pelusida menjadi membran fertilisasi yang tak tertembus sperma lain.","src":"kuis"},{"id":"9.4.1","topic":"Sistem Reproduksi","sub":"10.5 Fertilisasi, Perkembangan Embrio Awal, Implantasi & Plasenta","kind":"pg","stem":"Tahapan perkembangan embrio awal yang berbentuk bola berongga berisi cairan (blastosol), terdiri atas massa sel dalam (embrioblas) serta lapisan trofoblas luar, dan merupakan fase yang menempel (berimplantasi) ke dinding endometrium uterus adalah…","options":["Gastrula","Zigot","Blastokista (Blastula)","Morula"],"key":[2],"why":"Zigot membelah menjadi bola padat Morula, lalu membentuk rongga menjadi Blastokista pada hari ke-5; sel trofoblas blastokista inilah yang menginvasi endometrium saat implantasi.","src":"kuis"},{"id":"9.4.2","topic":"Sistem Reproduksi","sub":"10.5 Fertilisasi, Perkembangan Embrio Awal, Implantasi & Plasenta","kind":"pg","stem":"Pernyataan yang benar mengenai sirkulasi darah dan selaput ekstraembrionik pada janin manusia di dalam kandungan adalah…","options":["Alantois berfungsi menyekresikan hormon progesteron selama bulan pertama kehamilan","Vena umbilikalis di dalam tali pusat membawa darah yang kaya oksigen (O₂) dan nutrisi dari plasenta menuju tubuh janin, sedangkan dua arteri umbilikalis membawa darah kaya CO₂ dan urea dari janin ke plasenta","Cairan amnion berfungsi sebagai tempat pembentukan sel darah merah pertama embrio","Darah ibu memompa langsung masuk ke jantung janin melalui pembuluh darah plasenta"],"key":[1],"why":"Seperti sirkulasi pulmonal, penamaan pembuluh tali pusat didasarkan pada jantung janin: Arteri umbilikalis keluar dari janin menuju plasenta (miskin O₂, kaya CO₂/urea), sedangkan Vena umbilikalis masuk dari plasenta menuju janin (kaya O₂ dan nutrisi). Darah ibu dan janin tidak pernah bercampur langsung.","src":"kuis"},{"id":"9.5.0","topic":"Sistem Reproduksi","sub":"10.6 Kehamilan, Persalinan (Partus) & Fisiologi Laktasi (ASI)","kind":"pg","stem":"Pasangan organ tubuh manusia di bawah ini yang ketiganya berkembang dari lapisan germinal yang sama pada saat organogenesis gastrula adalah…","options":["Sistem saraf pusat, epidermis kulit, dan retina mata (berasal dari Ektoderm)","Otot jantung, hati, dan kelenjar tiroid (berasal dari Mesoderm)","Ginjal, rangka tulang, dan sumsum tulang belakang (berasal dari Endoderm)","Otak, tulang rangka, dan paru-paru (berasal dari Ektoderm)"],"key":[0],"why":"Ektoderm membentuk jaringan saraf (SSP & SST), indera (retina/lensa/telinga dalam), dan epidermis kulit. Mesoderm membentuk tulang, otot, darah, ginjal, gonad. Endoderm membentuk epitel pencernaan, pernapasan, hati, pankreas, tiroid.","src":"kuis"},{"id":"9.5.1","topic":"Sistem Reproduksi","sub":"10.6 Kehamilan, Persalinan (Partus) & Fisiologi Laktasi (ASI)","kind":"pg","stem":"Proses persalinan (partus) merupakan salah satu contoh klasik mekanisme umpan balik positif (positive feedback) di dalam tubuh manusia karena…","options":["Tekanan kepala bayi pada serviks memicu pelepasan oksitosin dari neurohipofisis yang memperkuat kontraksi miometrium, sehingga kepala bayi menekan serviks lebih kuat lagi dan memicu pelepasan oksitosin yang makin besar","Hormon prolaktin menghentikan pelepasan prostaglandin begitu serviks membuka","Kadar progesteron yang tinggi terus menekan kontraksi otot rahim hingga bayi lahir","Penurunan hormon estrogen memicu penutupan leher rahim"],"key":[0],"why":"Siklus Ferguson pada persalinan bersifat menguatkan diri sendiri (umpan balik positif): regangan serviks → impuls saraf ke hipotalamus → rilis oksitosin neurohipofisis → kontraksi miometrium makin kuat → regangan serviks makin besar, dan baru berhenti setelah bayi lahir.","src":"kuis"},{"id":"9.5.2","topic":"Sistem Reproduksi","sub":"10.6 Kehamilan, Persalinan (Partus) & Fisiologi Laktasi (ASI)","kind":"pg","stem":"Seorang ibu menyusui mengalami kondisi payudaranya terasa penuh dan bengkak oleh air susu (produksi ASI melimpah), namun ASI sangat sulit memancar keluar ketika bayi mengisap karena ibu mengalami stres berat dan kelelahan. Hormon yang pelepasan refleksnya sedang terganggu oleh kondisi stres ibu tersebut adalah…","options":["Progesteron dari korpus luteum","Kalsitonin dari kelenjar tiroid","Prolaktin dari hipofisis anterior","Oksitosin dari hipofisis posterior"],"key":[3],"why":"Produksi ASI sudah berjalan (prolaktin normal), tetapi refleks pengeluaran/ejeksi ASI (let-down reflex) membutuhkan hormon Oksitosin dari neurohipofisis untuk mengontraksikan sel mioepitel mammae; stres akut (adrenalin/simpatis) dapat menghambat pelepasan oksitosin.","src":"kuis"},{"id":"9.6.0","topic":"Sistem Reproduksi","sub":"10.7 Teknologi Kontrasepsi, Infertilitas & Teknologi Berbantu (IVF)","kind":"pg","stem":"Mekanisme kerja utama kontrasepsi hormonal (pil KB kombinasi, suntik KB, maupun implan subdermal) dalam mencegah terjadinya kehamilan adalah…","options":["Mempertahankan kadar estrogen dan/atau progesteron sintetis di dalam darah untuk memberikan umpan balik negatif yang menekan sekresi FSH dan LH dari hipofisis, sehingga pematangan folikel dan ovulasi terhambat","Memicu lonjakan LH setiap hari agar seluruh sel telur habis terovulasi sekaligus","Menyumbat saluran tuba Fallopi dengan jaringan parut permanen","Membunuh seluruh sel oogonium di dalam ovarium secara permanen"],"key":[0],"why":"Hormon steroid eksogen (estrogen/progestin) meniru kondisi fase luteal/kehamilan, memberikan umpan balik negatif ke poros hipotalamus-hipofisis sehingga FSH dan LH tertekan dan ovulasi gagal terjadi.","src":"kuis"},{"id":"9.6.1","topic":"Sistem Reproduksi","sub":"10.7 Teknologi Kontrasepsi, Infertilitas & Teknologi Berbantu (IVF)","kind":"pg","stem":"Seorang wanita berusia 38 tahun telah menjalani prosedur sterilisasi Tubektomi (pemotongan dan pengikatan kedua tuba Fallopi). Kondisi fisiologis yang akan dialami wanita tersebut pada bulan-bulan berikutnya adalah…","options":["Ovulasi oosit sekunder dari ovarium serta siklus peluruhan dinding rahim (menstruasi) tetap berlangsung secara normal setiap bulan, namun sperma tidak dapat bertemu oosit","Korpus luteum tidak pernah terbentuk lagi karena hormon LH tidak dapat mencapai ovarium","Berhenti mengalami menstruasi (menopause dini) dan kadar hormon estrogennya menjadi nol","Pertumbuhan rambut wajah meningkat drastis akibat perubahan hormon"],"key":[0],"why":"Hormon FSH, LH, estrogen, dan progesteron diangkut melalui pembuluh darah, bukan melalui lumen tuba Fallopi. Karena ovarium dan rahim tetap utuh, ovulasi dan menstruasi tetap berjalan normal, hanya jalur pertemuan gamet di tuba yang terputus.","src":"kuis"},{"id":"9.6.2","topic":"Sistem Reproduksi","sub":"10.7 Teknologi Kontrasepsi, Infertilitas & Teknologi Berbantu (IVF)","kind":"pg","stem":"Pada teknologi bayi tabung (In Vitro Fertilization / IVF), tahapan perkembangan embrio hasil pembuahan di cawan petri yang paling optimal untuk ditransfer (dimasukkan kembali) ke dalam dinding endometrium rahim ibu adalah tahap…","options":["Janin yang sudah memiliki jantung dan plasenta lengkap","Oosit primer sebelum membelah","Zigot bersel tunggal sesaat setelah sperma masuk","Morula (8–16 sel) atau Blastokista (hari ke-3 hingga ke-5 pasca-fertilisasi)"],"key":[3],"why":"Zigot dikultur di laboratorium selama 3–5 hari hingga mencapai fase pembelahan 8 sel, morula, atau blastokista (fase alami yang siap melakukan implantasi/nidasi di endometrium uterus).","src":"kuis"},{"id":"9.7.0","topic":"Sistem Reproduksi","sub":"10.8 Gangguan Sistem Reproduksi & Infeksi Menular Seksual (IMS)","kind":"pg","stem":"Pasangan penyakit Infeksi Menular Seksual (IMS) dan agen mikroorganisme penyebabnya yang seluruhnya disebabkan oleh kelompok BAKTERI (sehingga dapat diterapi dengan antibiotik) adalah…","options":["Kanker serviks (HPV), AIDS (HIV), dan Herpes genitalis (HSV-2)","Gonore, Trikomoniasis, dan Kandidiasis vaginalis","Sifilis, Herpes genitalis, dan Kondiloma akuminata","Gonore (Neisseria gonorrhoeae), Sifilis (Treponema pallidum), dan Klamidia (Chlamydia trachomatis)"],"key":[3],"why":"Neisseria gonorrhoeae (diplokokus), Treponema pallidum (spirokaeta), dan Chlamydia trachomatis semuanya merupakan bakteri prokariotik. HSV-2, HPV, dan HIV adalah virus; Trichomonas adalah protozoa; Candida adalah jamur.","src":"kuis"},{"id":"9.7.1","topic":"Sistem Reproduksi","sub":"10.8 Gangguan Sistem Reproduksi & Infeksi Menular Seksual (IMS)","kind":"pg","stem":"Seorang wanita mengalami keluhan siklus menstruasi sangat jarang (oligomenore, 3–4 bulan sekali), peningkatan kadar hormon androgen (tumbuh rambut berlebih/hirsutisme dan jerawat), serta pemeriksaan USG menunjukkan banyak folikel kecil yang menggerombol di tepi ovarium seperti kalung mutiara karena gagal mencapai ovulasi. Kelainan endokrin-reproduksi ini disebut…","options":["Polycystic Ovary Syndrome (PCOS)","Mioma uteri","Endometriosis","Kanker ovarium"],"key":[0],"why":"PCOS ditandai oleh ketidakseimbangan rasio LH:FSH, hiperandrogenisme, dan resistensi insulin yang menyebabkan folikel gagal matang sempurna (anovulasi) dan tertahan sebagai kista-kista folikuler kecil di ovarium.","src":"kuis"},{"id":"9.7.2","topic":"Sistem Reproduksi","sub":"10.8 Gangguan Sistem Reproduksi & Infeksi Menular Seksual (IMS)","kind":"pg","stem":"Gejala klinis khas yang membedakan infeksi Sifilis stadium primer (akibat bakteri Treponema pallidum) dari Herpes genitalis (akibat virus HSV-2) adalah…","options":["Keduanya dapat disembuhkan tuntas dalam 1 hari dengan pemberian salep antijamur","Sifilis primer menyebabkan keputihan berbusa hijau, sedangkan Herpes menyebabkan kutil berbentuk jengger ayam","Sifilis primer ditandai dengan luka tunggal bersih bertepi keras yang TIDAK terasa nyeri (ulkus durum / chancre), sedangkan Herpes genitalis ditandai dengan bintil-bintil lepuh (vesikel) berkelompok yang SANGAT nyeri dan mudah kambuh","Sifilis disebabkan oleh virus yang bersembunyi di saraf, sedangkan Herpes disebabkan oleh bakteri"],"key":[2],"why":"Tanda patognomonik Sifilis stadium I adalah ulkus durum (chancre) yang tidak nyeri sehingga sering diabaikan pasien hingga lanjut ke stadium II/III; sebaliknya lesi vesikel HSV-2 sangat nyeri dan virusnya laten di ganglion saraf sakral.","src":"kuis"},{"id":"hots-h1","topic":"Keanekaragaman Hayati & Klasifikasi","sub":"HOTS · Indeks Dominansi & Kestabilan Komunitas Hutan","kind":"pg","title":"Indeks Dominansi & Kestabilan Komunitas Hutan","stem":"Komunitas Hutan A memiliki 3 spesies pohon masing-masing berjumlah 34, 33, dan 33 individu (Total N = 100). Komunitas Hutan B memiliki 3 spesies pohon dengan jumlah 90, 5, dan 5 individu (Total N = 100). Pernyataan kuantitatif yang tepat mengenai kedua komunitas tersebut adalah…","options":["Hutan A didominasi oleh satu spesies unggul yang menekan spesies lain","Hutan A memiliki kemerataan (E ≈ 1,0) dan nilai H' tertinggi (≈ 1,10), sedangkan Hutan B memiliki Indeks Dominansi (D ≈ 0,815) yang tinggi sehingga secara ekologis lebih rentan terhadap ledakan hama","Hutan B memiliki Indeks Keanekaragaman Shannon-Wiener (H') dan kemerataan (Evenness) yang lebih tinggi daripada Hutan A","Kedua hutan memiliki nilai H' dan Indeks Dominansi yang sama persis karena jumlah total individunya sama-sama 100"],"key":[1],"why":"Pada Hutan A proporsi tiap spesies merata (pᵢ ≈ 1/3) sehingga H' maksimum (ln 3 ≈ 1,10), E = 1, dan Dominansi D = 3×(1/3)² = 0,33 (rendah). Pada Hutan B satu spesies mendominasi 90% (D = 0,9² + 0,05² + 0,05² = 0,815 tinggi, H' = 0,39 rendah) sehingga jika hama menyerang spesies dominan, ekosistem Hutan B langsung runtuh.","src":"hots"},{"id":"hots-h2","topic":"Bakteri & Resistensi","sub":"HOTS · Sinergi Antibiotik dan Struktur Bakteri","kind":"pg","title":"Sinergi Antibiotik dan Struktur Bakteri","stem":"Seorang peneliti menguji tiga jenis mikroorganisme: (1) Staphylococcus aureus (Gram-positif), (2) Salmonella typhi (Gram-negatif), dan (3) Methanobacterium (Archaea penghuni rawa anaerob). Jika ketiganya diberi enzim Lisozim dan antibiotik Penisilin secara bersamaan dalam medium isotonik, manakah yang dinding selnya paling cepat mengalami kerusakan struktural?","options":["Methanobacterium, karena dinding sel Archaea tersusun atas peptidoglikan murni","Ketiganya langsung mengalami lisis dalam waktu yang sama persis","Salmonella typhi, karena membran luar lipopolisakarida mempercepat masuknya lisozim","Staphylococcus aureus, karena memiliki lapisan peptidoglikan tebal yang terbuka langsung tanpa perisai membran luar, sedangkan Methanobacterium kebal karena dindingnya pseudomurein (tanpa peptidoglikan)"],"key":[3],"why":"Penisilin (penghambat ikatan silang peptidoglikan) dan Lisozim (pemutus ikatan β-1,4 NAG-NAM peptidoglikan) bekerja paling efektif pada bakteri Gram-positif (S. aureus). Bakteri Gram-negatif terlindungi oleh membran luar LPS, sedangkan Archaea (Methanobacterium) sama sekali TIDAK memiliki peptidoglikan sehingga kebal terhadap penisilin dan lisozim!","src":"hots"},{"id":"hots-h3","topic":"Ekosistem Indonesia","sub":"HOTS · Piramida Biomassa Terbalik vs Aliran Energi Laut","kind":"pg","title":"Piramida Biomassa Terbalik vs Aliran Energi Laut","stem":"Hasil survei ekologi di perairan lepas Samudra Hindia menunjukkan biomassa kering sesaat (standing crop) fitoplankton hanya 5 g/m², sedangkan biomassa zooplankton yang memakannya mencapai 22 g/m². Mengapa piramida biomassa tersebut dapat terbalik tanpa melanggar Hukum II Termodinamika pada piramida energi?","options":["Karena piramida energi di ekosistem perairan juga ikut terbalik mengikuti piramida biomassa","Karena di ekosistem laut efisiensi transfer energi trofik mencapai 250% dari produsen ke konsumen I","Karena fitoplankton memiliki laju reproduksi dan pergantian generasi (turnover rate) yang sangat cepat sehingga total energi yang diproduksinya sepanjang tahun tetap jauh lebih besar (~10× lipat) daripada energi zooplankton","Karena zooplankton mampu berfotosintesis sendiri menggunakan energi panas air laut"],"key":[2],"why":"Piramida biomassa mengukur massa sesaat (standing crop); fitoplankton bersel tunggal membelah sangat cepat dan langsung dimakan zooplankton. Namun jika diukur aliran energinya per satuan luas per tahun (kkal/m²/tahun), produsen fitoplankton tetap menghasilkan energi ~10× lebih besar dari zooplankton (Piramida Energi TIDAK PERNAH terbalik!).","src":"hots"},{"id":"hots-h4","topic":"Enzim & Metabolisme Sel","sub":"HOTS · Eksperimen Kloroplas Terisolasi (Efek Jagendorf)","kind":"pg","title":"Eksperimen Kloroplas Terisolasi (Efek Jagendorf)","stem":"Kloroplas yang diisolasi ditempatkan dalam larutan asam bersuhu gelap gulita (pH 4,0) hingga lumen tilakoidnya mencapai pH 4,0. Kemudian kloroplas dipindahkan secara mendadak ke dalam larutan penyangga basa (pH 8,0) bersama ADP dan fosfat anorganik (Pᵢ) tetap dalam kondisi GELAP GULITA tanpa cahaya. Apa yang akan terjadi?","options":["Tidak ada ATP yang terbentuk karena enzim ATP sintase mutlak membutuhkan foton cahaya untuk berputar","ATP tetap berhasil disintesis oleh enzim ATP sintase karena telah terbentuk gradien konsentrasi H⁺ (selisih 4 unit pH = 10.000× lipat) antara lumen tilakoid dan stroma yang menggerakkan kemiosmosis","Siklus Calvin langsung menghasilkan glukosa meskipun tanpa CO₂ dan tanpa NADPH","Terbentuk gas oksigen (O₂) dalam jumlah besar akibat fotolisis air oleh perubahan pH"],"key":[1],"why":"Eksperimen klasik André Jagendorf ini membuktikan Teori Kemiosmosis Peter Mitchell: fungsi cahaya pada reaksi terang sebenarnya adalah memompa H⁺ ke lumen tilakoid. Jika gradien H⁺ (lumen pH 4 asam vs stroma pH 8 basa) diciptakan secara buatan, arus keluar H⁺ menuruni gradien melalui CF₀-CF₁ ATP sintase langsung menghasilkan ATP meskipun dalam gelap gulita!","src":"hots"},{"id":"hots-h5","topic":"Sistem Sirkulasi","sub":"HOTS · Paradoks Laju Aliran Darah di Kapiler","kind":"pg","title":"Paradoks Laju Aliran Darah di Kapiler","stem":"Sebuah percobaan hemodinamika mengukur bahwa satu pembuluh Aorta memiliki diameter 2,5 cm dengan kecepatan aliran darah 40 cm/detik, sedangkan satu pembuluh Kapiler memiliki diameter sangat sempit (hanya 8 μm). Namun ketika darah mengalir dari aorta menuju jaringan kapiler, kecepatan aliran darah di kapiler justru melambat drastis menjadi 0,05 cm/detik. Mengapa?","options":["Karena tekanan darah di dalam vena kava lebih tinggi daripada tekanan di dalam aorta","Karena darah di dalam kapiler membeku menjadi benang fibrin lalu mencair kembali di vena","Karena jantung berhenti memompa setiap kali darah tiba di jaringan kapiler","Karena menurut persamaan kontinuitas (Q = A<sub>total</sub> × v), jutaan percabangan kapiler memiliki LUAS PENAMPANG TOTAL gabungan yang jauh lebih besar (~4.500 cm²) dibandingkan satu aorta (~5 cm²), sehingga kecepatan aliran berbanding terbalik menjadi sangat lambat demi memberi waktu difusi O₂ dan nutrisi"],"key":[3],"why":"Jangan terkecoh melihat diameter 1 kapiler tunggal! Persamaan kontinuitas (v = Q / A<sub>total</sub>) menggunakan luas penampang TOTAL seluruh cabang paralel. Karena luas total seluruh kapiler tubuh ~900× luas aorta, laju aliran melambat drastis di kapiler agar pertukaran gas dan zat makanan berlangsung sempurna.","src":"hots"},{"id":"hots-h6","topic":"Sistem Respirasi","sub":"HOTS · Keracunan Karbon Monoksida (CO) vs Pemicu Napas","kind":"pg","title":"Keracunan Karbon Monoksida (CO) vs Pemicu Napas","stem":"Seorang penghuni kamar tertutup yang menyalakan genset mengalami keracunan gas Karbon Monoksida (CO). Anehnya, meskipun jaringan otaknya mengalami hipoksia berat yang mematikan, frekuensi napas korban pada awalnya tidak meningkat secara drastis dan kulitnya tidak tampak membiru (sianosis) melainkan merah ceri. Mengapa?","options":["Karena gas CO berikatan dengan Fe²⁺ hemoglobin ~240× lebih kuat daripada O₂ membentuk Karboksihemoglobin (HbCO) yang berwarna merah ceri, sementara tekanan parsial PCO₂ dan pH darah korban tetap normal sehingga kemoreseptor medula oblongata tidak terpicu kuat","Karena kemoreseptor di medula oblongata hanya peka terhadap kadar nitrogen di udara","Karena gas CO berubah menjadi gas oksigen di dalam alveolus paru-paru","Karena gas CO merangsang ginjal menghentikan produksi urin secara mendadak"],"key":[0],"why":"Pusat pernapasan di medula oblongata terutama diatur oleh kadar CO₂/H⁺ (pH cairan serebrospinal), sedangkan kemoreseptor perifer memantau PO₂ terlarut di plasma (bukan kandungan O₂ yang terikat Hb). Pada keracunan CO, PO₂ plasma terlarut dan PCO₂ masih normal meskipun hampir seluruh situs Fe²⁺ Hb telah dikunci oleh CO menjadi HbCO!","src":"hots"},{"id":"hots-h7","topic":"Sistem Ekskresi & Integrasi","sub":"HOTS · Analisis Klirens Ginjal & Selektivitas Nefron","kind":"pg","title":"Analisis Klirens Ginjal & Selektivitas Nefron","stem":"Seorang pasien menjalani pemeriksaan darah dan urin dengan hasil: kadar glukosa darah puasa = 90 mg/dL (normal), namun di dalam urin akhirnya ditemukan protein Albumin dalam jumlah tinggi (++ / Biuret ungu) disertai pembengkakan (edema) pada kedua tungkai kaki. Di manakah letak kerusakan anatomis ginjal pasien dan mengapa kakinya membengkak?","options":["Kerusakan pada Hati karena gagal mengubah amonia menjadi urea dalam Siklus Ornitin","Kerusakan pada Tubulus Kontortus Distal akibat kelebihan hormon ADH yang menyumbat pembuluh limfa kaki","Kerusakan pada sawar filtrasi Glomerulus (sel podosit/membran basal) sehingga albumin plasma bocor ke urin (Albuminuria); hilangnya albumin darah menurunkan tekanan osmotik koloid (onkotik) plasma sehingga cairan merembes keluar dari kapiler ke ruang antarsel jaringan (edema)","Kerusakan pada Lengkung Henle karena pasien terlalu banyak minum air putih"],"key":[2],"why":"Albumin di dalam darah berfungsi menjaga tekanan onkotik (osmotik koloid)约25–30 mmHg untuk menahan air tetap di dalam kapiler darah. Ketika glomerulus bocor (Sindrom Nefrotik / Glomerulonefritis), albumin terbuang lewat urin → tekanan onkotik darah anjlok → air berpindah dari kapiler ke jaringan interstisial memicu edema.","src":"hots"},{"id":"hots-h8","topic":"Sistem Imun","sub":"HOTS · Kegagalan Seleksi Negatif Timus & Penyakit Autoimun","kind":"pg","title":"Kegagalan Seleksi Negatif Timus & Penyakit Autoimun","stem":"Dalam proses pematangan limfosit T di kelenjar Timus, dilakukan dua tahap uji seleksi ketat (seleksi positif di korteks dan seleksi negatif di medula) yang memusnahkan sekitar 98% calon sel T melalui apoptosis. Apa konsekuensi klinis yang terjadi apabila tahap SELEKSI NEGATIF di medula timus mengalami kegagalan genetik?","options":["Sel NK kehilangan kemampuan membedakan sel bakteri Gram-positif dan Gram-negatif","Tubuh menjadi kebal terhadap seluruh jenis virus termasuk HIV tanpa memerlukan vaksinasi","Sel B di sumsum tulang berubah menjadi eritrosit penghasil hemoglobin","Sel T yang memiliki afinitas tinggi terhadap protein tubuh sehat sendiri (autoantigen) lolos ke sirkulasi darah dan menyerang jaringan tubuh sendiri, memicu penyakit AUTOIMUN (seperti Lupus, Diabetes Tipe 1, atau Multiple Sclerosis)"],"key":[3],"why":"Seleksi positif memastikan sel T mengenali molekul MHC tubuh sendiri; sedangkan Seleksi Negatif memusnahkan (apoptosis) klon sel T yang bereaksi kuat terhadap peptida diri sendiri (self-antigen). Jika seleksi negatif gagal, terjadilah hilangnya toleransi diri (loss of self-tolerance) → Penyakit Autoimun.","src":"hots"},{"id":"hots-h9","topic":"Sistem Koordinasi","sub":"HOTS · Umpan Balik Hormon Tiroid pada Gondok vs Penyakit Graves","kind":"pg","title":"Umpan Balik Hormon Tiroid pada Gondok vs Penyakit Graves","stem":"Pasien P menderita Gondok endemik akibat defisiensi iodium kronis (badan lesu, gemuk, tidak tahan dingin), sedangkan Pasien Q menderita Penyakit Graves autoimun (badan kurus, jantung berdebar cepat, mata menonjol/eksoftalmus, dan kelenjar tiroid juga membesar). Bagaimanakah perbandingan kadar hormon TSH (dari hipofisis anterior) dan Tiroksin (T₄) di dalam darah kedua pasien?","options":["Kedua pasien mengalami kerusakan pada hipofisis posterior penghasil ADH dan oksitosin","Pasien P memiliki T₄ RENDAH dan TSH SANGAT TINGGI (karena hilangnya umpan balik negatif T₄ ke hipofisis); sedangkan Pasien Q memiliki T₄ SANGAT TINGGI dan TSH SANGAT RENDAH (karena T₄ tinggi menekan hipofisis, sementara tiroid dipacu oleh autoantibodi TSI)","Pasien P memiliki TSH rendah dan T₄ tinggi; sedangkan Pasien Q memiliki TSH tinggi dan T₄ rendah","Kedua pasien sama-sama memiliki kadar TSH dan T₄ yang sangat tinggi di atas normal"],"key":[1],"why":"Pada Pasien P (kurang iodium), kegagalan sintesis T₄ menghilangkan rem umpan balik negatif ke adenohipofisis → TSH melonjak tinggi dan memicu hipertrofi tiroid (gondok hipotiroid). Pada Pasien Q (Graves), autoantibodi TSI meniru TSH memacu tiroid menghasilkan T₄ berlebih (hipertiroid) → T₄ yang sangat tinggi mengerem hipofisis sehingga TSH darah justru anjlok mendekati nol!","src":"hots"},{"id":"hots-h10","topic":"Sistem Reproduksi","sub":"HOTS · Peran Hormon hCG dan Pengangkatan Ovarium Saat Hamil","kind":"pg","title":"Peran Hormon hCG dan Pengangkatan Ovarium Saat Hamil","stem":"Pada eksperimen reproduksi mamalia dan kasus klinis kebidanan: jika Korpus Luteum ovarium seorang ibu hamil terpaksa diangkat melalui operasi pada usia kehamilan minggu ke-5 (Trimester I), ibu tersebut akan langsung mengalami keguguran. Namun jika operasi pengangkatan ovarium dilakukan pada usia kehamilan minggu ke-16 (Trimester II), kehamilan tetap berjalan normal hingga bayi lahir. Mengapa?","options":["Karena hormon FSH dan LH dari hipofisis janin menggantikan fungsi rahim ibu","Karena setelah minggu ke-16 janin tidak lagi membutuhkan dinding endometrium maupun aliran darah ibu","Karena pada minggu ke-5 hormon Progesteron penopang dinding endometrium masih bergantung penuh pada Korpus Luteum (yang dipertahankan oleh hormon hCG dari trofoblas), sedangkan pada minggu ke-16 organ PLASENTA telah matang dan mengambil alih produksi progesteron serta estrogen secara mandiri","Karena pada trimester kedua kelenjar tiroid ibu berubah fungsi menjadi penghasil hormon progesteron"],"key":[2],"why":"Selama 8–10 minggu pertama kehamilan, sel trofoblas embrio menyekresikan hCG untuk menjaga agar Korpus Luteum ovarium tidak luruh dan terus memproduksi progesteron. Mulai minggu ke-10–12 (Trimester II), plasenta telah berkembang sempurna untuk mensintesis progesteron sendiri dalam jumlah besar (luteo-placental shift).","src":"hots"}]};
